# roman.py
import re

def to_roman(n: int) -> str:
    """
    Converts an integer (1 to 3999) to its standard Roman numeral representation.

    Args:
        n: The integer to convert.

    Returns:
        The canonical uppercase Roman numeral string.

    Raises:
        TypeError: If n is not an int or is a bool.
        ValueError: If n is outside the range [1, 3999].
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("Input must be an integer.")

    if not (1 <= n <= 3999):
        raise ValueError("Input must be between 1 and 3999 inclusive.")

    mapping = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]

    result = []
    for value, symbol in mapping:
        while n >= value:
            result.append(symbol)
            n -= value

    return "".join(result)

def from_roman(s: str) -> int:
    """
    Converts a canonical Roman numeral string to its integer value.

    Args:
        s: The canonical uppercase Roman numeral string (e.g., 'MCMXCIV').

    Returns:
        The integer represented by the Roman numeral.

    Raises:
        TypeError: If s is not a str.
        ValueError: If s is not a valid, canonical Roman numeral string 
                    representable by to_roman().
    """
    if not isinstance(s, str):
        raise TypeError("Input must be a string.")

    # 1. Check for basic validity (uppercase, only valid characters)
    if not re.fullmatch(r'[IVXLCDM]+', s):
        raise ValueError(f"String '{s}' contains invalid characters or structure.")

    # 2. Check for canonical form and calculate value simultaneously
    # This loop handles the standard conversion logic while ensuring canonical rules are met implicitly.

    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    i = 0
    while i < len(s):
        current_val = roman_map[s[i]]

        if i + 1 < len(s):
            next_val = roman_map[s[i+1]]

            if current_val < next_val:
                # Subtractive case (IV, IX, XL, XC, CD, CM)
                # This structure ensures we only process valid subtractive pairs.
                # E.g., 'IC' (99) is invalid, but if the input passed the regex, 
                # we rely on the conversion logic to detect non-canonical forms later if necessary,
                # although the specific structure of Roman numeral conversion inherently checks for canonicality
                # if we restrict the allowed subtraction rules (only I before V/X, X before L/C, C before D/M).

                total += (next_val - current_val)
                i += 2
                continue
            else:
                total += current_val
                i += 1
        else:
            # Last character
            total += current_val
            i += 1

    # 3. Final strict validation against known valid outputs
    # Since the conversion logic above correctly calculates the value *if* it's canonical, 
    # the most robust way to ensure *only* canonical forms pass is to verify the result
    # by converting it back.
    try:
        canonical_roman = to_roman(total)
        if canonical_roman != s:
            # This catches forms like 'IIII' (value 4, canonical 'IV'), 'VV' (value 10, canonical 'X'), etc.
            raise ValueError
    except ValueError:
        # If to_roman raises ValueError (though total is likely <= 3999), or if the check fails
        raise ValueError

    return total

if __name__ == '__main__':
    print("--- Testing to_roman ---")
    try:
        print(f"to_roman(3): {to_roman(3)}")       # III
        print(f"to_roman(4): {to_roman(4)}")       # IV
        print(f"to_roman(9): {to_roman(9)}")       # IX
        print(f"to_roman(58): {to_roman(58)}")     # LVIII
        print(f"to_roman(1994): {to_roman(1994)}") # MCMXCIV
        print(f"to_roman(3999): {to_roman(3999)}") # MMMCMXCIX

        # Error testing
        try: to_roman(4000)
        except ValueError as e: print(f"Caught expected error for 4000: {e}")
        try: to_roman(0)
        except ValueError as e: print(f"Caught expected error for 0: {e}")
        try: to_roman(3.14)
        except TypeError as e: print(f"Caught expected error for float: {e}")
        try: to_roman(True)
        except TypeError as e: print(f"Caught expected error for bool: {e}")

    except Exception as e:
        print(f"Unexpected error during to_roman test: {e}")

    print("\n--- Testing from_roman ---")
    try:
        print(f"from_roman('MCMXCIV'): {from_roman('MCMXCIV')}") # 1994
        print(f"from_roman('MMMCMXCIX'): {from_roman('MMMCMXCIX')}") # 3999
        print(f"from_roman('III'): {from_roman('III')}") # 3

        # Error testing

        # Non-string
        try: from_roman(123)
        except TypeError as e: print(f"Caught expected error for int: {e}")

        # Invalid characters/structure
        try: from_roman("MCMX")
        except ValueError as e: print(f"Caught expected error for invalid char/structure: {e}")

        try: from_roman("")
        except ValueError as e: print(f"Caught expected error for empty string: {e}")

        # Non-canonical forms
        try: from_roman("IIII") # 4, but canonical is IV
        except ValueError as e: print(f"Caught expected error for IIII: {e}")

        try: from_roman("VV") # 10, but canonical is X
        except ValueError as e: print(f"Caught expected error for VV: {e}")

        try: from_roman("VX") # Non-canonical subtraction
        except ValueError as e: print(f"Caught expected error for VX: {e}")

        try: from_roman("CMCM") # Invalid sequence
