```python
# semver.py
import re
from functools import total_ordering
from typing import Tuple, Union, List

# --- Utility Functions and Constants ---

SEMVER_REGEX = re.compile(
    r"^(?P<major>0|[1-9]\d*)\."
    r"(?P<minor>0|[1-9]\d*)\."
    r"(?P<patch>0|[1-9]\d*)"
    r"(?:-(?P<prerelease>([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)))?"
    r"(?:\+(?P<build>([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)))?$"
)

PRERELEASE_IDENTIFIER_REGEX = re.compile(r"^[0-9A-Za-z-]+$")
BUILD_IDENTIFIER_REGEX = re.compile(r"^[0-9A-Za-z-]+$")

def parse_identifiers(identifier_string: str) -> List[str]:
    """Parses dot-separated identifiers into a list, validating each one."""
    if not identifier_string:
        return []
    return identifier_string.split('.')

# --- Version Class ---

@total_ordering
class Version:
    """
    Represents a Semantic Version (MAJOR.MINOR.PATCH-PRERELEASE+BUILD).
    Comparison follows SemVer 2.0.0 rules.
    """
    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[str, ...] = (), build: Tuple[str, ...] = ()):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease
        self.build = build

    @classmethod
    def _validate_identifier(cls, identifier: str, is_numeric: bool) -> None:
        """Validates a single identifier segment."""
        if not identifier:
            raise ValueError("Empty identifier found.")
        if not PRERELEASE_IDENTIFIER_REGEX.match(identifier):
            raise ValueError(f"Invalid identifier format: {identifier}")

        if is_numeric:
            # Numeric identifiers must not have leading zeros (unless the value is '0')
            if len(identifier) > 1 and identifier.startswith('0'):
                raise ValueError("Numeric pre-release identifier must not have leading zeros.")

    @classmethod
    def parse(cls, text: str) -> 'Version':
        """
        Parses a full SemVer string into a Version object.
        """
        if not isinstance(text, str):
            raise TypeError("Input must be a string.")

        text = text.strip()
        if not text:
            raise ValueError("Input string cannot be empty.")

        match = SEMVER_REGEX.fullmatch(text)
        if not match:
            raise ValueError(f"Invalid SemVer format: {text}")

        data = match.groupdict()

        # Parse core version numbers
        try:
            major = int(data['major'])
            minor = int(data['minor'])
            patch = int(data['patch'])
        except ValueError:
            # Should be caught by regex, but good for robustness
            raise ValueError("Major, minor, or patch segment is not a valid integer.")

        # Parse prerelease
        prerelease_ids = []
        if data['prerelease']:
            identifiers = parse_identifiers(data['prerelease'])
            for identifier in identifiers:
                try:
                    is_numeric = identifier.isdigit()
                    cls._validate_identifier(identifier, is_numeric)
                    prerelease_ids.append(identifier)
                except ValueError as e:
                    raise ValueError(f"Invalid pre-release identifier in '{data['prerelease']}': {e}")

        # Parse build metadata (ignored for comparison, but stored for canonical string)
        build_ids = []
        if data['build']:
            identifiers = parse_identifiers(data['build'])
            for identifier in identifiers:
                try:
                    # Build identifiers can have leading zeros
                    cls._validate_identifier(identifier, is_numeric=False) 
                    build_ids.append(identifier)
                except ValueError as e:
                    raise ValueError(f"Invalid build identifier in '{data['build']}': {e}")

        v = cls(major, minor, patch, tuple(prerelease_ids), tuple(build_ids))

        # The canonical string MUST be the text it was parsed from, including the original build metadata
        # This satisfies the requirement: "str(v) gives the canonical text, which for a parsed version is the text it was parsed from."
        v._original_text = text
        return v

    def __new__(cls, major: int, minor: int, patch: int, prerelease: Tuple[str, ...] = (), build: Tuple[str, ...] = ()):
        # Optimization: If we are creating a version internally (e.g., from bump), we don't need to store original text.
        if hasattr(cls, '_original_text') and cls._original_text is not None:
             # This path is taken only if __init__ is called directly on an object that was previously instantiated.
             # In our usage, we ensure this doesn't happen for simple instantiation.
             pass

        instance = super().__new__(cls)
        instance.major = major
        instance.minor = minor
        instance.patch = patch
        instance.prerelease = prerelease
        instance.build = build
        return instance

    def __init__(self, major: int, minor: int, patch: int, prerelease: Tuple[str, ...] = (), build: Tuple[str, ...] = ()):
        # Only initialize if we haven't already set the canonical text from parse()
        if not hasattr(self, '_original_text') or self._original_text is None:
            self.major = major
            self.minor = minor
            self.patch = patch
            self.prerelease = prerelease
            self.build = build
            self._original_text = f"{major}.{minor}.{patch}" + \
                                (f"-{''.join(self.prerelease)}").replace('"', '') if prerelease else "" + \
                                (f"+{''.join(self.build)}").replace('"', '') if build else ""
        else:
            # If _original_text exists, we are a result of a bump/internal modification, 
            # and the attributes are already set by __new__ or the caller.
            pass

    def __str__(self) -> str:
        """Returns the canonical text it was parsed from."""
        return self._original_text if hasattr(self, '_original_text') and self._original_text is not None else self._to_string_canonical()

    def _to_string_canonical(self) -> str:
        """Generates the string representation based on current state (used for bumped versions)."""
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += f"-{'.'.join(self.prerelease)}"
        if self.build:
            s += f"+{'.'.join(self.build)}"
        return s

    def __repr__(self) -> str:
        return f"Version({self.major}, {self.minor}, {self.patch}, {self.prerelease}, {self.build})"

    def __eq__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented

        # Build metadata is ignored for equality
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self.prerelease == other.prerelease)

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __lt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) < 0

    def __le__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) <= 0

    def __gt__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) > 0

    def __ge__(self, other) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) >= 0

    def _compare(self, other: 'Version') -> int:
        """
        Compares self to other.
        Returns -1 if self < other, 0 if self == other, 1 if self > other.
        """
        # 1. Compare Major, Minor, Patch numerically
        if self.major != other.major:
            return 1 if self.major > other.major else -1
        if self.minor != other.minor:
            return 1 if self.minor > other.minor else -1
        if self.patch != other.patch:
            return 1 if self.patch > other.patch else -1

        # 2. Compare Prerelease
        self_prerelease = self.prerelease
        other_prerelease = other.prerelease

        if not self_prerelease and not other_prerelease:
            return 0 # Equal
        if not self_prerelease and other_prerelease:
            return 1 # Version without prerelease is greater
        if self_prerelease and not other_prerelease:
            return -1 # Version with prerelease is smaller

        # Both have prereleases, compare identifiers left-to-right

        len_self = len(self_prerelease)
        len_other = len(other_prerelease)

        for i in range(min(len_self, len_other)):
            s_id = self_prerelease[i]
            o_id = other_prerelease[i]

            is_s_num = s_id.isdigit()
            is_o_num = o_id.isdigit()

            if is_s_num and is_o_num:
                # Both numeric: compare numerically
                s_val = int(s_id)
                o_val = int(o_id)
                if s_val != o_val:
                    return 1 if s_val > o_val else -1
            elif not is_s_num and not is_o_num:
                # Both alphanumeric: compare lexicographically (ASCII order)
                if s_id != o_id:
                    return 1 if s_id > o_id else -1
            else:
                # Mixed type comparison: Numeric is lower than alphanumeric
                if is_s_num and not is_o_num:
                    return -1 # Numeric < Alphanumeric
                if not is_s_num and is_o_num:
                    return 1  # Alphanumeric > Numeric

        # If all common identifiers are equal, the shorter list is lower
        if len_self != len_other:
            return 1 if len_self > len_other else -1

        return 0 # Equal

    def bump(self, kind: str) -> 'Version':
        """
        Increments the specified version component and resets prerelease/build.
        """
        kind = kind.lower()
        if kind not in ('major', 'minor', 'patch'):
            raise ValueError(f"Invalid bump kind: {kind}. Must be 'major', 'minor', or 'patch'.")

        new_major, new_minor, new_patch = self.major, self.minor, self.patch

        if kind == 'major':
            new_major += 1
            new_minor = 0
            new_patch = 0
        elif kind == 'minor':
            new_minor += 1
            new_patch = 0
        elif kind == 'patch':
            new_patch += 1

        # Bumped versions always have no prerelease or build metadata
        return Version(new_major, new_minor, new_patch)

# --- Version Range Satisfaction ---

def _parse_partial_version(text: str) -> Version:
    """Parses a version string, treating it as MAJOR.MINOR.PATCH.0 if parts are missing."""
    match = SEMVER_REGEX.match(text)
    if not match:
        # Partial versions cannot have prerelease or build metadata
        if re.fullmatch(r"(\d+|\d+\.\d*)", text):
            parts = text.split('.')

            major = int(parts[0]) if len(parts) >= 1 else 0
            minor = int(parts[1]) if len(parts) >= 2 else 0
            patch = 0

            # If only major is given (e.g., "1"), treat as 1.0.0
            if len(parts) == 1:
                return Version(major, 0, 0)
            # If major.minor is given (e.g., "1.2"), treat as 1.2.0
            elif len(parts) == 2:
                return Version(major, minor, 0)
            # If major.minor.patch is given
            elif len(parts) == 3:
                return Version(major, minor, int(parts[2]))

        raise ValueError(f"Invalid or malformed version string or partial version: {text}")

    # If it matched the full regex, we parse it fully, but we must normalize it
    # for range checking: strip prerelease/build for comparison purposes only.
    data = match.groupdict()

    major = int(data['major'])
    minor = int(data['minor'])
    patch = int(data['patch'])

    # Partial versions MUST NOT have prerelease or build parts according to spec.
    if data['prerelease'] or data['build']:
        raise ValueError(f"Partial version specifier cannot contain prerelease or build metadata: {text}")

    return Version(major, minor, patch)


def _calculate_caret_range(v: Version) -> Tuple[Version, Version]:
    """Calculates the range for ^V."""
    if v.major == 0 and v.minor == 0 and v.patch == 0:
        # ^0.0.X is equivalent to >=0.0.X <0.0.(X+1) if X>0, otherwise >=0.0.X <0.0.1
        if v.patch == 0:
             # ^0.0.0 is tricky, often means >=0.0.0 <0.0.1, but let's follow the rule: 
             # "^0.0.3 is >=0.0.3 <0.0.4"
             upper_bound = Version(0, 0, v.patch + 1)
        else:
             upper_bound = Version(0, 0, v.patch + 1)
    elif v.major == 0:
        # ^0.Y.Z is equivalent to >=0.Y.Z <0.(Y+1).0
        upper_bound = Version(0, v.minor + 1, 0)
    else:
        # ^X.Y.Z is equivalent to >=X.Y.Z <(X+1).0.0
        upper_bound = Version(v.major + 1, 0, 0)

    lower_bound = v
    return lower_bound, upper_bound

def _calculate_tilde_range(v: Version) -> Tuple[Version, Version]:
    """Calculates the range for ~V."""
    if v.major == 0 and v.minor == 0 and v.patch == 0:
        # ~0.0.X is equivalent to >=0.0.X <0.0.(X+1)
        upper_bound = Version(0, 0, v.patch + 1)
    elif v.major == 0:
        # ~0.Y.Z is equivalent to >=0.Y.Z <0.(Y+1).0
        upper_bound = Version(0, v.minor + 1, 0)
    else:
        # ~X.Y.Z is equivalent to >=X.Y.Z <X.(Y+1).0
        upper_bound = Version(v.major, v.minor + 1, 0)

    lower_bound = v
    return lower_bound, upper_bound


def satisfies(version: Union[Version, str], spec: str) -> bool:
    """
    Checks if a version (or version string) satisfies a complex specification string.
    """
    if not spec:
        raise ValueError("Specification string cannot be empty.")

    # 1. Normalize version input
    if isinstance(version, str):
        try:
            v = Version.parse(version)
        except ValueError as e:
            raise ValueError(f"Version input '{version}' is invalid: {e}")
    elif isinstance(version, Version):
        v = version
    else:
        raise TypeError("Version must be a Version object or a string.")

    # 2. Split and parse comparators
    spec_parts = spec.strip().split()

    satisfied_by_all = True

    for spec_part in spec_parts:
        comparator = spec_part[0]
        version_str = spec_part[1:] if len(spec_part) > 1 and spec_part[1] not in ('<', '>', '=', '!', '^', '~') else spec_part[0]

        # Determine the comparison version (V)
        if comparator in ('^', '~'):
            # Special range operators use the rest of the spec_part as V
            range_spec = spec_part[1:]
            if not range_spec:
                 raise ValueError(f"Range operator {comparator} requires a version.")

            try:
                v_spec = _parse_partial_version(range_spec.strip())
            except ValueError as e:
                raise ValueError(f"Invalid version for range spec '{range_spec}': {e}")

            if comparator == '^':
                lower, upper = _calculate_caret_range(v_spec)
                # Check: >= Lower AND < Upper
                if not (v >= lower and v < upper):
                    satisfied_by_all = False
                    break
                continue # Move to next spec_part

            elif comparator == '~':
                lower, upper = _calculate_tilde_range(v_spec)
                # Check: >= Lower AND < Upper
                if not (v >= lower and v < upper):
                    satisfied_by_all = False
                    break
                continue # Move to next spec_part

        # Standard comparisons: >=V, >V, <=V, <V, =V, V
        operator = comparator

        try:
            if operator in ('=', '<', '>', '!', '<=', '>='):
                # Explicit comparator, V is the next token
                v_spec = Version.parse(spec_part[1])
            elif operator.isdigit() or ('.' in operator and operator.replace('.', '').isdigit()):
                # Bare version V (implies =V)
                v_spec = _parse_partial_version(spec_part)
                operator = '='
            else:
                # This case should be covered above, but as a safeguard:
                raise ValueError("Malformed comparator.")
        except IndexError:
            raise ValueError(f"Missing version specifier for operator {operator}.")
        except ValueError as e:
            raise ValueError(f"Invalid version string in spec '{spec_part}': {e}")


        # Perform comparison based on operator
        comparison_result = 0 # Assume equal if operator is '='

        if operator == '=':
            comparison_result = (v == v_spec)
        elif operator == '>':
            comparison_result = (v > v_spec)
        elif operator == '<':
            comparison_result = (v < v_spec)
        elif operator == '>=':
            comparison_result = (v >= v_spec)
        elif operator == '<=':
            comparison_result = (v <= v_spec)
        elif operator == '!': # Should be '!==' or similar, but based on prompt, we assume != if only '!' is used (though this is ambiguous)
             # Assuming '!=' behavior if only '!' is passed, otherwise requires '!='
             if spec_part.startswith('!=='):
                 comparison_result = (v != v_spec)
             else:
                 # If it was just '!' it's malformed according to standard semver ranges, but we treat it as failure if not recognized
                 satisfied_by_all = False
                 break

        if not comparison_result:
            satisfied_by_all = False
            break

    return satisfied_by_all

# --- Example Usage and Tests (Self-Verification) ---
if __name__ == '__main__':
    print("--- Testing Version Parsing and Comparison ---")

    # 1. Basic Parsing
    v1 = Version.parse("1.2.3")
    print(f"Parsed 1.2.3: {v1}, Major={v1.major}")

    # 2. Complex Parsing
    v2 = Version.parse("1.2.3-rc.1+exp.7")
    print(f"Parsed 1.2.3-rc.1+exp.7: {v2}, Pre={v2.prerelease}")

    v3 = Version.parse("2.0.0-alpha")
    print(f"Parsed 2.0.0-alpha: {v3}, Pre={v3.prerelease}")

    # 3. Comparison Tests
    v1_eq = Version.parse("1.2.3")
    v1_neq = Version.parse("1.2.4")

    print(f"\n1.2.3 == 1.2.3? {v1 == v1_eq}")
    print(f"1.2.3 == 1.2.4? {v1 == v1_neq}")

    # Precedence Test: Pre-release vs Normal
    v_pre = Version.parse("1.2.3-beta")
    v_base = Version.parse("1.2.3")
    print(f"1.2.3-beta < 1.2.3? {v_pre < v_base}")

    # Precedence Test: Prerelease Identifier comparison
    v_rc1 = Version.parse("1.0.0-rc.1")
    v_rc2 = Version.parse("1.0.0-rc.2")
    print(f"rc.1 < rc.2? {v_rc1 < v_rc2}") # Numeric comparison

    v_beta = Version.parse("1.0.0-beta")
    v_rc = Version.parse("1.0.0-rc")
    print(f"beta < rc? {v_beta < v_rc}") # ASCII comparison ('b' < 'r')

    # Build metadata ignored
    v_build_a = Version.parse("1.0.0+a")
    v_build_b = Version.parse("1.0.0+b")
    print(f"Build A == Build B? {v_build_a == v_build_b}")

    # 4. Bump Tests
    v_patch = v1.bump('patch')
    print(f"\n1.2.3 bumped patch: {v_patch}")
    v_major = v1.bump('major')
    print(f"1.2.3 bumped major: {v_major}")

    # 5. Range Satisfaction Tests
    print("\n--- Testing Range Satisfaction ---")

    # Full Version Check
    assert satisfies(Version.parse("1.2.3"), ">=1.2.0") == True
