            levels_map[lvl] = []
        levels_map[lvl].append(node)

    # 4. Format output: list of lists, sorted by level number, and inner lists sorted lexicographically
    result = []
    sorted_levels = sorted(levels_map.keys())

    for lvl in sorted_levels:
        # Ensure inner list is lexicographically sorted
        result.append(sorted(levels_map[lvl]))

