def subgraph_order(graph: dict[str, iter], targets: iter) -> list[str]:
    """
    Returns the topological order for the minimal subgraph required to build the target nodes.

    Args:
        graph: The dependency graph.
        targets: An iterable of nodes to include in the required subgraph.

    Returns:
        The topological sort of the required nodes and their dependencies.

    Raises:
        KeyError: If any target node does not exist in the overall graph.
        CycleError: If a cycle exists within the required subgraph.
    """

    if not targets:
        return []

    target_set = set(targets)
    all_required_nodes = set()

    # 1. Find all required nodes (targets + all their ancestors)
    queue = list(target_set)

    while queue:
        current = queue.pop(0)
        all_required_nodes.add(current)

        # Check if the node exists in the overall graph structure
        if current not in {n for n in graph.keys()} and current not in {dep for deps in graph.values() for dep in deps}:
             raise KeyError(f"Target node '{current}' not found in graph nodes.")

        # Add all dependencies of the current node
        if current in graph:
            for dep in graph[current]:
                if dep not in all_required_nodes:
                    all_required_nodes.add(dep)
                    queue.append(dep)

    # 2. Construct the induced subgraph structure for the required nodes
    required_graph: dict[str, iter] = {}

    # Only include edges where BOTH the source and the target are required nodes
    for node in all_required_nodes:
        deps = graph.get(node, [])
        required_deps = [dep for dep in deps if dep in all_required_nodes]
        required_graph[node] = required_deps

    # 3. Perform topological sort on the induced subgraph
    # We reuse the logic from toposort, but restricted to all_required_nodes.

    # 3a. Calculate in-degrees within the required subgraph
    in_degree: dict[str, int] = {node: 0 for node in all_required_nodes}
    successors: dict[str, set[str]] = {node: set() for node in all_required_nodes}

    for node, deps_list in required_graph.items():
        for dep in deps_list:
            # dep is a prerequisite for node
            in_degree[node] += 1
            successors[dep].add(node)

    import heapq

    pq = []
    for node in all_required_nodes:
        if in_degree[node] == 0:
            heapq.heappush(pq, node)

    sorted_list: list[str] = []

    while pq:
        u = heapq.heappop(pq)
        sorted_list.append(u)

        # Iterate over successors *within the required set*
        for v in successors[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(pq, v)

    # 4. Cycle Detection within the required subgraph
    if len(sorted_list) != len(all_required_nodes):
        # Cycle exists among the needed nodes. Use DFS cycle detection tailored to the induced subgraph.
        visited = {node: 0 for node in all_required_nodes}
        cycle_nodes: list[str] = []

        def dfs_cycle_finder_subgraph(node: str, path_stack: list[str]):
            nonlocal cycle_nodes
            if cycle_nodes: return
            visited[node] = 1
            path_stack.append(node)

            deps = required_graph.get(node, [])

            for neighbor in deps:
                if visited[neighbor] == 1:
                    try:
                        start_index = path_stack.index(neighbor)
                        cycle_nodes = path_stack[start_index:]
                    except ValueError: pass
                    return

                if visited[neighbor] == 0:
                    dfs_cycle_finder_subgraph(neighbor, path_stack)
                    if cycle_nodes: return

