    if isinstance(final_segment, str):
        if not isinstance(parent_obj, Mapping):
            raise PathError(f"Cannot set key '{final_segment}' on non-mapping object", path_str)
        parent_obj[final_segment] = final_value

    elif isinstance(final_segment, int):
        if not isinstance(parent_obj, (list, tuple)):
            raise PathError(f"Cannot set index {final_segment} on non-list object", path_str)

        idx = final_segment

        # Handle appending (only if index == len)
        if idx == len(parent_obj):
            parent_obj.append(final_value)
        elif -len(parent_obj) <= idx < len(parent_obj):
            parent_obj[idx] = final_value
        else:
            raise PathError(f"Index {idx} out of bounds for setting", path_str)


# --- Delete Logic ---

def delete(obj: Any, path: str) -> Any:
    """
    Removes the value at path from its parent and returns the removed value.
    """
    segments = parse(path)
    path_str = path

    if not segments:
        raise PathError("Path cannot be empty for deletion.", path_str)

    if WILDCARD in segments:
        raise PathError("Wildcards are not supported for deletion.", path_str)

    parent_segments = segments[:-1]
    target_segment = segments[-1]

    # 1. Traverse to the parent object
    parent_obj = obj

    try:
        for i, segment in enumerate(parent_segments):

            if isinstance(segment, str):
                if not isinstance(parent_obj, Mapping) or segment not in parent_obj:
                    raise PathError(f"Parent object missing key '{segment}'", path_str)
                parent_obj = parent_obj[segment]

            elif isinstance(segment, int):
                if not isinstance(parent_obj, (list, tuple)):
                    raise PathError(f"Parent object is not a list/tuple for index {segment}", path_str)

                idx = segment
                if -len(parent_obj) <= idx < len(parent_obj):
                    parent_obj = parent_obj[idx]
                else:
                    raise PathError(f"Index {idx} out of range during parent traversal", path_str)
    except PathError:
        # Re-raise existing path errors
        raise
    except Exception:
        raise PathError("Structural error during parent traversal for deletion", path_str)


    # 2. Perform deletion from parent_obj using target_segment

    if isinstance(target_segment, str):
        if not isinstance(parent_obj, Mapping):
            raise PathError(f"Parent object is not a mapping for key '{target_segment}'", path_str)
        if target_segment not in parent_obj:
            raise PathError(f"Key '{target_segment}' not found for deletion", path_str)

        deleted_value = parent_obj[target_segment]
        del parent_obj[target_segment]
        return deleted_value

    elif isinstance(target_segment, int):
        if not isinstance(parent_obj, (list, tuple)):
            raise PathError(f"Parent object is not a list/tuple for index {target_segment}", path_str)

        idx = target_segment
        if -len(parent_obj) <= idx < len(parent_obj):
            deleted_value = parent_obj[idx]
            del parent_obj[idx]
            return deleted_value
        else:
            raise PathError(f"Index {idx} out of range for deletion", path_str)

