    count = 0

    def find_empty(g):
        for r in range(9):
            for c in range(9):
                if g[r][c] == 0:
                    return r, c
        return None

    # Create a copy of the grid to modify during search
    import copy
    initial_grid = copy.deepcopy(grid)

    def solve_recursive(current_grid):
        nonlocal count
        if count >= limit:
            return

        find = find_empty(current_grid)
        if not find:
            # Found a solution
            count += 1
            return

        r, c = find

        for num in range(1, 10):
