        return set()

    used = set()
    # Check row
    for val in grid[r]:
        if val != 0:
            used.add(val)
    # Check column
    for i in range(9):
        if grid[i][c] != 0:
            used.add(grid[i][c])
    # Check box
    start_row, start_col = (r // 3) * 3, (c // 3) * 3
    for i in range(start_row, start_row + 3):
        for j in range(start_col, start_col + 3):
            if grid[i][j] != 0:
                used.add(grid[i][j])

    return set(range(1, 10)) - used

def hint(grid: list[list[int]]) -> tuple[int, int, int, str] | None:
