    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                empty_cells.append((r, c))

    if not empty_cells:
        # Grid is complete
        return None

    # 1. Check for Naked Singles
    for r, c in empty_cells:
        candidates = _get_candidates(grid, r, c)
        if len(candidates) == 1:
            digit = candidates.pop()
            return (r, c, digit, 'naked single')

    # 2. Check for Hidden Singles

    # A. Rows
    for r in range(9):
        # Track candidates present in empty cells of this row
        candidates_in_row_cells = {d: [] for d in range(1, 10)}
        for c in range(9):
            if grid[r][c] == 0:
                candidates = _get_candidates(grid, r, c)
                for d in candidates:
                    candidates_in_row_cells[d].append((r, c))

        for d in range(1, 10):
            positions = candidates_in_row_cells[d]
            # If digit d is a candidate only in one cell of this row
            if len(positions) == 1:
                # We must also ensure this cell is actually empty (it should be, given the loop structure)
                r_found, c_found = positions[0]
                if grid[r_found][c_found] == 0:
                    return (r_found, c_found, d, 'hidden single in row')

    # B. Columns
    for c in range(9):
        candidates_in_col_cells = {d: [] for d in range(1, 10)}
        for r in range(9):
            if grid[r][c] == 0:
                candidates = _get_candidates(grid, r, c)
                for d in candidates:
                    candidates_in_col_cells[d].append((r, c))

        for d in range(1, 10):
            positions = candidates_in_col_cells[d]
            if len(positions) == 1:
                r_found, c_found = positions[0]
                if grid[r_found][c_found] == 0:
                    return (r_found, c_found, d, 'hidden single in column')

    # C. Boxes
    for box_idx in range(9):
        start_row, start_col = (box_idx // 3) * 3, (box_idx % 3) * 3

        candidates_in_box_cells = {d: [] for d in range(1, 10)}

        for r_offset in range(3):
            for c_offset in range(3):
                r, c = start_row + r_offset, start_col + c_offset
                if grid[r][c] == 0:
                    candidates = _get_candidates(grid, r, c)
                    for d in candidates:
                        candidates_in_box_cells[d].append((r, c))

        for d in range(1, 10):
            positions = candidates_in_box_cells[d]
            if len(positions) == 1:
                r_found, c_found = positions[0]
                if grid[r_found][c_found] == 0:
                    return (r_found, c_found, d, 'hidden single in box')

    return None


def difficulty(grid: list[list[int]]) -> dict[str, int] | None:
    """
    Attempts to solve the grid using only hint logic. 
    Returns the count of naked and hidden steps, or None if guessing is required.
    """
    try:
        _validate_grid(grid)
    except ValueError as e:
        raise ValueError(f"Invalid grid shape for difficulty assessment: {e}")

    current_grid = copy.deepcopy(grid)
    naked_count = 0
    hidden_count = 0

    while True:
        step = hint(current_grid)

        if step is None:
            # No more logical steps can be found
            if is_valid(current_grid):
                # Check if it's complete
                if all(all(cell != 0 for cell in row) for row in current_grid):
                    return {'naked': naked_count, 'hidden': hidden_count}
                else:
                    # Grid is partially solved but stuck (needs guessing)
                    return None
            else:
                # Grid state is invalid (shouldn't happen if previous hints were valid, 
                # but necessary if the initial grid was invalid and passed the first check, 
                # or if hint fails mid-solve due to internal inconsistency)
                return None

        r, c, digit, reason = step

        if reason == 'naked single':
            naked_count += 1
        elif 'hidden single' in reason:
            hidden_count += 1

        # Apply the hint
        current_grid[r][c] = digit

