import json
import os
from pathlib import Path
from typing import List, Optional, Tuple
from todo.model import Task, Task as ModelTask
from todo.model import Task as TaskType # Alias to avoid conflict

class StoreError(Exception):
    pass

class TodoStore:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self._tasks: Dict[int, ModelTask] = {}
        self.next_id: int = 1
        self._load()

    def _load(self):
        if not self.path.exists():
            self.tasks_data = {"version": 1, "next_id": 1, "tasks": []}
            return

        try:
            with open(self.path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except json.JSONDecodeError:
            raise StoreError(f"File is not valid JSON: {self.path}")
        except Exception as e:
            raise StoreError(f"Could not read or open file {self.path}: {e}")

        if data.get("version") != 1:
            raise StoreError(f"Unsupported store version: {data.get('version')}")

        next_id_from_file = data.get("next_id", 1)
        tasks_list = data.get("tasks", [])

        loaded_tasks: Dict[int, ModelTask] = {}
        max_id = 0

        for item in tasks_list:
            try:
                task = ModelTask.from_dict(item)

                # Validation checks: ID must be below next_id, and no ID reused
                if task.id >= next_id_from_file:
                    raise StoreError(f"Task ID {task.id} is equal to or greater than stored next_id {next_id_from_file}.")
                if task.id in loaded_tasks:
                    raise StoreError(f"Duplicate task ID found: {task.id}.")

                loaded_tasks[task.id] = task
                max_id = max(max_id, task.id)

            except ValueError as e:
                # This catches validation errors from ModelTask.from_dict
                raise StoreError(f"Invalid task data format: {e}") from e

        self._tasks = loaded_tasks
        self.next_id = next_id_from_file

        # Ensure next_id is greater than any existing ID, in case file was manually edited
        if self._tasks:
            self.next_id = max(self.next_id, max(self._tasks.keys()) + 1)

    def _save(self) -> None:
        """Writes the current state to the file atomically."""

        # Sort tasks by ID for consistent storage
        sorted_tasks = sorted(self._tasks.values(), key=lambda t: t.id)
        tasks_dict_list = [t.to_dict() for t in sorted_tasks]

        data = {
            "version": 1,
            "next_id": self.next_id,
            "tasks": tasks_dict_list
        }

        temp_path = self.path.with_suffix(self.path.suffix + ".tmp")

        try:
            with open(temp_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=4)

            os.replace(temp_path, self.path)
        except Exception as e:
            # Clean up temp file if replace failed
            if temp_path.exists():
                temp_path.unlink()
            raise StoreError(f"Failed to write to store file {self.path}: {e}")


    # --- Public API Methods ---

    def add(self, title: str, tags: Tuple[str, ...] = ()) -> ModelTask:
        try:
            normalized_title = ModelTask.normalize_title(title)
        except ValueError as e:
            raise ValueError(f"Invalid title: {e}") from e

        normalized_tags = set()
        for tag in tags:
            try:
                normalized_tags.add(ModelTask.normalize_tag(tag))
            except ValueError as e:
                raise ValueError(f"Invalid tag provided: {e}") from e

        new_id = self.next_id
        task = ModelTask(
            id=new_id, 
            title=normalized_title, 
            tags=sorted(list(normalized_tags)), 
            done=False
        )

        self._tasks[new_id] = task
        self.next_id += 1
        self._save()
        return task

    def get(self, task_id: int) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")
        return self._tasks[task_id]

    def list(self, status: str = "open", tags: Tuple[str, ...]) -> List[ModelTask]:
        status = status.lower()
        if status not in ["open", "done", "all"]:
            raise ValueError("Invalid status. Must be 'open', 'done', or 'all'.")

        target_tasks: List[ModelTask] = []

        # Normalize input tags immediately
        try:
            normalized_filter_tags = [ModelTask.normalize_tag(t) for t in tags]
        except ValueError as e:
            raise ValueError(f"Invalid tag filter provided: {e}") from e


        for task in self._tasks.values():
            # 1. Status check
            if status == "open" and task.done:
                continue
            if status == "done" and not task.done:
                continue
            if status == "all" and task.done is not None:
                pass # Always include

            # 2. Tag check (must have ALL provided tags)
            if normalized_filter_tags:
                task_tags_set = set(task.tags)
                if not all(tag in task_tags_set for tag in normalized_filter_tags):
                    continue

            target_tasks.append(task)

        # Return in increasing ID order
        return sorted(target_tasks, key=lambda t: t.id)

    def mark_done(self, task_id: int) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")

        task = self._tasks[task_id]
        if task.done:
            # No change, but still return the task
            return task

        # Create a new immutable task instance with done=True
        new_task = task.replace(done=True) # Note: dataclasses in 3.10+ support replace
                                           # If targetting older python, manual construction needed.
                                           # Since 3.12 is specified, this is fine.

        self._tasks[task_id] = new_task
        self._save()
        return new_task

    def remove(self, task_id: int) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")

        task_to_remove = self._tasks[task_id]
        del self._tasks[task_id]
        self._save()
        return task_to_remove

    def edit(self, task_id: int, title: Optional[str] = None, add_tags: Tuple[str, ...] = (), remove_tags: Tuple[str, ...] = ()) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")

        current_task = self._tasks[task_id]

        new_title = title
        if title is not None:
            try:
                new_title = ModelTask.normalize_title(title)
            except ValueError as e:
                raise ValueError(f"Invalid new title: {e}") from e

        # 1. Handle Tags
        current_tags = set(current_task.tags)

        # Add tags
        tags_to_add = set()
        for tag in add_tags:
            try:
                normalized_tag = ModelTask.normalize_tag(tag)
                tags_to_add.add(normalized_tag)
            except ValueError as e:
                raise ValueError(f"Invalid tag to add: {e}") from e

        new_tags_set = current_tags.union(tags_to_add)

        # Remove tags
        for tag in remove_tags:
            try:
                normalized_tag = ModelTask.normalize_tag(tag)
                if normalized_tag in new_tags_set:
                    new_tags_set.remove(normalized_tag)
            except ValueError as e:
                # Removing an invalid tag doesn't error based on specification, but we must validate the tag itself
                raise ValueError(f"Invalid tag to remove: {e}") from e

        final_tags = sorted(list(new_tags_set))

        # 2. Check for required change
        if title is None and not add_tags and not remove_tags:
            raise ValueError("Must provide --title, or at least one tag change (--tag or --untag).")

        # 3. Update task
        updated_task = current_task
        if new_title is not None:
            updated_task = current_task.__class__(**current_task.__dict__, title=new_title)

        if final_tags != current_task.tags:
             updated_task = current_task.__class__(**current_task.__dict__, tags=final_tags)

        if updated_task is current_task:
            # Should not happen if we passed the required change check, but as a safeguard
            return current_task 

        self._tasks[task_id] = updated_task
        self._save()
        return updated_task

    # Helper for dataclass replacement (mimicking functionality if needed, though Python 3.12 supports it)
    def replace(self, **kwargs):
        """Creates a new Task instance with updated fields."""
        old_task = self
        new_attrs = {}
        for key in self.__dataclass_fields__:
            value = getattr(self, key)
            if key in kwargs:
                new_attrs[key] = kwargs[key]
            else:
                new_attrs[key] = value

        # Since Task is frozen=True, we must reconstruct it if we want to maintain immutability principle
        return ModelTask(
            id=new_attrs['id'],
            title=new_attrs['title'],
            tags=new_attrs['tags'],
            done=new_attrs['done']
        )
