DEFAULT_FILE = "todo.json"

def format_task_line(task: Task) -> str:
    status_marker = "[x]" if task.done else "[ ]"
    tag_string = " ".join([f"#{tag}" for tag in task.tags])
    return f"{task.id} {status_marker} {task.title} {tag_string}"

def run_add(store: TodoStore, args: argparse.Namespace) -> int:
    try:
        task = store.add(args.title, tuple(args.tag))
        print(f"added {task.id}")
        return 0
    except (ValueError, StoreError) as e:
        print(f"error: {e}", file=sys.stderr)
        return 2 # Usage/Validation error for add

def run_list(store: TodoStore, args: argparse.Namespace) -> int:
    try:
        status_map = {"open": "open", "done": "done", "all": "all"}
        status = status_map.get(args.status, "open")

        # Repeated --tag means AND condition in store.list implementation
        task_list = store.list(status=status, tags=tuple(args.tag))

        for task in task_list:
            print(format_task_line(task))

        return 0
    except (ValueError, StoreError) as e:
        print(f"error: {e}", file=sys.stderr)
        return 2 # Usage/Validation error for list

def run_done(store: TodoStore, args: argparse.Namespace) -> int:
    ids_to_process = [int(i) for i in args.id]

    # Pre-check: Ensure all IDs exist before making changes
    try:
        for task_id in ids_to_process:
            store.get(task_id)
    except KeyError as e:
        # Error 1: First missing ID
        print(f"error: no task with id {e.args[0]}", file=sys.stderr)
        return 1

    # Process changes
    results: List[str] = []
    for task_id in ids_to_process:
        try:
            task = store.mark_done(task_id)
            results.append(f"done {task.id}")
        except Exception:
            # Should not happen due to pre-check, but safety net
            print(f"error: unexpected error marking {task_id} done", file=sys.stderr)
            return 1 

    print('\n'.join(results))
    return 0

def run_remove(store: TodoStore, args: argparse.Namespace) -> int:
    try:
        task = store.remove(int(args.id))
        print(f"removed {task.id}")
        return 0
    except KeyError as e:
        print(f"error: no task with id {e.args[0]}", file=sys.stderr)
        return 1
    except StoreError as e:
        print(f"error: {e}", file=sys.stderr)
        return 3

def run_edit(store: TodoStore, args: argparse.Namespace) -> int:
    try:
        task_id = int(args.id)

        # Check if any operation is requested
        if args.title is None and not args.tag and not args.untag:
            raise ValueError("Must specify --title, or at least one tag change (--tag or --untag).")

        # Convert string lists to tuples for API consumption
        add_tags = tuple(args.tag) if args.tag else ()
        remove_tags = tuple(args.untag) if args.untag else ()

        task = store.edit(
            task_id=task_id, 
            title=args.title, 
            add_tags=add_tags, 
            remove_tags=remove_tags
        )
        print(f"edited {task.id}")
        return 0

    except KeyError as e:
        print(f"error: no task with id {e.args[0]}", file=sys.stderr)
        return 1
    except (ValueError, StoreError) as e:
        # Error 2: Invalid title or tag, or missing operation
        print(f"error: {e}", file=sys.stderr)
        return 2


def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="A simple command-line todo manager.")

    # Global file option
    parser.add_argument('--file', default=DEFAULT_FILE, help=f'Path to the todo storage file. (default: {DEFAULT_FILE})')

    subparsers = parser.add_subparsers(dest="command", required=True)

    # --- ADD Command ---
    parser_add = subparsers.add_parser('add', help='Add a new task.')
    parser_add.add_argument('title', type=str, help='The title of the new task.')
    parser_add.add_argument('--tag', nargs='*', default=[], help='Tags to apply to the task (can be repeated).')
    parser_add.set_defaults(func=run_add)

    # --- LIST Command ---
    parser_list = subparsers.add_parser('list', help='List tasks.')
    parser_list.add_argument('--status', choices=['open', 'done', 'all'], default='open', help='Filter by status.')
    parser_list.add_argument('--tag', nargs='*', default=[], help='Filter tasks that possess ALL of these tags (can be repeated).')
    parser_list.set_defaults(func=run_list)

    # --- DONE Command ---
    parser_done = subparsers.add_parser('done', help='Mark one or more tasks as done.')
    parser_done.add_argument('id', type=str, nargs='+', help='The ID(s) of the task(s) to mark as done.')
    parser_done.set_defaults(func=run_done)

    # --- REMOVE Command ---
    parser_remove = subparsers.add_parser('remove', help='Remove a task by ID.')
    parser_remove.add_argument('id', type=str, help='The ID of the task to remove.')
    parser_remove.set_defaults(func=run_remove)

    # --- EDIT Command ---
    parser_edit = subparsers.add_parser('edit', help='Edit an existing task.')
    parser_edit.add_argument('id', type=str, help='The ID of the task to edit.')
    parser_edit.add_argument('--title', type=str, default=None, help='New title for the task.')
    parser_edit.add_argument('--tag', nargs='*', default=[], help='Tags to add to the task.')
    parser_edit.add_argument('--untag', nargs='*', default=[], help='Tags to remove from the task.')
    parser_edit.set_defaults(func=run_edit)


    args = parser.parse_args(argv)

    # Initialize store based on global argument
    try:
        store = TodoStore(args.file)
    except StoreError as e:
        # Error 3: Store file invalid
        print(f"error: {e}", file=sys.stderr)
        return 3

    # Execute the command function
    return args.func(store, args)


if __name__ == '__main__':
    # This block handles the execution when running as 'python -m todo.cli'
    sys.exit(main())
