```python
import re
import datetime
from dataclasses import dataclass, field
from typing import List, Dict, Any, Optional

@dataclass(frozen=True)
class Task:
    id: int
    title: str
    tags: List[str] = field(default_factory=list)
    done: bool = False
    priority: str = field(default="normal")
    due: Optional[datetime.date] = field(default=None)

    def to_dict(self) -> Dict[str, Any]:
        # Keys must be in this exact order
        due_str = self.due.strftime("%Y-%m-%d") if self.due else None
        return {
            "id": self.id, 
            "title": self.title, 
            "tags": self.tags, 
            "done": self.done, 
            "priority": self.priority, 
            "due": due_str
        }

    @staticmethod
    def normalize_title(title: str) -> str:
        normalized = title.strip()
        if not normalized:
            raise ValueError("Title cannot be empty.")
        return normalized

    @staticmethod
    def normalize_tag(tag: str) -> str:
        normalized = tag.strip().lower()
        if not re.fullmatch(r"[a-z0-9][a-z0-9_-]*", normalized):
            raise ValueError(f"Invalid tag format: {tag}")
        return normalized

    @staticmethod
    def normalize_priority(p: str) -> str:
        normalized = p.strip().lower()
        if normalized not in ["high", "normal", "low"]:
            raise ValueError(f"Invalid priority: {p}. Must be 'high', 'normal', or 'low'.")
        return normalized

    @staticmethod
    def parse_date(s: str) -> datetime.date:
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d").date()
        except ValueError:
            raise ValueError(f"Invalid date format: {s}. Must be YYYY-MM-DD.")

    @classmethod
    def from_dict(cls, d: Dict[str, Any]) -> 'Task':
        required_keys = {"id": int, "title": str, "tags": list, "done": bool}
        optional_keys = {"priority": str, "due": (str, type(None))}

        # Check required keys
        for key, expected_type in required_keys.items():
            if key not in d:
                raise ValueError(f"Missing key '{key}' in task dictionary.")
            if not isinstance(d[key], expected_type):
                raise ValueError(f"Key '{key}' has incorrect type. Expected {expected_type.__name__}, got {type(d[key]).__name__}.")

        # Validate Title and Tags
        try:
            title = cls.normalize_title(d['title'])
        except ValueError as e:
            raise ValueError(f"Invalid task title: {e}") from e

        try:
            tags = sorted(list(set(cls.normalize_tag(t) for t in d['tags'])))
        except ValueError as e:
            raise ValueError(f"Invalid tag in task: {e}") from e

        # Handle optional fields
        priority = d.get("priority", "normal")
        try:
            priority = cls.normalize_priority(priority)
        except ValueError as e:
            raise ValueError(f"Invalid priority: {e}") from e

        due_str = d.get("due")
        due_date = None
        if due_str is not None:
            try:
                due_date = cls.parse_date(due_str)
            except ValueError as e:
                raise ValueError(f"Invalid due date format: {e}") from e

        return cls(
            id=d['id'],
            title=title,
            tags=tags,
            done=d['done'],
            priority=priority,
            due=due_date
        )

