### `todo/store.py`
```python
import json
import os
from pathlib import Path
from typing import List, Dict, Optional, Tuple
from datetime import date
from todo.model import Task, Task as ModelTask
from todo.model import Task as TaskType # Alias to avoid conflict

VERSION_1 = 1
VERSION_2 = 2

class StoreError(Exception):
    pass

class TodoStore:
    def __init__(self, path: str | Path):
        self.path = Path(path)
        self._tasks: Dict[int, ModelTask] = {}
        self.next_id: int = 1
        self.current_version: int = 1
        self._load()

    def _load(self):
        if not self.path.exists():
            self.tasks_data = {"version": 1, "next_id": 1, "tasks": []}
            return

        try:
            with open(self.path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except json.JSONDecodeError:
            raise StoreError(f"File is not valid JSON: {self.path}")
        except Exception as e:
            raise StoreError(f"Could not read or open file {self.path}: {e}")

        version = data.get("version", 1)
        self.current_version = version

        next_id_from_file = data.get("next_id", 1)
        tasks_list = data.get("tasks", [])

        loaded_tasks: Dict[int, ModelTask] = {}
        max_id = 0

        for item in tasks_list:
            try:
                task = ModelTask.from_dict(item)

                if task.id >= next_id_from_file:
                    raise StoreError(f"Task ID {task.id} is equal to or greater than stored next_id {next_id_from_file}.")
                if task.id in loaded_tasks:
                    raise StoreError(f"Duplicate task ID found: {task.id}.")

                loaded_tasks[task.id] = task
                max_id = max(max_id, task.id)

            except ValueError as e:
                raise StoreError(f"Invalid task data format: {e}") from e

        self._tasks = loaded_tasks
        self.next_id = next_id_from_file

        if self._tasks:
            self.next_id = max(self.next_id, max(self._tasks.keys()) + 1)

        # If we loaded version 1, we must ensure future saves are version 2
        if self.current_version == VERSION_1:
            self.current_version = VERSION_2


    def _save(self) -> None:
        """Writes the current state to the file atomically, always using version 2."""

        # Sort tasks by ID for consistent storage
        sorted_tasks = sorted(self._tasks.values(), key=lambda t: t.id)
        tasks_dict_list = [t.to_dict() for t in sorted_tasks]

        data = {
            "version": VERSION_2, # Always write V2
            "next_id": self.next_id,
            "tasks": tasks_dict_list
        }

        temp_path = self.path.with_suffix(self.path.suffix + ".tmp")

        try:
            with open(temp_path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=4)

            os.replace(temp_path, self.path)
        except Exception as e:
            if temp_path.exists():
                temp_path.unlink()
            raise StoreError(f"Failed to write to store file {self.path}: {e}")


    # --- Public API Methods ---

    def add(self, title: str, tags: Tuple[str, ...], priority: str = "normal", due: Optional[date] = None) -> ModelTask:
        try:
            normalized_title = ModelTask.normalize_title(title)
            normalized_priority = ModelTask.normalize_priority(priority)
        except ValueError as e:
            raise ValueError(f"Invalid input for add: {e}") from e

        normalized_tags = set()
        for tag in tags:
            try:
                normalized_tags.add(ModelTask.normalize_tag(tag))
            except ValueError as e:
                raise ValueError(f"Invalid tag provided: {e}") from e

        # Due date validation handled by ModelTask if passed as string, but here it's date object
        if due and not isinstance(due, date):
             raise ValueError("Due date must be a datetime.date object.")

        new_id = self.next_id
        task = ModelTask(
            id=new_id, 
            title=normalized_title, 
            tags=sorted(list(normalized_tags)), 
            done=False,
            priority=normalized_priority,
            due=due
        )

        self._tasks[new_id] = task
        self.next_id += 1
        self._save()
        return task

    def get(self, task_id: int) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")
        return self._tasks[task_id]

    def list(self, status: str = "open", tags: Tuple[str, ...], overdue: bool = False, today: Optional[date] = None, sort: str = "id") -> List[ModelTask]:

        # 1. Validation
        status = status.lower()
        if status not in ["open", "done", "all"]:
            raise ValueError("Invalid status. Must be 'open', 'done', or 'all'.")

        if overdue and today is None:
            raise ValueError("Overdue flag requires a 'today' date to be specified.")

        if sort not in ["id", "priority", "due"]:
            raise ValueError("Invalid sort parameter. Must be 'id', 'priority', or 'due'.")

        # 2. Filtering and Selection
        target_tasks: List[ModelTask] = []

        # Normalize input tags
        try:
            normalized_filter_tags = [ModelTask.normalize_tag(t) for t in tags]
        except ValueError as e:
            raise ValueError(f"Invalid tag filter provided: {e}") from e

        for task in self._tasks.values():

            # Status Check
            if status == "open" and task.done: continue
            if status == "done" and not task.done: continue
            if status == "all" and task.done is not None: pass

            # Tag Check
            if normalized_filter_tags:
                task_tags_set = set(task.tags)
                if not all(tag in task_tags_set for tag in normalized_filter_tags):
                    continue

            # Overdue Check
            if overdue and task.done is False:
                if today and task.due and task.due < today:
                    # Task is open AND due date is strictly before today -> Overdue
                    target_tasks.append(task)
                    continue
                # If not overdue, continue to next task
                elif today and task.due is None:
                    # Open task, but no due date, cannot be overdue
                    pass 
                elif today and task.due and task.due >= today:
                    # Open task, due today or later, not overdue
                    pass
                elif not today: # Should be caught earlier, but safety first
                    pass
            elif not overdue:
                # If not checking for overdue, include all matching tasks (unless they fail status/tag)
                target_tasks.append(task)


        # 3. Sorting
        if sort == "id":
            sorted_tasks = sorted(target_tasks, key=lambda t: t.id)
        elif sort == "priority":
            # Order: high (0), normal (1), low (2). Tiebreaker: ID.
            priority_map = {"high": 0, "normal": 1, "low": 2}
            sorted_tasks = sorted(target_tasks, key=lambda t: (priority_map[t.priority], t.id))
        elif sort == "due":
            # Sort by due date (None last). Tiebreaker: ID.
            # Key returns (Is_None, Date_or_Sentinel). False comes before True.
            def due_sort_key(t: ModelTask):
                if t.due is None:
                    # Place None dates last
                    return (True, float('inf'))
                return (False, t.due)
            sorted_tasks = sorted(target_tasks, key=due_sort_key)

        return sorted_tasks

    def mark_done(self, task_id: int) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")

        task = self._tasks[task_id]
        if task.done:
            return task

        # Use dataclass replacement functionality (requires Python 3.10+)
        new_task = task.__class__(**task.__dict__, done=True)
        self._tasks[task_id] = new_task
        self._save()
        return new_task

    def remove(self, task_id: int) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")

        task_to_remove = self._tasks[task_id]
        del self._tasks[task_id]
        self._save()
        return task_to_remove

    def edit(self, task_id: int, title: Optional[str] = None, add_tags: Tuple[str, ...] = (), remove_tags: Tuple[str, ...] = (), priority: Optional[str] = None, due: Optional[date] = None, clear_due: bool = False) -> ModelTask:
        if task_id not in self._tasks:
            raise KeyError(f"Task with id {task_id} not found.")

        current_task = self._tasks[task_id]

        # 1. Validate changes requested
        if (due is not None and clear_due) or (due is None and clear_due):
            raise ValueError("Cannot provide both --due DATE and --no-due (clear_due=True).")

        # 2. Handle Title
        new_title = current_task.title
        if title is not None:
            try:
                new_title = ModelTask.normalize_title(title)
            except ValueError as e:
                raise ValueError(f"Invalid new title: {e}") from e

        # 3. Handle Priority
        new_priority = current_task.priority
        if priority is not None:
            try:
                new_priority = ModelTask.normalize_priority(priority)
            except ValueError as e:
                raise ValueError(f"Invalid new priority: {e}") from e

        # 4. Handle Tags
        current_tags = set(current_task.tags)

        tags_to_add = set()
        for tag in add_tags:
            try:
                tags_to_add.add(ModelTask.normalize_tag(tag))
            except ValueError as e:
                raise ValueError(f"Invalid tag to add: {e}") from e

        new_tags_set = current_tags.union(tags_to_add)

        for tag in remove_tags:
            try:
                normalized_tag = ModelTask.normalize_tag(tag)
                if normalized_tag in new_tags_set:
                    new_tags_set.remove(normalized_tag)
            except ValueError as e:
                raise ValueError(f"Invalid tag to remove: {e}") from e

        final_tags = sorted(list(new_tags_set))

        # 5. Handle Due Date
        new_due = current_task.due
        if clear_due:
            new_due = None
        elif due is not None:
            new_due = due

        # 6. Check for required change
        changed = (new_title != current_task.title or 
                   new_priority != current_task.priority or 
                   final_tags != current_task.tags or 
                   new_due != current_task.due)

        if not changed:
            raise ValueError("No valid changes provided. Must specify --title, or at least one tag/priority/date change.")

        # 7. Update task
        # Reconstruct using Task.__class__ to maintain immutability of original object
        updated_task = ModelTask(
            id=current_task.id,
            title=new_title,
            tags=final_tags,
            done=current_task.done,
            priority=new_priority,
            due=new_due
        )

        self._tasks[task_id] = updated_task
        self._save()
        return updated_task
