import argparse
import sys
import datetime
from typing import List, Tuple, Optional
from todo import Task, TodoStore, StoreError

DEFAULT_FILE = "todo.json"

def format_task_line(task: Task) -> str:
    # <id> [ ] <title>
    line = f"{task.id} [ ] {task.title}"

    # Priority
