    parser_edit.add_argument('--due', type=str, default=None, help='New due date in YYYY-MM-DD format.')
    parser_edit.add_argument('--no-due', action='store_true', help='Clear the due date.')
    parser_edit.set_defaults(func=run_edit)


    args = parser.parse_args(argv)

    # Parse global date context
    try:
        today_date = datetime.datetime.strptime(args.today, "%Y-%m-%d").date()
    except ValueError:
        print(f"error: Invalid --today date format. Use YYYY-MM-DD.", file=sys.stderr)
        return 2

    # Initialize store
    try:
        store = TodoStore(args.file)
    except StoreError as e:
        print(f"error: {e}", file=sys.stderr)
        return 3

    # Execute the command function
    # Pass today_date to functions that need it (like list)
    if hasattr(args.func, '__name__') and args.func.__name__ in ['run_list', 'run_add']:
        return args.func(store, args, today_date)
    else:
        return args.func(store, args)


if __name__ == '__main__':
    # This block handles the execution when running as 'python -m todo.cli'
