from typing import NamedTuple, List
import re

class TemplateError(Exception):
    """Base class for template errors."""
    pass

class TemplateSyntaxError(TemplateError):
    """Raised for syntax errors during parsing."""
    def __init__(self, message: str, lineno: int):
        super().__init__(f"line {lineno}: {message}")
        self.message = message
        self.lineno = lineno

class TemplateRenderError(TemplateError):
    """Raised for errors during template rendering."""
    def __init__(self, message: str, lineno: int):
        super().__init__(f"line {lineno}: {message}")
        self.message = message
        self.lineno = lineno

class Token(NamedTuple):
    kind: str  # "text", "var", "block"
    value: str
    lineno: int

def tokenize(source: str) -> List[Token]:
    """
    Tokenizes the source string into a list of Tokens.
    """
    tokens: List[Token] = []
    line_num = 1
    i = 0
    n = len(source)

    while i < n:
        char = source[i]

        if char == '\n':
            line_num += 1
            i += 1
            # Newline is always captured as text, even if it follows a tag
            tokens.append(Token("text", '\n', line_num))
            continue

        # Check for start of a tag
        if source.startswith("{{", i):
            start_index = i
            tag_type = "var"
            end_delimiter = "}}"
            content_start = i + 2

            # Scan for closing delimiter, respecting quotes inside
            j = content_start
            in_quote = None  # Stores "'" or '"' if inside a string literal
            while j < n:
                if in_quote:
                    # Inside a quote, look for the closing quote
                    if source[j] == in_quote:
                        in_quote = None
                    j += 1
                    continue

                # Not in a quote, check for delimiters
                elif source.startswith(end_delimiter, j):
                    content = source[content_start:j]

                    # Strip surrounding whitespace for token value
                    stripped_content = content.strip()

                    # Tokens are only created if content is not empty after stripping
                    if stripped_content:
                        tokens.append(Token("var", stripped_content, line_num))
                    else:
                        # Empty tag content like {{ }}
                        tokens.append(Token("var", "", line_num))

                    i = j + len(end_delimiter)
                    break

                # Check for start of quoted string literal
                elif source[j] in ("'", '"'):
                    in_quote = source[j]
                    j += 1 # Start scanning after the opening quote

                j += 1
            else:
                # Loop finished without finding end delimiter
                raise TemplateSyntaxError("Unclosed expression tag '{{'", line_num)
            continue

        elif source.startswith("{%", i):
            start_index = i
            tag_type = "block"
            end_delimiter = "%}"
            content_start = i + 2

            # Scan for closing delimiter, respecting quotes inside
            j = content_start
            in_quote = None
            while j < n:
                if in_quote:
                    if source[j] == in_quote:
                        in_quote = None
                    j += 1
                    continue

                elif source.startswith(end_delimiter, j):
                    content = source[content_start:j]
                    stripped_content = content.strip()

                    if stripped_content:
                        tokens.append(Token("block", stripped_content, line_num))
                    else:
                        tokens.append(Token("block", "", line_num))

                    i = j + len(end_delimiter)
                    break

                elif source[j] in ("'", '"'):
                    in_quote = source[j]
                    j += 1

                j += 1
            else:
                raise TemplateSyntaxError("Unclosed block tag '{%'", line_num)
            continue

        elif source.startswith("{#", i):
            start_index = i
            tag_type = "comment"
            end_delimiter = "#}"
            content_start = i + 2

            # Scan for closing delimiter
            j = content_start
            while j < n:
                if source.startswith(end_delimiter, j):
                    # Comment found. Consume it and do not emit a token.
                    i = j + len(end_delimiter)
                    break
                j += 1
            else:
                raise TemplateSyntaxError("Unclosed comment tag '{#'", line_num)
            continue

        # If none of the tag starts match, it's regular text
        else:
            # Find the next start of any tag, or end of string
            next_tag_start = n

            # Look for next {{
            next_var = source.find("{{", i)
            if next_var != -1:
                next_tag_start = min(next_tag_start, next_var)

            # Look for next {%
            next_block = source.find("{%", i)
            if next_block != -1:
                next_tag_start = min(next_tag_start, next_block)

            # Look for next {#
            next_comment = source.find("{#", i)
            if next_comment != -1:
                next_tag_start = min(next_tag_start, next_comment)

            if next_tag_start > i:
                text_segment = source[i:next_tag_start]
                # Text token must never be empty
                tokens.append(Token("text", text_segment, line_num))
                i = next_tag_start
            else:
                # This path should ideally not be hit if tag detection is comprehensive, 
                # but handles single characters not starting a tag.
                tokens.append(Token("text", char, line_num))
                i += 1


    return tokens

