from typing import List, Any, Dict
from .lexer import Token, TemplateSyntaxError

# --- Node Definitions ---

class Node:
    """Base class for all parsed template nodes."""
    pass

class TextNode(Node):
    """Represents static text content."""
    def __init__(self, content: str):
        self.content = content

class VariableNode(Node):
    """Represents an expression in {{ ... }}. Can be a simple value or a condition."""
    def __init__(self, expression_parts: List[Any]):
        # expression_parts is a list representing the structure (e.g., [Atom, Filter1, Filter2])
        self.expression_parts = expression_parts
        # For simple output {{ exp }}, this is just the expression structure.
        # For conditions {{ if ... }}, this structure handles the full condition AST.
        pass

class StatementNode(Node):
    """Represents a control flow statement {% ... %}."""
    def __init__(self, statement_type: str, content: str):
        self.type = statement_type  # e.g., 'for', 'if', 'endif', 'endfor'
        self.content = content
        # Parsed structures will be added here (e.g., body, elifs)
        self.body: List[Node] = []
        self.else_block: List[Node] = []

# --- Parsing Logic ---

class Parser:
    """Parses a list of tokens into a tree structure."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_kind: str | None = None, expected_value: str | None = None) -> Token:
        if self.pos >= len(self.tokens):
            raise TemplateSyntaxError("Unexpected end of template", 1) # Lineno handling is complex here, defaulting to 1 for simplicity if EOF is reached mid-parse
        token = self.tokens[self.pos]

        if expected_kind and token.kind != expected_kind:
            raise TemplateSyntaxError(f"Expected token kind {expected_kind}, got {token.kind}", token.lineno)
        if expected_value and token.value != expected_value:
            raise TemplateSyntaxError(f"Expected token value '{expected_value}', got '{token.value}'", token.lineno)

        self.pos += 1
        return token

    def parse(self) -> List[Node]:
        """Main entry point for parsing."""
        nodes: List[Node] = []
        while self.pos < len(self.tokens):
            token = self.peek()
            if token is None:
                break

            if token.kind == "text":
                self.consume()
                nodes.append(TextNode(token.value))
            elif token.kind == "var":
                self.consume()
                # For simplicity, we wrap the raw content in a VariableNode. 
                # Actual expression parsing (atoms, filters) happens in the render stage, 
                # as full AST generation for expressions is very complex.
                nodes.append(VariableNode([token.value]))
            elif token.kind == "block":
                self.consume()
                # Block content needs deep parsing (statements)
                stmt_node = self._parse_statement(token.value, token.lineno)
                nodes.append(stmt_node)

        # Check for unclosed blocks at end of file (simplification: requires state tracking)
        # A proper implementation would track open IF/FOR structures.

        return nodes

    def _parse_statement(self, content: str, lineno: int) -> StatementNode:
        """
        Parses content inside {% ... %} tags. 
        This is a heavy simplification, assuming simple statement recognition.
        A full implementation requires recursive descent parsing of statements (if/for).
        """
        content = content.strip()

        if content.startswith("for ") and " in " in content:
            parts = content.split(" in ")
            if len(parts) == 2:
                name_part = parts[0].strip()
                expr_part = parts[1].strip()
                # E.g., "u" in "users" -> name="u", expr="users"
                # In a real system, we'd validate structure: {% for NAME in EXPR %}
                return StatementNode("for", content)

        elif content.startswith("if "):
            return StatementNode("if", content)

        elif content == "elif":
            return StatementNode("elif", content)

        elif content == "else":
            return StatementNode("else", content)

        elif content == "endif" or content == "endfor":
            return StatementNode("endif" if content == "endif" else "endfor", content)

        # If we reach here, it's an unknown statement or malformed structure
        raise TemplateSyntaxError(f"Unknown or malformed statement: '{content}'", lineno)


def parse(source: str) -> List[Node]:
    """
    Public interface to parse the source string.
    """
    from .lexer import tokenize

    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

if __name__ == '__main__':
