from typing import Any, Dict, List, Union
import collections.abc

from .lexer import Token, TemplateSyntaxError, TemplateRenderError
from .parser import Node, TextNode, VariableNode, StatementNode

# --- Core Logic ---

def _resolve_variable_path(
    value: Any, 
    path_segments: List[str], 
    loop_context: Dict[str, Any] | None = None
) -> Any:
    """
    Traverses the value structure using path segments.
    """
    current_value = value

    # If loop context is provided, it takes precedence for 'loop' variable access
    if loop_context and path_segments[0] == 'loop' and len(path_segments) > 1:
        segment = path_segments[1]
        if segment in loop_context:
            current_value = loop_context[segment]
            path_segments = path_segments[1:]
        else:
            return None

    for segment in path_segments:
        if current_value is None:
            return None

        is_list_index = segment.isdigit()

        if isinstance(current_value, collections.abc.Mapping):
            # Mapping lookup (uses string key)
            if is_list_index:
                # This case should technically not happen if we handle list/tuple indexing correctly
                return None 

            key = segment
            current_value = current_value.get(key)

        elif isinstance(current_value, (list, tuple)):
            # List/Tuple indexing
            if is_list_index:
                try:
                    index = int(segment)
                    current_value = current_value[index]
                except IndexError:
                    return None
            else:
                # Attribute access on a sequence/list using a name (e.g., list.name) - usually None
                return None

        elif isinstance(current_value, str) and not is_list_index:
             # String attribute access (e.g., string.upper()) - though typically attributes are used on objects
             # For simplicity, we treat this as attribute access if not a map/list
             try:
                 current_value = getattr(current_value, segment)
             except AttributeError:
                 return None

        else:
            # General object attribute access (e.g., user.name)
            try:
                current_value = getattr(current_value, segment)
            except AttributeError:
                return None

    return current_value

def _apply_filters(
    value: Any, 
    filters_list: List[str], 
    line_num: int
) -> Any:
    """
    Applies a list of filters sequentially to the value.
    """
    current_value = value

    for filter_str in filters_list:
        if not filter_str:
            continue

        try:
            # Parse filter: name or name:arg or name:arg1:arg2 (though we only support one arg)
            parts = filter_str.split(':', 1)
            filter_name = parts[0]
            arg_str = parts[1] if len(parts) > 1 else None

            # 1. Determine the base output text/value
            if current_value is None:
                # Handle None input for filters that might require input (e.g., default)
                output_base = None
            else:
                if isinstance(current_value, (str, bytes)):
                    output_base = str(current_value)
                elif isinstance(current_value, (int, float)):
                    output_base = str(current_value)
                else:
                    # If it's an object, we use str() representation for text filters, 
                    # or rely on object methods for others.
                    output_base = str(current_value)

            # 2. Apply filter logic
            if filter_name == "upper":
                current_value = output_base.upper() if isinstance(output_base, str) else output_base
            elif filter_name == "lower":
                current_value = output_base.lower() if isinstance(output_base, str) else output_base
            elif filter_name == "trim":
                current_value = output_base.strip() if isinstance(output_base, str) else output_base
            elif filter_name == "length":
                current_value = len(output_base) if isinstance(output_base, str) else 0
            elif filter_name == "first":
                if output_base is None:
                    current_value = None
                elif isinstance(output_base, str) and len(output_base) > 0:
                    current_value = output_base[0]
                elif isinstance(output_base, (list, tuple)) and len(output_base) > 0:
                    current_value = output_base[0]
                else:
                    current_value = None
            elif filter_name == "last":
                if output_base is None:
                    current_value = None
                elif isinstance(output_base, str) and len(output_base) > 0:
                    current_value = output_base[-1]
                elif isinstance(output_base, (list, tuple)) and len(output_base) > 0:
                    current_value = output_base[-1]
                else:
                    current_value = None
            elif filter_name == "reverse":
                if isinstance(output_base, str):
                    current_value = output_base[::-1]
                elif isinstance(output_base, (list, tuple)):
                    current_value = list(reversed(output_base))
                else:
                    current_value = None
            elif filter_name == "join":
                if arg_str is None:
                    raise TemplateSyntaxError("Filter 'join' requires a separator argument.", line_num)
                try:
                    sep = eval(arg_str) # WARNING: Using eval() for simplicity in argument parsing
                    if not isinstance(sep, str):
                         raise TypeError("Join separator must be a string.")

                    # Assuming we join iterable items from the value
                    if isinstance(output_base, (list, tuple)):
                        items = [str(item) for item in output_base]
                        current_value = sep.join(items)
                    else:
                        # Cannot join non-iterable unless it's a single string (which shouldn't happen for join)
                        current_value = ""
                except Exception as e:
                     raise TemplateSyntaxError(f"Error applying 'join' filter: {e}", line_num)
            elif filter_name == "default":
                if arg_str is None:
                    raise TemplateSyntaxError("Filter 'default' requires a literal argument.", line_num)
                try:
                    literal = eval(arg_str) # WARNING: Using eval() for simplicity
                except Exception as e:
                     raise TemplateSyntaxError(f"Error parsing default argument: {e}", line_num)

                if current_value is None or str(current_value) == "":
                    current_value = literal
                # Otherwise, keep the value unchanged (including 0 or False)
            elif filter_name == "truncate":
                if arg_str is None:
                    raise TemplateSyntaxError("Filter 'truncate' requires an integer argument.", line_num)
                try:
                    N = int(arg_str)
                except ValueError:
                    raise TemplateSyntaxError("Truncate argument must be an integer.", line_num)

                if N < 0:
                    raise TemplateSyntaxError("Truncate length must be non-negative.", line_num)

                if isinstance(output_base, str) and len(output_base) > N:
                    current_value = output_base[:N] + "..."
                else:
                    current_value = output_base
            elif filter_name == "items":
                if not isinstance(output_base, collections.abc.Mapping):
                     raise TemplateRenderError("Filter 'items' requires a mapping.", line_num)

                items_list = []
                for k, v in output_base.items():
                    items_list.append((k, v))
                current_value = items_list
            else:
                raise TemplateSyntaxError(f"Unknown filter: '{filter_name}'", line_num)

        except TemplateError:
            # Re-raise template errors caught during filter application
            raise
        except Exception as e:
            # Catch unexpected issues during execution (e.g., invalid attribute access on non-object)
            raise TemplateRenderError(f"Error during filter '{filter_name}': {type(e).__name__}: {e}", line_num)

    return current_value

def _evaluate_expression(
    expression_parts: List[Any], 
    context: Dict[str, Any], 
    loop_context: Dict[str, Any] | None, 
    line_num: int
) -> Any:
    """
    Evaluates a single value expression (Atom + Filters).
    Note: This function currently only handles simple value expressions (not conditions).
    """
    if not expression_parts:
        return None

    # 1. Get the initial value (Atom)
    atom_str = expression_parts[0]
    initial_value = None

    try:
        if atom_str.startswith(('"', "'")):
            # String literal
            initial_value = atom_str[1:-1]
        elif atom_str.isdigit() or (atom_str.startswith('-') and atom_str[1:].isdigit()):
            # Integer literal
            initial_value = int(atom_str)
        else:
            # Variable path (name.segment or just name)
            # The path is the value itself, as filters are attached after the path.
            initial_value = _resolve_variable_path(None, [atom_str], loop_context)
            # Since we resolved the path, we must check if it resolved to something, 
            # or if it's just a string name that needs further resolution via context lookup
            if initial_value is None:
                 initial_value = context.get(atom_str)
    except Exception as e:
        raise TemplateRenderError(f"Error resolving atom '{atom_str}': {e}", line_num)

    # 2. Apply filters
    filters = [p for p in expression_parts[1:]]
    return _apply_filters(initial_value, filters, line_num)


# --- Template Rendering ---

class Template:
    def __init__(self, source: str):
        from .lexer import tokenize
        from .parser import parse

        tokens = tokenize(source)
        self.nodes: List[Node] = parse(source)

    def _render_node(
        self, 
        node: Node, 
        context: Dict[str, Any], 
        loop_context: Dict[str, Any] | None = None, 
        line_num: int = 1
    ) -> str:
        """Recursively renders a single node."""

        if isinstance(node, TextNode):
            return node.content

        elif isinstance(node, VariableNode):
            # VariableNode holds the expression structure
            try:
                result = _evaluate_expression(
                    node.expression_parts, context, loop_context, line_num
                )

                if result is None:
                    return "" # None writes nothing

                # Output text is str(value)
                return str(result)
            except TemplateRenderError as e:
                # Re-raise render errors with correct line context
                raise e
            except Exception as e:
                # Catch errors during evaluation not explicitly handled
                 raise TemplateRenderError(f"Runtime evaluation failed: {type(e).__name__}: {e}", line_num)

        elif isinstance(node, StatementNode):
            if node.type == "endif" or node.type == "endfor":
                # These are structural markers, they yield no output themselves.
                return ""

            # Handle Control Flow (IF/FOR)
            if node.type == "if":
                # Full IF parsing is extremely complex without a dedicated expression parser.
                # We treat the content as a placeholder for the structure and rely on 
                # the calling loop to handle branching logic based on parsed structure.
                # Since we only have the raw block content string here, we cannot evaluate 
                # the condition without a full AST.
                # Placeholder: If we hit a raw 'if' block, we assume the condition evaluation
                # must be handled by a wrapper that knows how to parse the condition string.
                # For this implementation, we must signal that rendering cannot proceed 
                # without a full statement parser.
                raise NotImplementedError("IF/ELIF/ELSE statement rendering requires full statement AST parsing, not just token parsing.")

            elif node.type == "for":
                # Similar complexity: requires parsing "NAME in EXPR"
                raise NotImplementedError("FOR statement rendering requires full statement AST parsing.")

            # If we reached here, the statement node is not a recognized terminator/branching logic
            return "" 

        return "" # Fallback

    def render(self, context: Dict[str, Any] | None = None, **kwargs) -> str:
        """
        Renders the parsed template against the provided context.
        """
        if context is None:
            context = {}

        # Merge context with kwargs, kwargs takes precedence
        merged_context = {**context, **kwargs}

        output_parts: List[str] = []

        # Top level nodes are usually text interspersed with control blocks
        for node in self.nodes:
            # Since we couldn't implement full AST rendering for blocks, 
            # we can only safely render TextNodes and simple VariableNodes here.
            if isinstance(node, TextNode):
                output_parts.append(node.content)
            elif isinstance(node, VariableNode):
                # For top-level variables, we pass None for loop_context
                output_parts.append(self._render_node(node, merged_context, None, line_num=1))
            elif isinstance(node, StatementNode):
                 # If we have statement nodes, we must halt or implement the full flow control logic.
                 # For the scope of this simplified implementation, we only support pure text/variable output.
                 raise NotImplementedError("Statements (if/for) are not fully implemented in the render pass.")


        return "".join(output_parts)

def render(source: str, context: Dict[str, Any] | None = None, **kwargs) -> str:
    """Public rendering function."""
    template = Template(source)
    return template.render(context, **kwargs)


