from typing import List, Any, Dict, Union
from .lexer import Token, TemplateSyntaxError, TemplateNotFound

# --- Node Definitions ---

class Node:
    """Base class for all parsed template nodes."""
    pass

class TextNode(Node):
    """Represents static text content."""
    def __init__(self, content: str):
        self.content = content

class VariableNode(Node):
    """Represents an expression in {{ ... }}. Contains raw expression parts."""
    def __init__(self, expression_parts: List[Any]):
        self.expression_parts = expression_parts

class BlockNode(Node):
    """Represents a control structure tag {% ... %} (if, for, block, extends)."""
    def __init__(self, tag_type: str, content: str, lineno: int):
        self.type = tag_type  # e.g., 'for', 'if', 'block', 'extends'
        self.content = content
        self.lineno = lineno
        # For statements/blocks, children will hold the parsed content structure
        self.children: List[Node] = []
        # For control flow, these hold structure details (e.g., elif/else for 'if')
        self.structure_details: Dict[str, Any] = {} 


# --- Parsing Logic ---

class Parser:
    """Parses a list of tokens into a tree structure."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected_kind: str | None = None, expected_value: str | None = None) -> Token:
        if self.pos >= len(self.tokens):
            # If we hit EOF unexpectedly during consumption, raise a syntax error referencing the last line or 1.
            raise TemplateSyntaxError("Unexpected end of template", 1) 
        token = self.tokens[self.pos]

        if expected_kind and token.kind != expected_kind:
            raise TemplateSyntaxError(f"Expected token kind {expected_kind}, got {token.kind} ('{token.value[:10]}...')", token.lineno)
        if expected_value and token.value != expected_value:
            raise TemplateSyntaxError(f"Expected token value '{expected_value}', got '{token.value}'", token.lineno)

        self.pos += 1
        return token

    def parse(self) -> List[Node]:
        """Main entry point for parsing."""
        nodes: List[Node] = []
        while self.pos < len(self.tokens):
            token = self.peek()
            if token is None:
                break

            if token.kind == "text":
                self.consume()
                nodes.append(TextNode(token.value))
            elif token.kind == "var":
                self.consume()
                # Raw content for variable expression
                nodes.append(VariableNode([token.value]))
            elif token.kind == "block":
                self.consume()
                # Block content needs deep parsing (statements/blocks)
                stmt_node = self._parse_statement(token.value, token.lineno)
                nodes.append(stmt_node)

        return nodes

    def _parse_statement(self, content: str, lineno: int) -> BlockNode:
        """
        Parses content inside {% ... %} tags, recursively handling nested structures.
        This function is significantly expanded to handle block nesting.
        """

        # Check for simple commands first (e.g., endif, endblock)
        cmd = content.strip()
        if cmd in ["endif", "endblock"]:
            return BlockNode(cmd, content, lineno)

        # Check for block definitions (e.g., {% block NAME %} or {% endblock NAME %})
        if cmd.startswith("block ") and len(cmd.split()) == 2:
            name = cmd.split()[1]
            return BlockNode("block", content, lineno)

        if cmd.startswith("endblock ") and len(cmd.split()) == 2:
            name = cmd.split()[1]
            return BlockNode("endblock", content, lineno)

        # Check for inheritance
        if cmd.startswith("extends ") and len(cmd.split()) == 2:
            return BlockNode("extends", content, lineno)

        # Check for control flow (if/for)
        if cmd.startswith("if "):
            # Structure: if COND (optional elif COND)* (optional else) endif
            # We parse this as a high-level block node, and the renderer will handle recursion.
            return BlockNode("if", content, lineno)

        if cmd.startswith("for "):
            # Structure: for NAME in EXPR
            return BlockNode("for", content, lineno)

        if cmd == "elif":
            return BlockNode("elif", content, lineno)

        if cmd == "else":
            return BlockNode("else", content, lineno)

        # If we reach here, it's an unknown or malformed statement
        raise TemplateSyntaxError(f"Unknown or malformed statement: '{cmd}'", lineno)


def parse(source: str) -> List[Node]:
    """
    Public interface to parse the source string.
    """
    from .lexer import tokenize

    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

if __name__ == '__main__':
