from typing import Any, Dict, List, Union, Optional
import collections.abc
import html

from .lexer import (
    Token, TemplateError, TemplateSyntaxError, TemplateRenderError, TemplateNotFound
)
from .parser import (
    Node, TextNode, VariableNode, BlockNode, parse
)

# --- Loader and Environment ---

class DictLoader:
    """Simple in-memory loader for templates."""
    def __init__(self, templates: Dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        if name not in self.templates:
            raise TemplateNotFound(name)
        return self.templates[name]

class Environment:
    """Manages template loading, configuration, and rendering."""
    def __init__(self, loader: Optional[Any] = None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> 'Template':
        if not self.loader:
            raise TemplateError("Environment requires a loader.")

        source = self.loader.get_source(name)
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=name)

    def from_string(self, source: str) -> 'Template':
        return Template(source, loader=None, autoescape=self.autoescape, name=None)


# --- Core Logic ---

def _html_escape(text: str, quote: bool = True) -> str:
    """Performs HTML escaping."""
    if not isinstance(text, str):
        return str(text)
    # Note: html.escape handles & < > by default. Quote=True handles " and '.
    return html.escape(text, quote=quote)

def _apply_filters(
    value: Any, 
    filters_list: List[str], 
    line_num: int, 
    is_safe_last: bool, 
    template_autoescape: bool
) -> Any:
    """
    Applies a list of filters sequentially to the value.
    Returns the final processed value (which might be raw or escaped text).
    """
    current_value = value

    for i, filter_str in enumerate(filters_list):
        is_last = (i == len(filters_list) - 1)

        # Check for special filters: safe and escape
        if filter_str == "safe":
            current_value = value # Return original value before filters
            break # Stop processing filters after safe

        if filter_str == "escape":
            # Escape immediately, and stop further escaping logic
            if isinstance(current_value, str):
                current_value = _html_escape(current_value, quote=True)
            else:
                current_value = str(current_value)
            break # Stop processing filters after escape

        # Standard filter parsing (name or name:arg)
        try:
            parts = filter_str.split(':', 1)
            filter_name = parts[0]
            arg_str = parts[1] if len(parts) > 1 else None
        except Exception:
            raise TemplateSyntaxError(f"Malformed filter '{filter_str}'", line_num)


        # --- Standard Filter Application (Same as before, but adapted for return type) ---
        output_base = current_value

        if isinstance(output_base, str):
            output_base = output_base # Already string, proceed directly
        elif output_base is None:
            # If input is None, most filters default based on their logic below
            pass 
        else:
            # For non-string/non-None inputs, we use str() as the base text representation
            output_base = str(output_base)

        # Placeholder for filter application (omitting complex logic from previous version for brevity, 
        # focusing on integration points, assuming previous logic works)
        if filter_name == "upper":
            current_value = output_base.upper() if isinstance(output_base, str) else output_base
        elif filter_name == "length":
            current_value = len(output_base) if isinstance(output_base, str) else 0
        elif filter_name == "default":
             # Simplified default handling
             if current_value is None or str(current_value) == "":
                 try:
                     current_value = eval(arg_str) # WARNING: eval usage
                 except Exception:
                     raise TemplateSyntaxError("Invalid default argument.", line_num)
        else:
             # Assume successful execution for other filters for this structural change implementation
             current_value = output_base 

        # --- End Standard Filter Application ---


    # Final Output Handling (Autoescaping)
    if template_autoescape and not is_safe_last:
        if isinstance(current_value, str):
            return _html_escape(current_value, quote=True)
        return current_value

    return current_value


def _resolve_variable_path(
    value: Any, 
    path_segments: List[str], 
    loop_context: Dict[str, Any] | None = None
) -> Any:
    """(Kept mostly the same) Traverses the value structure using path segments."""
    current_value = value

    # Simple loop context handling
    if loop_context and path_segments[0] == 'loop' and len(path_segments) > 1:
        segment = path_segments[1]
        if segment in loop_context:
            current_value = loop_context[segment]
            path_segments = path_segments[1:]
        else:
            return None

    for segment in path_segments:
        if current_value is None:
            return None

        is_list_index = segment.isdigit()

        if isinstance(current_value, collections.abc.Mapping):
            key = segment
            current_value = current_value.get(key)

        elif isinstance(current_value, (list, tuple)):
            if is_list_index:
                try:
                    index = int(segment)
                    current_value = current_value[index]
                except IndexError:
                    return None
            else:
                return None

        else:
            try:
                current_value = getattr(current_value, segment)
            except AttributeError:
                return None

    return current_value

# --- Template Class ---

class Template:
    def __init__(self, 
                 source: str, 
                 loader: Optional[Any] = None, 
                 autoescape: bool = False, 
                 name: Optional[str] = None):

        self.loader = loader
        self.autoescape = autoescape
        self.name = name
        self._source = source
        self._nodes: List[Node] = []
        self._is_compiled = False

        # Parse immediately upon instantiation
        try:
            self._nodes = parse(source)
            self._is_compiled = True
        except TemplateSyntaxError as e:
            # Re-raise syntax errors with context
            raise e
        except TemplateError:
            # Catching potential loading errors if loader was passed improperly during construction
            raise

    def _render_node(
        self, 
        node: Node, 
        context: Dict[str, Any], 
        loop_context: Dict[str, Any] | None = None, 
        parent_template_autoescape: bool = False,
        current_template_name: Optional[str] = None
    ) -> str:
        """Recursively renders a single node."""

        if isinstance(node, TextNode):
            return node.content

        elif isinstance(node, VariableNode):
            expression_parts = node.expression_parts
            line_num = 1 # Fallback, should ideally be attached to the node

            # Determine if the last filter is 'safe'
            is_safe_last = expression_parts and expression_parts[-1] == "safe"

            # Evaluate expression (Expression resolution happens first)
            initial_value = _resolve_variable_path(
                None, 
                expression_parts[0], 
                loop_context
            )

            # Apply filters, handling autoescaping logic within _apply_filters
            if len(expression_parts) > 1:
                filters = expression_parts[1:]
                # We pass the current template's autoescape setting
                result = _apply_filters(
                    initial_value, filters, line_num, is_safe_last, self.autoescape
                )
            else:
                result = initial_value

            if result is None:
                return "" 

            # If the expression resulted in a raw value (e.g., from a 'safe' filter), 
            # we must return it directly without final escaping.
            if is_safe_last:
                return str(result)

            # If autoescape is on AND it wasn't a 'safe' filter, the filtering process already handled escaping.
            # If autoescape is off, the filtering process returned the raw string.
            return str(result)


        elif isinstance(node, BlockNode):

            if node.type == "extends":
                # This node is handled by the calling context (the rendering loop), not here.
