# minisql/tokens.py

from dataclasses import dataclass
from typing import List, Optional

class SQLError(Exception):
    """Base class for SQL errors."""
    pass

class SQLSyntaxError(SQLError):
    """Raised for syntax errors during tokenizing or parsing."""
    def __init__(self, message: str, pos: int):
        super().__init__(f"Syntax Error at position {pos}: {message}")
        self.pos = pos

@dataclass(frozen=True)
class Token:
    kind: str
    value: Optional[str | int | float]
    pos: int

KEYWORDS = {
    "SELECT", "FROM", "WHERE", "AND", "OR", "NOT", "ORDER", "BY", 
    "ASC", "DESC", "LIMIT", "IS", "NULL", "TRUE", "FALSE"
}

def tokenize(sql: str) -> List[Token]:
    """Tokenizes the input SQL string."""
    tokens: List[Token] = []
    i = 0
    n = len(sql)

    def advance(count=1) -> int:
        nonlocal i
        i += count
        return i

    while i < n:
        char = sql[i]

        if char.isspace():
            advance()
            continue

        # 1. Operators and Punctuation
        if char in ('*', ',', '(', ')'):
            kind = 'STAR' if char == '*' else (
                'COMMA' if char == ',' else 
                'LPAREN' if char == '(' else 'RPAREN'
            )
            tokens.append(Token(kind, char, i))
            advance()
            continue

        # 2. String literals
        if char == "'":
            start_pos = i
            advance() # consume opening quote
            value_chars = []
            while i < n:
                if sql[i] == "'":
                    advance() # consume quote
                    if i < n and sql[i] == "'":
                        # Escaped quote ''
                        value_chars.append("'")
                        advance()
                    else:
                        break # End of string
                else:
                    value_chars.append(sql[i])
                    advance()

            if i == n and sql[i-1] != "'": # Check if loop terminated due to EOF before closing quote
                 raise SQLSyntaxError("Unterminated string literal", start_pos)

            tokens.append(Token('STRING', "".join(value_chars), start_pos))
            continue

        # 3. Numbers
        if char.isdigit() or (char == '-' and i + 1 < n and sql[i+1].isdigit()):
            start_pos = i
            is_negative = False
            if char == '-':
                is_negative = True
                advance()

            start_digits = i

            while i < n and (sql[i].isdigit() or sql[i] == '.'):
                if sql[i] == '.':
                    # Check for invalid '.' (e.g., '1.')
                    if i == start_digits and start_digits == i - 1 and is_negative: # Starts with -., invalid
                        raise SQLSyntaxError("Invalid number format (leading dot)", i)

                    # Check if '.' is followed by digits
                    if i + 1 == n or not sql[i+1].isdigit():
                        raise SQLSyntaxError("Invalid number format (dot without trailing digits)", i)

                advance()

            num_str = sql[start_pos:i]
            try:
                if '.' in num_str:
                    value = float(num_str)
                else:
                    value = int(num_str)
                tokens.append(Token('NUMBER', value, start_pos))
            except ValueError:
                # Should not happen given the loop logic, but defensive coding.
                raise SQLSyntaxError(f"Could not parse number: {num_str}", start_pos)
            continue

        # 4. Identifiers and Keywords
        if char.isalpha() or char == '_':
            start_pos = i
            while i < n and (sql[i].isalnum() or sql[i] == '_'):
                advance()
            value = sql[start_pos:i]

            upper_value = value.upper()
            if upper_value in KEYWORDS:
                kind = 'KEYWORD'
                value = upper_value
            else:
                kind = 'IDENT'

            tokens.append(Token(kind, value, start_pos))
            continue

        # 5. Comparison Operators
        if char in ('=', '<', '>', '!', '<', '='):
            op_str = ""
            start_pos = i

            if char == '<' and i + 1 < n and sql[i+1] == '=':
                op_str = "<="
                advance(2)
            elif char == '>' and i + 1 < n and sql[i+1] == '=':
                op_str = ">="
                advance(2)
            elif char == '=' and i + 1 < n and sql[i+1] == '=':
                # While SQL standards often use '==' for equality, the spec requires checking !=, <>
                # We treat '==' as '=' for simplicity unless the spec demands otherwise.
                # The spec lists op: = | != | <> | < | <= | > | >=
                pass # Fall through to single char check if not part of multi-char op

            elif char == '!' and i + 1 < n and sql[i+1] == '=':
                op_str = "!="
                advance(2)
            elif char == '<>' and i + 1 < n and sql[i+1] == '>': # Should be covered by <>, but for robustness
                op_str = "<>"
                advance(2)
            elif char == '<=':
                op_str = "<="
                advance(2)
            elif char == '>=':
                op_str = ">="
                advance(2)
            else:
                # Single character operators
                if char == '=':
                    op_str = "="
                    advance()
                elif char == '<':
                    op_str = "<"
                    advance()
                elif char == '>':
                    op_str = ">"
                    advance()
                else:
                    # This block handles potential unrecognized single chars that looked like ops
                    raise SQLSyntaxError(f"Unexpected character in operator sequence: {char}", i)


            # Handle <> conversion
            if op_str == "<>":
                op_str = "!="

            tokens.append(Token('OP', op_str, start_pos))
            continue

        # 6. Catch-all error
        raise SQLSyntaxError(f"Unexpected character: {char}", i)

    tokens.append(Token('EOF', None, n))
    return tokens
