# minisql/parser.py

from dataclasses import dataclass
from typing import List, Optional, Any, Tuple, Union
from .tokens import Token, SQLSyntaxError

# --- AST Nodes ---

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: Union[int, float, str, bool, None]

@dataclass(frozen=True)
class Compare:
    op: str
    left: Any
    right: Any

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclass(frozen=True)
class Select:
    columns: Optional[Union[str, List[str]]]
    table: str
    where: Optional[Any]
    order_by: List[Tuple[str, bool]] # (name, descending)
    limit: Optional[int]

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        if self.pos >= len(self.tokens):
            return self.tokens[-1] # Should be EOF
        return self.tokens[self.pos]

    def advance(self) -> Token:
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return self.tokens[self.pos - 1]

    def expect(self, kind: str, value: Optional[str] = None) -> Token:
        token = self.current_token()
        if token.kind != kind:
            raise SQLSyntaxError(f"Expected {kind} but found {token.kind}", token.pos)
        if value and token.value != value:
            raise SQLSyntaxError(f"Expected token value '{value}' but found '{token.value}'", token.pos)

        self.advance()
        return token

    # --- Parsing Functions ---

    def parse_literal(self) -> Any:
        token = self.current_token()

        if token.kind == 'IDENT':
            value = token.value
            if value.upper() == 'NULL':
                self.advance()
                return None
            elif value.upper() == 'TRUE':
                self.advance()
                return True
            elif value.upper() == 'FALSE':
                self.advance()
                return False
            else:
                # Must be a column name if it wasn't a reserved keyword used as literal
                # This is implicitly handled by the calling context (operand parsing), 
                # but here we assume if it's an IDENT and not a keyword, it's a name.
                # For literals, we only expect specific reserved identifiers.
                raise SQLSyntaxError(f"Expected literal value, found identifier '{value}'", token.pos)

        elif token.kind == 'NUMBER':
            self.advance()
            return token.value

        elif token.kind == 'STRING':
            self.advance()
            return token.value

        else:
            raise SQLSyntaxError(f"Expected literal (number, string, or NULL), found {token.kind}", token.pos)

    def parse_operand(self) -> Any:
        token = self.current_token()

        if token.kind == 'IDENT':
            # Could be a column name
            self.advance()
            return Column(token.value)

        elif token.kind == 'NUMBER':
            self.advance()
            return Literal(token.value)

        elif token.kind == 'STRING':
            self.advance()
            return Literal(token.value)

        elif token.kind == 'EOF' or token.kind == 'KEYWORD':
            # Check for NULL/TRUE/FALSE literals which are parsed differently in the condition chain
            if token.kind == 'KEYWORD':
                upper_value = token.value.upper()
                if upper_value in ('NULL', 'TRUE', 'FALSE'):
                    self.advance()
                    if upper_value == 'NULL':
                        return Literal(None)
                    return Literal(upper_value == 'TRUE')

            raise SQLSyntaxError(f"Expected operand, found {token.kind}", token.pos)

        else:
            raise SQLSyntaxError(f"Unexpected token while parsing operand: {token.kind}", token.pos)


    def parse_condition(self) -> Any:
        # Implements precedence: NOT > AND > OR
        # This uses Pratt parsing structure (or simple recursive descent with explicit precedence)

        # 1. Parse primary (atom/parenthesized condition)
        left = self._parse_primary_condition()

        # 2. Handle OR (Lowest precedence, Left-associative)
        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'OR':
            op_token = self.advance() # Consume OR
            right = self._parse_primary_condition()
            left = Or(left, right)

        return left

    def _parse_primary_condition(self) -> Any:
        # Handles NOT, AND, and comparison/IS NULL structures

        # Handle NOT (Unary operator)
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NOT':
            self.advance() # Consume NOT
            operand = self._parse_primary_condition()
            return Not(operand)

        # Handle AND (Binary operator)
        left = self._parse_term()

        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'AND':
            op_token = self.advance() # Consume AND
            right = self._parse_term()
            left = And(left, right)

        return left

    def _parse_term(self) -> Any:
        # Handles comparison and IS NULL checks
        token = self.current_token()

        # Check for IS NULL / IS NOT NULL
        if token.kind == 'IDENT' and token.value.upper() == 'IS':
            self.advance() # Consume IS

            operand = self._parse_operand()

            if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NULL':
                self.advance() # Consume NULL
                negated = (self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NOT')
                if negated:
                    self.advance() # Consume NOT
                    return IsNull(operand, True)
                return IsNull(operand, False)
            else:
                raise SQLSyntaxError("Expected NULL after IS", token.pos)


        # Check for binary comparison (operand op operand)
        left = self._parse_operand()

        if self.current_token().kind == 'OP':
            op_token = self.advance() # Consume op
            right = self._parse_operand()
            return Compare(op_token.value, left, right)

        # Parenthesized condition
        if token.kind == 'LPAREN':
            self.advance() # Consume '('
            condition = self.parse_condition()
            self.expect('RPAREN') # Consume ')'
            return condition

        # If none of the above, it's just a single operand (which is not a condition alone)
        # This case should ideally not be hit if the caller ensures it's a condition, 
        # but we return the operand structure itself.
        return left


    def parse_select_list(self, table_name: str, next_clause_expectations: List[str]) -> Tuple[Any, int]:
        """Parses columns list, returns (AST_node, next_token_pos)."""

        select_list_tokens = []

        # Check for '*'
        if self.current_token().kind == 'STAR':
            self.advance()
            return '*', self.pos

        # Parse comma-separated names
        columns: List[str] = []
        while True:
            token = self.current_token()
            if token.kind != 'IDENT':
                break

            columns.append(token.value)
            self.advance()

            if self.current_token().kind != 'COMMA':
                break
            self.advance() # Consume COMMA

        if not columns:
             # Should have been caught by '*' check if list was empty, but safety check
             raise SQLSyntaxError("SELECT list cannot be empty", self.tokens[0].pos)

        # Check for duplicate names (Rule: same name listed twice is a syntax error)
        if len(columns) != len(set(columns)):
             raise SQLSyntaxError("Duplicate column name in select list", self.tokens[0].pos)

        return columns, self.pos

    def parse_select_clause(self) -> Select:
        # 1. SELECT list
        select_list_token = self.expect('KEYWORD', 'SELECT')

        # Temporarily capture position before parsing list, as list parsing advances self.pos
        initial_pos = self.pos
        columns_ast, current_pos = self.parse_select_list(None, ['FROM'])
        self.pos = current_pos

        # 2. FROM table
        self.expect('KEYWORD', 'FROM')
        table_token = self.expect('IDENT')
        table_name = table_token.value

        # 3. WHERE condition (Optional)
        where_clause: Optional[Any] = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'WHERE':
            self.advance() # Consume WHERE
            where_clause = self.parse_condition()

        # 4. ORDER BY (Optional)
        order_by: List[Tuple[str, bool]] = []
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'ORDER':
            self.advance() # Consume ORDER
            self.expect('KEYWORD', 'BY')

            # Parse one or more order items
            while True:
                name_token = self.expect('IDENT')
                name = name_token.value

                descending = False
                if self.current_token().kind == 'KEYWORD':
                    val = self.current_token().value
                    if val == 'DESC':
                        self.advance()
                        descending = True
                    elif val == 'ASC':
                        self.advance()

                order_by.append((name, descending))

                if self.current_token().kind != 'COMMA':
                    break
                self.advance() # Consume COMMA

        # 5. LIMIT (Optional)
        limit: Optional[int] = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'LIMIT':
            self.advance() # Consume LIMIT
            limit_token = self.expect('NUMBER')
            limit = int(limit_token.value)

        # Final check: Must end after LIMIT or previous clause
        if self.current_token().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token after statement: {self.current_token().value}", self.current_token().pos)

        return Select(columns_ast, table_name, where_clause, order_by, limit)


def parse(sql: str) -> Select:
    """Tokenizes and parses a single SQL statement."""
    tokens = tokenize(sql)
    parser = Parser(tokens)

    stmt = parser.parse_select_clause()

    return stmt
