# minisql/parser.py

from dataclasses import dataclass
from typing import List, Optional, Any, Tuple, Union, Dict
from .tokens import Token, SQLSyntaxError

# --- AST Nodes ---

@dataclass(frozen=True)
class Column:
    # Canonical text: 'name' or 'table.name'
    text: str 

@dataclass(frozen=True)
class Literal:
    value: Union[int, float, str, bool, None]

@dataclass(frozen=True)
class Aggregate:
    func: str # COUNT, SUM, AVG, MIN, MAX
    arg: Optional[Column] # Column reference or None for COUNT(*)

    @property
    def canonical_text(self) -> str:
        if self.func == 'COUNT' and self.arg is None:
            return "COUNT(*)"
        if self.arg:
            return f"{self.func}({self.arg.text})"
        # Should not happen if logic is correct, but for safety
        return f"{self.func}()"

@dataclass(frozen=True)
class Compare:
    op: str
    left: Any
    right: Any

@dataclass(frozen=True)
class And:
    left: Any
    right: Any

@dataclass(frozen=True)
class Or:
    left: Any
    right: Any

@dataclass(frozen=True)
class Not:
    operand: Any

@dataclass(frozen=True)
class IsNull:
    operand: Any
    negated: bool

@dataclass(frozen=True)
class Join:
    table: str # Name of the table being joined (e.g., 'b')
    left: Column # Column from the left table (A)
    right: Column # Column from the right table (B)

@dataclass(frozen=True)
class Select:
    # Select Items: list of (AST_expr, output_key_str)
    items: List[Tuple[Any, str]] 
    # Output keys (aliases or canonical texts)
    columns: Optional[List[str]] 
    table: str
    # Join information
    join: Optional[Join] 
    # Condition
    where: Optional[Any] 
    # Grouping
    group_by: List[str] # List of canonical texts used for grouping
    # Ordering
    order_by: List[Tuple[str, bool]] # (canonical_text, descending)
    # Limit
    limit: Optional[int]


# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.keywords_set = set(KEYWORDS)

    def current_token(self) -> Token:
        if self.pos >= len(self.tokens):
            return self.tokens[-1]
        return self.tokens[self.pos]

    def advance(self) -> Token:
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return self.tokens[self.pos - 1]

    def expect(self, kind: str, value: Optional[str] = None) -> Token:
        token = self.current_token()
        if token.kind != kind:
            raise SQLSyntaxError(f"Expected {kind} but found {token.kind} ('{token.value}')", token.pos)
        if value and token.value != value:
            raise SQLSyntaxError(f"Expected token value '{value}' but found '{token.value}'", token.pos)

        self.advance()
        return token

    # --- Parsing Functions ---

    def parse_literal(self) -> Literal:
        token = self.current_token()

        if token.kind == 'NUMBER':
            self.advance()
            return Literal(token.value)

        elif token.kind == 'STRING':
            self.advance()
            return Literal(token.value)

        elif token.kind == 'IDENT':
            value = token.value
            if value.upper() == 'NULL':
                self.advance()
                return Literal(None)
            elif value.upper() == 'TRUE':
                self.advance()
                return Literal(True)
            elif value.upper() == 'FALSE':
                self.advance()
                return Literal(False)
            else:
                raise SQLSyntaxError(f"Identifier '{value}' used where literal was expected", token.pos)

        else:
            raise SQLSyntaxError(f"Expected literal value, found {token.kind}", token.pos)

    def parse_ref(self, current_table: Optional[str]) -> Column:
        """Parses a reference: name or table.name."""
        token = self.current_token()

        if token.kind == 'IDENT':
            name = token.value

            if self.current_token().kind == 'DOT':
                # Qualified reference: table.name
                self.advance() # Consume DOT

                if self.current_token().kind != 'IDENT':
                     raise SQLSyntaxError("Expected identifier after dot in qualified reference", self.current_token().pos)

                table_ident = self.current_token()
                self.advance() # Consume table name

                # Check for unqualified reference if this is the first part of a qualified ref
                if current_table is not None and table_ident.value != current_table:
                    # This is implicitly checked by the executor later, but parser records canonical form
                    pass

                return Column(f"{table_ident.value}.{name}")
            else:
                # Unqualified reference: name
                self.advance() # Consume identifier

                if current_table is None:
                    raise SQLSyntaxError("Unqualified reference used outside of FROM clause context", token.pos)

                # Canonical form for unqualified reference: table.name (using current_table)
                return Column(f"{current_table}.{name}")

        else:
            raise SQLSyntaxError(f"Expected reference (name or table.name), found {token.kind}", token.pos)


    def parse_aggregate(self, current_table: str, table_name: str) -> Aggregate:
        """Parses an aggregate function: COUNT(*), SUM(ref), etc."""

        # 1. Parse function name
        func_token = self.expect('KEYWORD')
        func_name = func_token.value

        if func_name not in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
             raise SQLSyntaxError(f"Invalid aggregate function: {func_name}", func_token.pos)

        arg_col: Optional[Column] = None

        if func_name == 'COUNT':
            if self.current_token().kind == 'STAR':
                self.advance() # Consume *
                return Aggregate(func_name, None) # COUNT(*)
            else:
                # COUNT(ref)
                if self.current_token().kind != 'LPAREN':
                    raise SQLSyntaxError("COUNT requires '(' after function name", func_token.pos)
                self.advance() # Consume '('

                arg_col = self.parse_ref(current_table)

                self.expect('RPAREN') # Consume ')'
                return Aggregate(func_name, arg_col)

        elif func_name in ('SUM', 'AVG', 'MIN', 'MAX'):
            self.expect('LPAREN') # Consume '('

            # The argument must be a reference
            arg_col = self.parse_ref(current_table)

            self.expect('RPAREN') # Consume ')'
            return Aggregate(func_name, arg_col)

        raise RuntimeError("Should not happen")


    def parse_select_item(self, current_table: str, table_name: str) -> Tuple[Any, str]:
        """Parses one item in the SELECT list: (expr, key)."""

        # 1. Parse the expression (Column or Aggregate)
        expr: Any

        # Check if it starts with a function (Aggregate)
        if self.current_token().kind == 'KEYWORD' and self.current_token().value in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            expr = self.parse_aggregate(current_table, table_name)
        else:
            # Must be a column reference
            expr = self.parse_ref(current_table)

        # 2. Parse Alias (AS name)
        alias_name: Optional[str] = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'AS':
            self.advance() # Consume AS
            alias_token = self.expect('IDENT')
            alias_name = alias_token.value

        # 3. Determine output key (Rule 7)
        if isinstance(expr, Aggregate):
            # Aggregate canonical text is the base key if no alias
            canonical_text = expr.canonical_text
        elif isinstance(expr, Column):
            canonical_text = expr.text
        else:
            raise SQLSyntaxError("Invalid expression type in select list", self.current_token().pos)

        # Final key is alias or canonical text
        output_key = alias_name if alias_name else canonical_text

        return expr, output_key

    # --- Clause Parsers ---

    def parse_join(self, current_table: str) -> Optional[Join]:
        """Parses FROM table [JOIN table ON condition]"""

        if self.current_token().kind != 'KEYWORD' or self.current_token().value != 'JOIN':
            return None

        self.advance() # Consume JOIN

        join_table_token = self.expect('IDENT')
        join_table_name = join_table_token.value

        if join_table_name == current_table:
            raise SQLSyntaxError("Cannot join a table to itself", join_table_token.pos)

        self.expect('KEYWORD', 'ON')

        # ON condition: ref = ref
        left_ref = self.parse_ref(current_table)
        self.expect('OP', '=')
        right_ref = self.parse_ref(join_table_name)

        return Join(join_table_name, left_ref, right_ref)


    def parse_select_list(self, current_table: str, table_name: str) -> Tuple[List[Tuple[Any, str]], Optional[str]]:
        """Parses items list, returns (list of (expr, key), columns list or None for *)."""

        items: List[Tuple[Any, str]] = []

        # Check for '*'
        if self.current_token().kind == 'STAR':
            self.advance()
            return [], None # No specific columns list

        # Parse comma-separated items
        while True:
            expr_item, key = self.parse_select_item(current_table, table_name)
            items.append((expr_item, key))

            if self.current_token().kind != 'COMMA':
                break
            self.advance() # Consume COMMA

        # Check for duplicate keys (Rule: two select items with the same output key)
        keys = [key for _, key in items]
        if len(keys) != len(set(keys)):
             raise SQLSyntaxError("Duplicate output key in select list", self.tokens[0].pos)

        return items, keys


    def parse_condition(self, current_table: str, joined_tables: List[str]) -> Any:
        # Operands can now be Refs (qualified or unqualified)

        def parse_primary_condition() -> Any:
            token = self.current_token()

            # Handle IS NULL / IS NOT NULL
            if token.kind == 'IDENT' and token.value.upper() == 'IS':
                self.advance() # Consume IS

                operand = self._parse_ref_or_expr(current_table, joined_tables)

                if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NULL':
                    self.advance() # Consume NULL
                    negated = (self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NOT')
                    if negated:
                        self.advance() # Consume NOT
                        return IsNull(operand, True)
                    return IsNull(operand, False)
                else:
                    raise SQLSyntaxError("Expected NULL after IS", token.pos)

            # Handle Parenthesized condition
            if token.kind == 'LPAREN':
                self.advance() # Consume '('
                condition = self.parse_condition(current_table, joined_tables) # Recursively call main condition parser
                self.expect('RPAREN') # Consume ')'
                return condition

            # Handle Operands (Refs or Literals)
            return self._parse_ref_or_expr(current_table, joined_tables)

        def _parse_ref_or_expr(ct: str, jt: List[str]) -> Any:
            token = self.current_token()
            if token.kind == 'IDENT' or (token.kind == 'DOT' and self.tokens[self.pos+1].kind == 'IDENT'):
                # It's a potential reference (ref)
                self.pos -= 1 # Revert advance if needed later, but for now, let parse_ref handle it
                return self.parse_ref(ct)
            else:
                # It must be a literal
                return self.parse_literal()


        # NOT (Unary)
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'NOT':
            self.advance() # Consume NOT
            operand = parse_primary_condition()
            return Not(operand)

        # AND (Binary)
        left = parse_primary_condition()

        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'AND':
            self.advance() # Consume AND
            right = parse_primary_condition()
            left = And(left, right)

        # OR (Binary - Lowest precedence)
        while self.current_token().kind == 'KEYWORD' and self.current_token().value == 'OR':
            self.advance() # Consume OR
            right = parse_primary_condition()
            left = Or(left, right)

        return left

    def parse_group_by(self, current_table: str, table_name: str) -> List[str]:
        """Parses GROUP BY ref {, ref}"""
        self.expect('KEYWORD', 'GROUP')
        self.expect('KEYWORD', 'BY')

        group_refs: List[str] = []

        while True:
            # Refs in GROUP BY are implicitly unqualified, referring to the source table
            ref_col = self.parse_ref(current_table)
            group_refs.append(ref_col.text)

            if self.current_token().kind != 'COMMA':
                break
            self.advance() # Consume COMMA

        return group_refs


    def parse_order_by(self, current_table: str, table_name: str) -> List[Tuple[str, bool]]:
        """Parses ORDER BY (ref | aggregate) [ASC | DESC]"""

        self.expect('KEYWORD', 'ORDER')
        self.expect('KEYWORD', 'BY')

        order_items: List[Tuple[str, bool]] = []

        while True:
            # Order item can be a ref or an aggregate
            token = self.current_token()

            if token.kind == 'KEYWORD' and token.value in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
                item_expr = self.parse_aggregate(current_table, table_name)
            else:
                # Must be a reference (ref)
                item_expr = self.parse_ref(current_table)

            # Determine canonical text (Rule 7)
            if isinstance(item_expr, Aggregate):
                text = item_expr.canonical_text
            elif isinstance(item_expr, Column):
                text = item_expr.text
            else:
                raise SQLSyntaxError("Invalid expression in ORDER BY", token.pos)

            descending = False
            if self.current_token().kind == 'KEYWORD':
                val = self.current_token().value
                if val == 'DESC':
                    self.advance()
                    descending = True
                elif val == 'ASC':
                    self.advance()

            order_items.append((text, descending))

            if self.current_token().kind != 'COMMA':
                break
            self.advance() # Consume COMMA

        return order_items


    def parse_select_clause(self) -> Select:

        # --- Stage 1: Initial FROM and JOIN ---

        self.expect('KEYWORD', 'SELECT')
        select_items, columns_list = self.parse_select_list(None, None)

        self.expect('KEYWORD', 'FROM')
        from_table_token = self.expect('IDENT')
        from_table_name = from_table_token.value

        # Check for JOIN
        join_node: Optional[Join] = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'JOIN':
            join_node = self.parse_join(from_table_name)

        current_table = from_table_name

        # --- Stage 2: WHERE ---
        where_clause: Optional[Any] = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'WHERE':
            self.advance() # Consume WHERE
            # For WHERE, we pass all known tables to check qualifications
            joined_tables = [from_table_name]
            if join_node:
                 joined_tables.append(join_node.table)
            where_clause = self.parse_condition(from_table_name, joined_tables)

        # --- Stage 3: GROUP BY ---
        group_by_refs: List[str] = []
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'GROUP':
            group_by_refs = self.parse_group_by(from_table_name, from_table_name)

        # --- Stage 4: ORDER BY ---
        order_by = self.parse_order_by(from_table_name, from_table_name)

        # --- Stage 5: LIMIT ---
        limit: Optional[int] = None
        if self.current_token().kind == 'KEYWORD' and self.current_token().value == 'LIMIT':
            self.advance() # Consume LIMIT
            limit_token = self.expect('NUMBER')
            limit = int(limit_token.value)

        # Final check
        if self.current_token().kind != 'EOF':
            raise SQLSyntaxError(f"Unexpected token after statement: {self.current_token().value}", self.current_token().pos)

        return Select(
            items=select_items,
            columns=columns_list,
            table=from_table_name,
            join=join_node,
            where=where_clause,
            group_by=group_by_refs,
            order_by=order_by,
            limit=limit
        )


def parse(sql: str) -> Select:
    """Tokenizes and parses a single SQL statement."""
    tokens = tokenize(sql)
    parser = Parser(tokens)

    stmt = parser.parse_select_clause()

    return stmt
