def _calculate_aggregate(agg_expr: Aggregate, group_rows: List[Dict[str, Any]], tables: Dict[str, List[Dict[str, Any]]], row_context: Dict[str, Any]) -> Any:
    """Calculates a single aggregate value for a group."""

    if agg_expr.func == 'COUNT':
        if agg_expr.arg is None:
            return len(group_rows) # COUNT(*)

        # COUNT(ref)
        ref_text = agg_expr.arg.text
        count = 0
        for row in group_rows:
            try:
                value = _evaluate_expression(Column(ref_text), row, tables, {})
                if value is not None:
                    count += 1
            except SQLExecutionError:
                pass # Ignore errors during evaluation of the specific column
        return count

    # For SUM, AVG, MIN, MAX, we collect all non-NULL values
    values = []
    ref_text = None
    if agg_expr.arg:
        ref_text = agg_expr.arg.text

    if ref_text:
        for row in group_rows:
            try:
                value = _evaluate_expression(Column(ref_text), row, tables, {})
                if value is not None:
                    values.append(value)
            except SQLExecutionError:
                pass

    if not values:
        return None # NULL if no values

    if agg_expr.func == 'SUM':
        sum_val = 0
        for val in values:
            if not isinstance(val, (int, float)):
                raise SQLExecutionError(f"SUM requires numeric values, got {type(val).__name__}")
            sum_val += val

        # Rule: int if all were int, else float
        if all(isinstance(v, int) for v in values):
            return sum_val
        return float(sum_val)

    elif agg_expr.func == 'AVG':
        s = sum(values)
        return float(s) / len(values)

    elif agg_expr.func == 'MIN' or agg_expr.func == 'MAX':
        # Min/Max requires comparison logic. We rely on Python's comparison operators.
        # Since we already checked kind consistency during WHERE/JOIN, this should generally be safe.
        return min(values) if agg_expr.func == 'MIN' else max(values)


