    current_rows: List[Dict[str, Any]] = []

    if stmt.join:
        # Initialize base rows for the FROM table (A)
        base_rows_a = tables[stmt.table]

        # Perform join starting from A vs B
        current_rows = _perform_joins(base_rows_a, stmt, tables)
    else:
        # No join, use rows from the primary table
        current_rows = tables[stmt.table]

    if not current_rows and not stmt.join and not stmt.where and not stmt.group_by:
        # If table is empty and no operations are applied, return empty list
        return []

    # 2. Filtering (WHERE clause) (Rule 6)
    filtered_rows: List[Dict[str, Any]] = []

    if stmt.where:
        for row in current_rows:
            # Row context must contain all qualified keys
            try:
                result = _evaluate_expression(stmt.where, row, tables, {})
                if result is True:
                    filtered_rows.append(row)
            except SQLExecutionError as e:
                raise e
            except Exception as e:
                # Catch errors during evaluation (e.g., type mismatch in comparison)
                raise SQLExecutionError(f"Evaluation error during WHERE clause: {e}")

    else:
        filtered_rows = current_rows

    # 3. Grouping (Rule 4)
    grouped_groups = _group_rows(filtered_rows, stmt.group_by, tables)

    # 4. Aggregation (Rule 5)
    final_output_rows: List[Dict[str, Any]] = []

    if stmt.group_by:
        for group_rows in grouped_groups:
            output_row: Dict[str, Any] = {}

            # Calculate aggregates and determine the final row contents
            for expr, key in stmt.items:
                if isinstance(expr, Aggregate):
                    value = _calculate_aggregate(expr, group_rows, tables, {})
                    output_row[key] = value
                elif isinstance(expr, Column):
                    # Ref in GROUP BY or SELECT list (must match group key)
                    # Find the value from the group's first row (they are identical by definition)
                    value = _evaluate_expression(expr, group_rows[0], tables, {})
                    output_row[key] = value

            final_output_rows.append(output_row)
    else:
        # No grouping: treat all filtered rows as a single "group"
        if not filtered_rows:
            # Rule: With no kept rows, return []
            return []

        # If no grouping, we run projection/selection on the rows directly
        for row in filtered_rows:
            output_row: Dict[str, Any] = {}
            for expr, key in stmt.items:
                if isinstance(expr, Aggregate):
                    # If aggregate exists but no grouping, this is an error unless it's a single row context
                    # For non-grouped queries, aggregates must use a single row's context or be treated as errors.
                    # Rule: Aggregates in SELECT list must be grouped unless the query is trivial.
                    if any(isinstance(item[0], Aggregate) for item in stmt.items):
                        raise SQLExecutionError("Aggregates are only permitted in queries with GROUP BY, unless they are simple scalar functions that run over the whole dataset, which is complex to define here. Defaulting to error.")

                elif isinstance(expr, Column):
                    value = _evaluate_expression(expr, row, tables, {})
                    output_row[key] = value
                else:
                     # Should not happen
                     pass
            final_output_rows.append(output_row)

    # 5. Ordering (Rule 6)

    def get_sort_value(row: Dict[str, Any], sort_key_text: str) -> Any:
        """Retrieves value by alias or canonical text."""
        # Check if the text matches an output key
        for key in row.keys():
            if key == sort_key_text:
                return row[key]

        # If not found as a key, it must be a direct column reference (only possible if not grouped)
        # This relies on the fact that if grouped, the key MUST be an alias or canonical text.
        # If not grouped, we look up the original column name in the row context (which is the dict keys).
        return row.get(sort_key_text)


    # Stable sort
    def sort_key_generator(row):
        keys = []
        for text, descending in stmt.order_by:
            try:
                value = get_sort_value(row, text)
            except Exception:
                 # If we cannot find the column/alias, treat as NULL for sorting purposes
                 value = None

            # NULL sorting logic
            if value is None:
                if not descending:
                    keys.append((0, None)) # NULLs first in ASC
                else:
                    keys.append((2, None)) # NULLs last in DESC
            else:
                # Use 1 or 2 rank to enforce ordering rules based on DESC flag
                rank = 1 if not descending else 2
                keys.append((rank, value))
        return tuple(keys)

    sorted_rows = sorted(final_output_rows, key=sort_key_generator, reverse=False)

    # 6. Limiting (Rule 8)
    if stmt.limit is not None:
        sorted_rows = sorted_rows[:stmt.limit]

    return sorted_rows


def query(sql: str, tables: Dict[str, List[Dict[str, Any]]]) -> List[Dict[str, Any]]:
    """High-level entry point for running a query."""
    from .parser import parse

    # Pre-check for aggregate in condition (Rule: Aggregates not allowed in condition)
    # This check is complex and requires parsing the WHERE clause first.
    # We rely on the evaluation phase to catch this during execution.

    stmt = parse(sql)
    return execute(stmt, tables)
