from decimal import Decimal

class AccountType(Enum):
    ASSET = "asset"
    LIABILITY = "liability"
    EQUITY = "equity"
    INCOME = "income"
    EXPENSE = "expense"

@dataclass(frozen=True)
class Account:
    code: str
    name: str
    type: AccountType
    parent: Optional[str]

class Chart:
    def __init__(self):
        # Maps code -> Account object
        self._accounts: Dict[str, Account] = {}
        # Maps parent code -> list of child codes
        self._children_map: Dict[str, List[str]] = {}
        # Maps code -> list of child codes (for traversal)
        self._child_codes: Dict[str, List[str]] = {}

    def add(self, code: str, name: str, type_input, parent: Optional[str] = None) -> Account:
        if not code or not code.isdigit():
            raise ValueError("Code must be a non-empty string of digits.")

        if isinstance(type_input, str):
            try:
                type_input = AccountType(type_input.lower())
            except ValueError:
                raise ValueError(f"Unknown account type: {type_input}")

        if code in self._accounts:
            raise ValueError(f"Account code {code} already exists.")

        if parent:
            if parent not in self._accounts:
                raise ValueError(f"Parent account {parent} does not exist.")
            parent_account = self._accounts[parent]
            if parent_account.type == AccountType.INCOME and type_input not in (AccountType.INCOME, AccountType.EXPENSE):
                # While the prompt implies a check, standard accounting hierarchies might be more complex.
                # Sticking strictly to the prompt's constraint:
                pass # Assuming parent type check is sufficient if parent exists.
            elif parent_account.type != type_input:
                raise ValueError(f"Parent type mismatch: Parent {parent} is {parent_account.type.value}, but new account is {type_input.value}")


        new_account = Account(code=code, name=name, type=type_input, parent=parent)
        self._accounts[code] = new_account

        if parent:
            if parent not in self._children_map:
                self._children_map[parent] = []
            self._children_map[parent].append(code)
        else:
            # If it's a root, ensure it's registered correctly (no parent)
            pass

        # Update child map for traversal
        self._child_codes[code] = []
        if parent:
            self._child_codes[parent].append(code)

        return new_account

    def get(self, code: str) -> Account:
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found in the chart.")
        return self._accounts[code]

    def children(self, code: str) -> list[Account]:
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")

        child_codes = self._children_map.get(code, [])

        # Sort by code and retrieve Account objects
        return sorted([self._accounts[c] for c in child_codes], key=lambda a: a.code)

    def roots(self) -> list[Account]:
        return sorted([acc for acc in self._accounts.values() if acc.parent is None], key=lambda a: a.code)

    def is_leaf(self, code: str) -> bool:
        if code not in self._accounts:
            raise KeyError(f"Account code {code} not found.")
        return code not in self._children_map or not self._children_map[code]

    def walk(self) -> list[tuple[Account, int]]:
        """Depth first traversal, depth 0 for roots. Sorts by code at each level."""
        result = []

        def dfs(account: Account, depth: int):
            # Add current account
            result.append((account, depth))

            # Recursively visit children in code order
            sorted_children = sorted(self.children(account.code), key=lambda a: a.code)
            for child in sorted_children:
                dfs(child, depth + 1)

        # Start DFS from all roots, ensuring roots are processed in code order
        roots = sorted(self.roots(), key=lambda a: a.code)
        for root in roots:
            dfs(root, 0)

        return result
