        self._entries: List[Entry] = []
        self._entry_counter = 0

    def _convert_amount(self, amount_input) -> Decimal:
        if isinstance(amount_input, float):
            raise TypeError("Amounts cannot be floats.")

        try:
            amount = Decimal(str(amount_input))
        except InvalidOperation:
            raise ValueError(f"Invalid numeric format for amount: {amount_input}")

        if amount < Decimal('0'):
            raise ValueError("Amount cannot be negative.")

        # Check for more than two decimal places
        if amount.as_tuple().exponent < -2:
            raise ValueError("Amount cannot have more than two decimal places.")

        return amount

    def post(self, day: date, memo: str, lines_data: List[Tuple[str, Optional[Decimal], Optional[Decimal]]]) -> Entry:

        # 1. Check line count
        if len(lines_data) < 2:
            raise ValueError("An entry must have at least two lines.")

        # Pre-process and validate individual lines
        processed_lines: List[Line] = []
        total_debits = Decimal('0')
        total_credits = Decimal('0')

        for account_code, debit_input, credit_input in lines_data:

            # 2. Account existence and leaf status
            try:
                account = self.chart.get(account_code)
            except KeyError:
                raise KeyError(f"Account code {account_code} does not exist in the chart.")

            if not self.chart.is_leaf(account_code):
                raise ValueError(f"Account {account_code} is not a leaf account.")

            # 3. Amount validation and non-zero check
            try:
                debit = debit_input if debit_input is not None else Decimal('0')
                credit = credit_input if credit_input is not None else Decimal('0')
            except TypeError as e:
                raise e # Re-raise TypeError if input was float
            except ValueError as e:
                raise e # Re-raise ValueError from _convert_amount if input was bad number

            if debit > Decimal('0') and credit > Decimal('0'):
                raise ValueError("Each line must have exactly one of debit or credit non-zero.")

            # Apply conversion checks (ensuring inputs weren't floats if they were passed as Decimals)
            if debit > Decimal('0') and not isinstance(debit, Decimal):
                 try:
                    debit = self._convert_amount(debit)
                 except (TypeError, ValueError) as e:
                    raise ValueError(f"Debit amount error: {e}")

            if credit > Decimal('0') and not isinstance(credit, Decimal):
                 try:
                    credit = self._convert_amount(credit)
                 except (TypeError, ValueError) as e:
                    raise ValueError(f"Credit amount error: {e}")


            # Re-check the non-zero rule after potential Decimal conversion if inputs were strings/ints
            if (debit > Decimal('0') and credit > Decimal('0')) or \
               (debit == Decimal('0') and credit == Decimal('0')):
                 raise ValueError("Each line must have exactly one of debit or credit non-zero.")

            processed_lines.append(Line(account=account_code, debit=debit, credit=credit))
            total_debits += debit
            total_credits += credit

        # 4. Balancing check
        if total_debits != total_credits:
            raise UnbalancedEntryError(
                f"Entry is unbalanced: Debits ({total_debits}) != Credits ({total_credits})"
            )

        # Post entry
        self._entry_counter += 1
        new_entry = Entry(
            number=self._entry_counter,
            day=day,
            memo=memo,
            lines=tuple(processed_lines)
        )
        self._entries.append(new_entry)
        return new_entry

    def entries(self) -> List[Entry]:
        return sorted(self._entries, key=lambda e: e.number)

    def balance(self, code: str, start: Optional[date] = None, end: Optional[date] = None) -> Decimal:
        if code not in self.chart._accounts:
            raise KeyError(f"Account code {code} not found.")

        account = self.chart.get(code)

        # Determine if the account is Debit-Normal (ASSET or EXPENSE)
        is_debit_normal = account.type in (AccountType.ASSET, AccountType.EXPENSE)

        total_debits = Decimal('0')
        total_credits = Decimal('0')

        # Traverse the chart to include descendants
        all_relevant_codes = {code}
        queue = [code]
        while queue:
            current_code = queue.pop(0)
            for child in self.chart.children(current_code):
                child_code = child.code
                all_relevant_codes.add(child_code)
                queue.append(child_code)

        for entry in self.entries():
            entry_day = entry.day

            # Date filtering
            if start and entry_day < start:
                continue
            if end and entry_day > end:
                continue

            for line in entry.lines:
                line_code = line.account
                if line_code not in all_relevant_codes:
                    continue

                if line.debit > Decimal('0'):
                    total_debits += line.debit
                if line.credit > Decimal('0'):
                    total_credits += line.credit

        # Calculate balance on normal side
        if is_debit_normal:
            # Normal side is Debit: Debits - Credits
            return total_debits - total_credits
        else:
            # Normal side is Credit: Credits - Debits
            return total_credits - total_debits

    def ledger(self, code: str) -> List[LedgerRow]:
        if code not in self.chart._accounts:
            raise KeyError(f"Account code {code} not found.")

        account = self.chart.get(code)
        is_debit_normal = account.type in (AccountType.ASSET, AccountType.EXPENSE)

        ledger_rows: List[LedgerRow] = []
        running_balance = Decimal('0')

        # We need to process all lines relevant to this account or its descendants
        # For simplicity and matching the requirement "one row per line posted to the account or a descendant",
        # we iterate through all entries and check if the line account is 'code' OR a descendant of 'code'.

        # --- Helper to check if a line's account is in the subtree of 'code' ---
        def is_descendant_or_self(line_code, root_code):
            if line_code == root_code:
                return True

            # Quick check: traverse up the parents until we hit the root or None
            current = self.chart.get(line_code)
            while current.parent:
                parent_code = current.parent
                if parent_code == root_code:
                    return True
                try:
                    current = self.chart.get(parent_code)
                except KeyError:
                    return False
            return False


        # Sort criteria: day, entry number, line position in entry
        def line_sort_key(entry: Entry, line_idx: int):
            return (entry.day, entry.number, line_idx)

        all_line_events = []
        for entry in self.entries():
            for i, line in enumerate(entry.lines):
                line_code = line.account

                # Check if this line applies to the target account or its descendants
                if is_descendant_or_self(line_code, code):
                    all_line_events.append((entry, i, line))

        # Sort the events chronologically
        all_line_events.sort(key=lambda x: line_sort_key(x[0], x[1]))

        # Calculate running balance
        for entry, line_idx, line in all_line_events:

            # Determine the effect on the running balance (Debit/Credit relative to the account's normal side)
            amount_change = Decimal('0')

            if line.debit > Decimal('0'):
                if is_debit_normal:
                    amount_change = line.debit
                else: # Credit normal
                    amount_change = -line.debit
            elif line.credit > Decimal('0'):
                if is_debit_normal:
                    amount_change = -line.credit
                else: # Credit normal
                    amount_change = line.credit

            running_balance += amount_change

            # Record the row
            row = LedgerRow(
                number=entry.number,
                day=entry.day,
                memo=entry.memo,
                debit=line.debit,
                credit=line.credit,
                balance=running_balance
            )
            ledger_rows.append(row)

        return ledger_rows
