from typing import List, Tuple
from decimal import Decimal

from books.journal import Journal
from books.accounts import Chart, Account, AccountType

# Helper function to format amount string
def format_amount(amount: Decimal) -> str:
    # Ensures exactly two decimals and leading minus sign if negative
    return f"{amount:,.2f}" if amount >= Decimal('0') else f"-{abs(amount):,.2f}"

# Helper function to calculate balance for a code across a period
def get_period_balance(journal: Journal, code: str, start: Optional[date], end: Optional[date]) -> Decimal:
    # We reuse Journal.balance, as it already calculates the net balance across the period
    try:
        return journal.balance(code, start=start, end=end)
    except KeyError:
        return Decimal('0')


def _get_account_lines(
    journal: Journal, 
    chart: Chart, 
    walk_order: List[Tuple[Account, int]], 
    start: Optional[date], 
    end: Optional[date], 
    account_type_filter: Optional[AccountType] = None
) -> List[Tuple[Account, Decimal]]:
    """
    Generates the list of accounts that must be displayed, along with their balances, 
    filtered by type and existence in the period.
    Returns [(Account, Balance), ...]
    """

    account_balances: Dict[str, Decimal] = {}

    # 1. Calculate balances for all accounts in walk order
    for account, _ in walk_order:
        code = account.code

        # Only calculate balance if the account type matches the filter (if provided)
        if account_type_filter and account.type != account_type_filter:
            continue

        balance = get_period_balance(journal, code, start, end)
        account_balances[code] = balance

    # 2. Filter for accounts with activity or matching type
    display_list: List[Tuple[Account, Decimal]] = []

    for account, _ in walk_order:
        code = account.code

        if account.type == account_type_filter:
            balance = account_balances[code]

            # Check if the account itself or any descendant has activity.
            # A simple proxy check: if the balance is non-zero, or if the account 
            # is a root/leaf of the relevant type, we show it.
            # A more robust check (which is complex) would require iterating all journal lines 
            # for descendants. We rely on balance > 0 or balance < 0 here for simplicity, 
            # as the prompt implies "if it or a descendant has at least one line".

            if balance != Decimal('0'):
                display_list.append((account, balance))

    return display_list


def trial_balance(journal: Journal, as_of: Optional[date] = None) -> str:
    """Generates the Trial Balance report."""

    if as_of is None:
        report_date = "TRIAL BALANCE"
    else:
        report_date = f"TRIAL BALANCE as of {as_of.strftime('%Y-%m-%d')}"

    # Get chart structure (needs the chart object, which we must assume is accessible 
    # or passed through journal/chart access)
    chart = journal.chart
    walk_order = chart.walk()

    # 1. Get all accounts with balances
    all_accounts = [acc for acc, _ in walk_order]

    # 2. Calculate period balances for all accounts
    account_balances: Dict[str, Decimal] = {}
    for account in all_accounts:
        balance = get_period_balance(journal, account.code, start=None, end=as_of)
        account_balances[account.code] = balance

    output_lines = [report_date]

    total_debits_sum = Decimal('0')
    total_credits_sum = Decimal('0')

    # 3. Format account lines
    for account in all_accounts:
        code = account.code
        balance = account_balances[code]

        # Account lines must be shown if they have *any* line in the period.
        # We approximate this by checking if the balance is non-zero, 
        # though this is imperfect if a balanced entry exists entirely within descendants.
        if balance != Decimal('0'):

            depth = 0
            temp_code = code
            while True:
                try:
                    parent_account = chart.get(temp_code).parent
                    if parent_account is None:
                        break
                    depth += 1
                    temp_code = parent_account
                except KeyError:
                    break

            indent = "  " * depth
            amount_str = format_amount(balance)

            # Determine if this balance contributes to total debits or credits
            is_debit_normal = account.type in (AccountType.ASSET, AccountType.EXPENSE)

            if is_debit_normal:
                # Debit normal: Positive balance means Debit total increases
                if balance >= Decimal('0'):
                    total_debits_sum += balance
                # Negative balance means Credit total increases
                else:
                    total_credits_sum += abs(balance)
            else:
                # Credit normal: Positive balance means Credit total increases
                if balance >= Decimal('0'):
                    total_credits_sum += balance
                # Negative balance means Debit total increases
                else:
                    total_debits_sum += abs(balance)


            # Print the line: <code> <name>: <amount>
            output_lines.append(f"{indent}{code} {account.name}: {amount_str}")

    # 4. Totals
    output_lines.append(f"Total debits: {format_amount(total_debits_sum)}")
    output_lines.append(f"Total credits: {format_amount(total_credits_sum)}")

    return "\n".join(output_lines) + "\n"


def income_statement(journal: Journal, start: date, end: date) -> str:
    """Generates the Income Statement report."""

    if start > end:
        raise ValueError("Start date cannot be after end date.")

    chart = journal.chart
    walk_order = chart.walk()

    income_accounts: List[Account] = []
    expense_accounts: List[Account] = []

    for account, _ in walk_order:
        if account.type == AccountType.INCOME:
            income_accounts.append(account)
        elif account.type == AccountType.EXPENSE:
            expense_accounts.append(account)

    output_lines = [f"INCOME STATEMENT {start.strftime('%Y-%m-%d')} to {end.strftime('%Y-%m-%d')}"]

    # --- Income Section ---
    output_lines.append("Income")

    # We use the specialized helper to get accounts with activity in the period
    income_activity = _get_account_lines(
        journal, chart, walk_order, start, end, AccountType.INCOME
    )

    total_income = Decimal('0')
    for account, balance in income_activity:
        # Income accounts are credit normal. A positive balance here is net income contribution.
        output_lines.append(f"{'  ' * (2 * (len(account.code) // 2))}{account.code} {account.name}: {format_amount(balance)}")
        total_income += balance

    output_lines.append(f"Total income: {format_amount(total_income)}")

    # --- Expense Section ---
    output_lines.append("Expenses")

    expense_activity = _get_account_lines(
        journal, chart, walk_order, start, end, AccountType.EXPENSE
    )

    total_expenses = Decimal('0')
    for account, balance in expense_activity:
        # Expense accounts are debit normal. A positive balance here is net expense.
        output_lines.append(f"{'  ' * (2 * (len(account.code) // 2))}{account.code} {account.name}: {format_amount(balance)}")
        total_expenses += balance

    output_lines.append(f"Total expenses: {format_amount(total_expenses)}")

    # --- Net Income ---
    net_income = total_income - total_expenses
    output_lines.append(f"Net income: {format_amount(net_income)}")

    return "\n".join(output_lines) + "\n"

