import re
from typing import Callable, Any, Tuple, Dict, List

from .request import Request, Response, HTTPError, BadRequest

# --- Errors ---

class NotFound(HTTPError):
    def __init__(self):
        super().__init__(404, "Not Found")

class MethodNotAllowed(HTTPError):
    def __init__(self, allowed: List[str]):
        super().__init__(405, "Method Not Allowed")
        self.allowed = sorted(allowed)

# --- Router ---

class Router:
    def __init__(self):
        # Structure: { method: [(pattern_regex, converter_map, handler), ...] }
        self.routes: Dict[str, List[Tuple[re.Pattern, Dict[str, Any], Callable[[Request], Response]]]] = {}

    def add(self, method: str, pattern: str, handler: Callable[[Request], Response]):
        if method not in self.routes:
            self.routes[method] = []

        # Internal conversion to pattern and validation
        try:
            regex_pattern, converters = self._compile_pattern(pattern)

            # Check for duplicates (method and raw pattern string)
            if any(r[0].pattern == pattern for r in self.routes[method]):
                raise ValueError(f"Pattern '{pattern}' already registered for {method}")

            self.routes[method].append((regex_pattern, converters, handler))

        except ValueError as e:
            raise e
        except Exception:
            # Catch internal compilation errors during validation
            raise ValueError(f"Invalid pattern structure: {pattern}")


    def route(self, pattern: str, methods: Tuple[str, ...] = ('GET',)):
        """Decorator factory."""
        def decorator(handler: Callable[[Request], Response]):
            for method in methods:
                self.add(method, pattern, handler)
            return handler
        return decorator

    def _compile_pattern(self, pattern: str) -> Tuple[re.Pattern, Dict[str, Any]]:
        """Converts pattern string to regex and extracts parameter names/converters."""
        if not pattern.startswith('/'):
            raise ValueError("Pattern must start with /")

        # Pattern segments: /literal/\{param\}/\{param:int\}/\{param:path\}
        segments = [s for s in pattern.split('/') if s]

        regex_parts = ['^/']
        converters = {}

        for i, segment in enumerate(segments):
            if segment.startswith('{') and segment.endswith('}'):
                content = segment[1:-1]

                if ':' in content:
                    name, converter_str = content.split(':', 1)
                    name = name.strip()

                    if converter_str == 'int':
                        converter = 'int'
                        regex_part = r'(\d+)'
                    elif converter_str == 'path':
                        converter = 'path'
                        # Path segments match one or more segments joined by '/'
                        if i != len(segments) - 1:
                             raise ValueError("Path converter '{name:path}' can only be the last segment.")
                        # Match anything until the end of the string
                        regex_part = r'(.+)' 
                    else:
                        raise ValueError(f"Unknown converter: {converter_str}")

                    if name in converters:
                        raise ValueError(f"Repeated parameter name: {name}")

                    converters[name] = converter
                    regex_parts.append(regex_part)
                else:
                    # Simple path parameter {name}
                    name = content
                    converter = 'str'
                    if name in converters:
                         raise ValueError(f"Repeated parameter name: {name}")
                    converters[name] = converter
                    # Matches any segment, non-empty
                    regex_parts.append(r'([^/]+)')
            else:
                # Literal segment
                # Escape regex special characters in literals
                literal = re.escape(segment)
                regex_parts.append(literal)

        regex_parts.append('$')

        full_regex_str = "".join(regex_parts)
        compiled_regex = re.compile(full_regex_str)
        return compiled_regex, converters


    def resolve(self, method: str, path: str) -> Tuple[Callable[[Request], Response], Dict[str, Any]]:
        """
        Resolves the handler and parameters for a given method and path.
        """
        # Path segments are decoded (except + stays +)
        try:
            decoded_path = self._decode_path(path)
        except BadRequest as e:
            raise e

        if method not in self.routes:
            # Check if any route exists for this path structure, even if method doesn't match
            potential_matches = []
            for m, routes in self.routes.items():
                for regex, _, _ in routes:
                    if regex.match(decoded_path):
                        potential_matches.append(m)

            if not potential_matches:
                raise NotFound()

            # If routes exist but no specific method match, check HEAD/GET fallback
            if 'GET' in potential_matches:
                allowed = [m for m in potential_matches if m in ('GET', 'HEAD')]
                # If GET exists, we can potentially serve it if the method is HEAD
                if method == 'HEAD' and 'GET' in [m for m, _, _ in self.routes.get('GET', [])]:
                    # Fall through to handle GET match logic below
                    pass
                else:
                    raise MethodNotAllowed([m for m in potential_matches])
            else:
                 raise MethodNotAllowed([m for m in potential_matches])


        possible_routes = self.routes.get(method, [])

        # HEAD request handling: If no HEAD handler, use GET handler if present
        if method == 'HEAD':
            head_routes = self.routes.get('HEAD', [])
            if head_routes:
                possible_routes = head_routes
            elif 'GET' in self.routes:
                # Fallback to GET handlers
                possible_routes = self.routes['GET']


        # Try matching routes in registration order
        for regex, converters, handler in possible_routes:
            match = regex.match(decoded_path)
            if match:
                # Extract parameters from regex groups
                params = {}
                param_names = list(converters.keys())

                for i, name in enumerate(param_names):
                    try:
                        value = match.group(i + 1)
                        converter = converters[name]

                        if converter == 'int':
                            params[name] = int(value)
                        elif converter == 'path':
                            # Path converter gets the whole matched string
                            params[name] = value
                        else: # str
                            params[name] = value
                    except IndexError:
                        # This should not happen if pattern compilation was correct
                        raise RuntimeError("Routing internal error: Parameter group missing")

                return handler, params

        # If we reached here, it means the method existed (or we were testing fallback) 
        # but no route matched the path for that method/fallback.

        # Re-check for MethodNotAllowed if we failed to match *any* route for the given method
        if method in self.routes:
             all_methods_for_path = set()
             for regex, _, _ in self.routes[method]:
                  if regex.match(decoded_path):
                       all_methods_for_path.add(method) # Should be true if we are iterating this list

             # If we failed to match here, something is fundamentally wrong, or the initial method check was misleading.
             # Re-raising based on the most generous interpretation:
             matching_paths_methods = set()
             for m, routes in self.routes.items():
                 for regex, _, _ in routes:
                     if regex.match(decoded_path):
                         matching_paths_methods.add(m)

             if matching_paths_methods:
                 raise MethodNotAllowed(sorted(list(matching_paths_methods)))
             else:
                 raise NotFound()
        else:
            # No routes registered for this method, and no general matches found above.
            raise NotFound()


    def _decode_path(self, path: str) -> str:
        """
        Decodes path segments. '+' stays '+'. Only percent-decodes.
        """

        # Split by '/' but we need to handle %2F specially if it's part of a segment
        # We must process byte-by-byte or use regex that respects segment boundaries.

        decoded_parts = []
        current_segment = ''

        # We iterate over the raw string, replacing separators if they aren't encoded.
        # Since we are operating on a string input path, we use string replacement logic 
        # mimicking byte decoding rules (where + is not a space).

        i = 0
        while i < len(path):
            char = path[i]

            if char == '%':
                if i + 2 >= len(path):
                    raise BadRequest(f"Malformed percent encoding in path: {path}")

                hex_code = path[i+1:i+3]
                try:
                    byte_val = int(hex_code, 16)
                    # Convert byte value back to character (assuming ASCII/UTF-8 context)
                    decoded_char = chr(byte_val)
                    i += 3
                    current_segment += decoded_char
                    continue
                except ValueError:
                    raise BadRequest(f"Invalid hex digits in percent encoding in path: {path}")

            elif char == '+':
                # '+' stays '+' in path decoding
                current_segment += '+'
                i += 1
                continue

            elif char == '/':
                # End of segment. Process segment.
                if current_segment:
                    decoded_parts.append(current_segment)
                current_segment = ''
                i += 1
                continue

            else:
                current_segment += char
                i += 1

        # Append the last segment
        if current_segment:
            decoded_parts.append(current_segment)

        # Rejoin with '/'
        return '/' + '/'.join(decoded_parts)


    def dispatch(self, request: Request) -> Response:
        """Resolves, stores params, calls handler, and returns response."""
        try:
            handler, params = self.resolve(request.method, request.path)

            # Store params
            request.params.update(params)

            # Call handler
            response = handler(request)

            # HEAD specific handling: ensure body is empty
            if request.method == 'HEAD':
                response.body = b''

            return response

        except NotFound:
            return Response.text("", status=404)
        except MethodNotAllowed as e:
            return Response.text(f"Method Not Allowed. Allowed: {', '.join(e.allowed)}", 
                                  status=405, headers=Headers().set('Allow', ", ".join(e.allowed)))
        except HTTPError as e:
            reason = get_reason(e.status)
            body_text = str(e) if e.status == 400 else f"{e.status} {reason}"
            return Response.text(body_text, status=e.status)
        except Exception:
            # Catch all other exceptions and return 500
            return Response.text("500 Internal Server Error", status=500)
