import base64
import json
from typing import Callable, List, Dict, Any

from .request import Request, Response, HTTPError, BadRequest, Headers, MethodNotAllowed

# --- Middleware Definition ---

MiddlewareFunc = Callable[[Request, Callable[[Request], Response]], Response]

class App:
    def __init__(self, router: 'Router', middleware: List[MiddlewareFunc] = None):
        self.router = router
        self.middleware: List[MiddlewareFunc] = middleware if middleware else []

    def use(self, mw: MiddlewareFunc):
        self.middleware.append(mw)

    def handle(self, request: Request) -> Response:
        """Runs the middleware chain."""

        # Innermost call is router dispatch
        def innermost_call(req: Request) -> Response:
            try:
                # This calls router.dispatch, which handles internal HTTPErrors -> Responses
                return self.router.dispatch(req)
            except Exception:
                # Catch exceptions raised *during* dispatch (should be rare if router handles all)
                return Response.text("500 Internal Server Error", status=500)

        # Wrap the chain using function composition pattern
        def chain_runner(mw_chain: Callable[[Request], Response], req: Request) -> Response:

            # Start with the innermost call
            next_func = innermost_call

            # Iterate backwards through middleware list (outermost first)
            for mw in reversed(self.middleware):
                # Create the next function in the chain: mw(req, next_func)
                # next_func here is the function that calls the *next* element in the chain
                next_func = lambda r: mw(r, next_func)

            # The final 'next_func' now wraps everything
            return next_func(req)

        try:
            return chain_runner(innermost_call, request)
        except Exception as e:
            # Catch exceptions raised by the outermost middleware itself
            print(f"Middleware chain failed with unhandled exception: {e}")
            return Response.text("500 Internal Server Error", status=500)


    def handle_bytes(self, data: bytes) -> bytes:
        """Parses bytes, handles, and returns response bytes."""
        try:
            request = self.router.parse_request(data)
        except BadRequest as e:
            # BadRequest from parsing results in 400 without running middleware
            status = e.status if isinstance(e, HTTPError) else 400
            reason = get_reason(status)
            return Response.text(f"{status} {reason}", status=status).to_bytes()
        except Exception:
            # Catch parsing errors not caught as BadRequest
            return Response.text("400 Bad Request", status=400).to_bytes()

        return self.handle(request).to_bytes()

# --- Middleware Factories ---

def logger(lines: List[str]) -> MiddlewareFunc:
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        response = call_next(request)

        reason = get_reason(response.status)
        lines.append(f"{request.method} {request.path} {response.status}")
        return response
    return mw

def cookies() -> MiddlewareFunc:
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        cookies_dict = {}
        cookie_header = request.headers.get('Cookie')

        if cookie_header:
            parts = [p.strip() for p in cookie_header.split(';') if p.strip()]

            for part in parts:
                if '=' in part:
                    name, value = part.split('=', 1)
                    name = name.strip() # Cookie names keep case
                    value = value.strip()

                    # Mimic Content-Type parameter parsing logic for values
                    if value.startswith('"') and value.endswith('"'):
                        value = value[1:-1]

                    if name not in cookies_dict:
                        cookies_dict[name] = value

        request.state['cookies'] = cookies_dict
        return call_next(request)
    return mw


def basic_auth(users: Dict[str, str], realm: str = 'app') -> MiddlewareFunc:
    def mw(request: Request, call_next: Callable[[Request], Response]) -> Response:
        auth_header = request.headers.get('Authorization')

        if not auth_header or not auth_header.startswith('Basic '):
            return call_next(request) # No auth provided, proceed

        token = auth_header[6:].strip()

        try:
            decoded_bytes = base64.b64decode(token)
            # Expect format user:password
            if b':' not in decoded_bytes:
                raise ValueError("Malformed auth token")

            username_bytes, password_bytes = decoded_bytes.split(b':', 1)
            username = username_bytes.decode('utf-8')

            if username in users and users[username] == password_bytes.decode('utf-8'):
                request.state['user'] = username
                return call_next(request)
            else:
                # Auth failed
                response = Response.text(f"401 Unauthorized", status=401)
                response.headers = response.headers.set('WWW-Authenticate', f'Basic realm="{realm}"')
                return response

        except Exception:
            # Decoding or parsing failed
            response = Response.text(f"401 Unauthorized", status=401)
            response.headers = response.headers.set('WWW-Authenticate', f'Basic realm="{realm}"')
            return response

    return mw
