import re
from typing import Dict, Any, Set, List
from .graph import DependencyGraph
from .formula import (
    FormulaError, ErrorValue, ERROR_GENERAL, ERROR_CYCLE, 
    parse_formula, references, evaluate
)

# --- Utility Functions ---

def _validate_cell_name(name: str):
    """Validates cell format (A1 to Z999)."""
    name = name.upper()
    if not name:
        raise ValueError("Cell name cannot be empty.")

    match = re.match(r"^[A-Z]{1,2}\d{1,3}$", name)
    if not match:
        raise ValueError(f"Invalid cell name format: {name}")

    col_part = match.group(0)[:1] # Only need the first letter for basic validation scope
    row_part = match.group(0)[1:]

    if len(col_part) > 1:
         # Although the grammar allows A-Z, the constraints specify A-Z. 
         # We strictly enforce single letter columns based on the prompt example (A-Z)
         raise ValueError(f"Column name exceeds single letter limit: {name}")

    try:
        row = int(row_part)
        if not (1 <= row <= 999):
            raise ValueError
        if str(row) != row_part: # Checks for leading zeros (e.g., '01')
            raise ValueError
    except ValueError:
        raise ValueError(f"Row number invalid or contains leading zeros: {name}")


def _get_all_cell_names() -> List[str]:
    """Generates all cell names in row-major order (A1, B1, ..., A2, B2, ...)."""
    all_names = []
    for r in range(1, 1000):
        for c_ord in range(26): # A=0 to Z=25
            col_letter = chr(65 + c_ord)
            name = f"{col_letter}{r}"
            all_names.append(name)
    return all_names

_ALL_CELL_NAMES = _get_all_cell_names()

# --- Sheet Implementation ---

class Sheet:
    def __init__(self):
        # Stores the raw input string for each cell
        self._raw_values: Dict[str, str] = {name: "" for name in _ALL_CELL_NAMES}
        # Stores the computed value (int, float, str, None, ErrorValue)
        self._values: Dict[str, Any] = {name: None for name in _ALL_CELL_NAMES}
        self.evaluations: int = 0
        self.graph = DependencyGraph()
        self._is_dirty = True

    def _check_name(self, name: str):
        """Helper to validate cell name format."""
        _validate_cell_name(name)

    def get(self, name: str) -> Any:
        self._check_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        self._check_name(name)
        return self._raw_values.get(name, "")

    def cells(self) -> List[str]:
        """Returns non-empty cells in row-major order."""
        return sorted([n for n in _ALL_CELL_NAMES if self.raw(n) != ""])

    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores input, triggers recalculation, and returns affected cells.
        """
        self._check_name(name)
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        old_raw = self._raw_values[name]
        if old_raw == raw:
            return [] # No change

        self._raw_values[name] = raw
        self._is_dirty = True

        # --- Step 1: Determine what needs recalculation ---

        # 1. Parse raw input to determine if it's a formula, number, or text
        cell_value = None
        is_formula = False

        raw_stripped = raw.strip()

        if raw_stripped.startswith('='):
            is_formula = True
            formula_source = raw_stripped[1:]
            try:
                tree = parse_formula(formula_source)
                precedents = references(tree)
                self.graph.set_dependencies(name.upper(), precedents)

                # Store AST/Formula tree implicitly by setting raw, but we need the tree for evaluation
                self._formula_tree = tree 

            except FormulaError as e:
                # Re-raise immediately if parsing fails, sheet state is unchanged
                raise e
        else:
            # Attempt to parse as a number
            try:
                if '.' in raw_stripped:
                    cell_value = float(raw_stripped)
                else:
                    cell_value = int(raw_stripped)
            except ValueError:
                # Otherwise, it's text
                cell_value = raw_stripped

        # If it wasn't a formula, we treat the input as the final value immediately
        if not is_formula:
            self._values[name] = cell_value
            self._is_dirty = True
            return [name]

        # --- Step 2: Recalculation Trigger ---

        # Identify all cells affected by this change
        # We need to calculate ALL dependents transitively, including self if it depends on itself.
        affected_cells = self.graph.all_dependents(name.upper())

        # Also include the cell itself, which might be needed for cycle checking later
        affected_cells.add(name.upper())

        # Sort affected cells in row-major order (important for calculation order)
        affected_cells_list = sorted(list(affected_cells), key=lambda n: (int(n[1:]), n[0]))

        # --- Step 3: Perform Recalculation ---

        if not self._is_dirty:
            # Should only happen if the set was triggered but no value changed in _raw_values
            return []

        # Reset state before full recalculation sweep
        self._values = {n: None for n in _ALL_CELL_NAMES}
        self.evaluations = 0

        # We must iterate over all cells in row-major order to ensure dependencies are met.
        # However, we only need to calculate the cells in affected_cells_list *if* they are formulas.

        # Since the rule states: "After every set, every cell's value is as if the whole sheet had been calculated from scratch."
        # We iterate over ALL cells in order, but only calculate formulas that are affected or are necessary precursors.

        recalculated_set: Set[str] = set()

        for current_name in _ALL_CELL_NAMES:
            if current_name not in affected_cells:
                # If this cell wasn't affected by the change, its value remains as it was *before* this set call,
                # unless it is a dependency of an affected cell that needed updating.
                # Due to the requirement: "After every set, every cell's value is as if the whole sheet had been calculated from scratch."
                # We must calculate everything, but only count evaluations for affected cells.
                pass 

            raw_input = self._raw_values[current_name]

            if not raw_input.startswith('='):
                # Not a formula, value is fixed (number or text)
                if raw_input == "":
                    self._values[current_name] = None
                else:
                    try:
                        if '.' in raw_input:
                            self._values[current_name] = float(raw_input)
                        else:
                            self._values[current_name] = int(raw_input)
                    except ValueError:
                        self._values[current_name] = raw_input # Text
                continue

            # --- Formula Evaluation ---

            # If it's a formula, we must ensure its dependency tree is correctly built (it should be, via set_dependencies)
            if not hasattr(self, '_formula_tree') or self._raw_values[current_name] != f"={self._raw_values[current_name]}":
                 # Re-parse if needed, though dependency update should handle this.
                 try:
                     tree = parse_formula(self._raw_values[current_name][1:])
                 except FormulaError:
                     # Should not happen if set() was called correctly
                     self._values[current_name] = ERROR_GENERAL
                     continue
                 self._formula_tree = tree


            # 1. Cycle Check
            is_on_cycle = current_name in self.graph.cycle_cells()
            if is_on_cycle:
                self._values[current_name] = ERROR_CYCLE
                continue

            # 2. Evaluate
            try:
                # Lookup function for evaluation uses the current state of self._values
                def lookup_func(cell_name: str):
                    # If the lookup is for a cycle cell, it returns ERROR_CYCLE immediately
                    if cell_name in self.graph.cycle_cells():
                         return ERROR_CYCLE
                    return self._values.get(cell_name)

                new_value = evaluate(self._formula_tree, lookup_func)

                # Rule 3 check: If any operand was an error, the result is that error.
                # The 'evaluate' function handles this propagation.

                self._values[current_name] = new_value

                if current_name in affected_cells:
                    self.evaluations += 1
                    recalculated_set.add(current_name)

            except FormulaError as e:
                self._values[current_name] = ERROR_GENERAL
            except Exception:
                 # Catching other unexpected evaluation errors
                self._values[current_name] = ERROR_GENERAL


        # Return cells that were actually re-evaluated due to the change
        return sorted(list(recalculated_set), key=lambda n: (int(n[1:]), n[0]))

    def __repr__(self):
        return f"<Sheet evaluations={self.evaluations}>"

