Here are the updated files for the extended `sheet` package.

### `sheet/formula.py`

```python
import re
from typing import Any, Union, Tuple, List, Set, Dict

# --- Error and Value Definitions ---

class ErrorValue(str):
    """Represents a calculation error, subclassing str for equality checks."""
    pass

# Updated Error Values
ERROR_DIV_ZERO = ErrorValue("#DIV/0!")
ERROR_VALUE = ErrorValue("#VALUE!")
ERROR_REF = ErrorValue("#REF!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- AST Node Definitions ---

class NumberLiteral:
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode:
    def __init__(self, name: str):
        self.name = name

class RangeNode:
    def __init__(self, start: str, end: str):
        self.start = start
        self.end = end

class BinaryOpNode:
    def __init__(self, left: Any, op: str, right: Any):
        self.left = left
        self.op = op  # '+', '-', '*', '/'
        self.right = right

class UnaryOpNode:
    def __init__(self, op: str, operand: Any):
        self.op = op  # '+', '-'
        self.operand = operand

class ParenExprNode:
    def __init__(self, expression: Any):
        self.expression = expression

class CallNode:
    def __init__(self, func_name: str, args: List[Any]):
        self.func_name = func_name
        self.args = args

# --- Formula Parsing ---

# Grammar Tokens (simplified for parsing structure)
TOKEN_TYPES = {
    'NUMBER': r'\d+(\.\d*)?',
    'REF': r'[A-Z]+\d+',
    'OP': r'[+\-*/]',
    'LPAREN': r'\(',
    'RPAREN': r'\)',
    'COLON': r':',
    'COMMA': r',',
    'WHITESPACE': r'\s+'
}

TOKEN_REGEX = '|'.join(f'(?P<{name}>{regex})' for name, regex in TOKEN_TYPES.items())

class Token:
    def __init__(self, type: str, value: str):
        self.type = type
        self.value = value

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.tokens: List[Token] = []
        self._tokenize()

    def _tokenize(self):
        for mo in re.finditer(TOKEN_REGEX, self.text):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'WHITESPACE':
                continue
            elif kind == 'OP' and value in ('+', '-', '*', '/'):
                # Handle unary vs binary operators later during parsing
                self.tokens.append(Token('OP', value))
            elif kind == 'OP' and value in ('+', '-'):
                 # Treat +/- as potential unary/binary
                self.tokens.append(Token('OP', value))
            elif kind == 'REF':
                self.tokens.append(Token('REF', value.upper()))
            else:
                self.tokens.append(Token(kind, value))
        self.tokens.append(Token('EOF', 'EOF'))

# --- Parser (Recursive Descent Skeleton) ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        return self.tokens[self.pos]

    def advance(self):
        self.pos += 1

    def consume(self, expected_type: str, expected_value: str = None):
        token = self.current_token()
        if token.type != expected_type or (expected_value and token.value != expected_value):
            raise FormulaError(f"Expected {expected_type}" + (f" with value {expected_value}" if expected_value else ""))
        self.advance()
        return token

    def parse(self) -> Any:
        """Entry point: Parses the entire expression."""
        expr = self._parse_expr()
        self.consume('EOF')
        return expr

    def _parse_expr(self) -> Any:
        # expr := term {(+ | -) term}
        node = self._parse_term()

        while self.current_token().type == 'OP' and self.current_token().value in ('+', '-'):
            op_token = self.current_token()
            self.advance()
            right = self._parse_term()
            node = BinaryOpNode(node, op_token.value, right)

        return node

    def _parse_term(self) -> Any:
        # term := unary {(* | /) unary}
        node = self._parse_unary()

        while self.current_token().type == 'OP' and self.current_token().value in ('*', '/'):
            op_token = self.current_token()
            self.advance()
            right = self._parse_unary()
            node = BinaryOpNode(node, op_token.value, right)

        return node

    def _parse_unary(self) -> Any:
        # unary := (+ | -) unary | number | ref | call | ( expr )
        token = self.current_token()

        # Unary sign (+ or -)
        if token.type == 'OP' and token.value in ('+', '-'):
            op = token.value
            self.advance()
            operand = self._parse_unary()
            return UnaryOpNode(op, operand)

        # Grouping
        if token.type == 'LPAREN':
            self.advance() # Consume '('
            expr = self._parse_expr()
            self.consume('RPAREN') # Consume ')'
            return ParenExprNode(expr)

        # Call function
        if token.type == 'REF' and self.tokens[self.pos+1].type == 'LPAREN':
            return self._parse_call()

        # Number literal
        if token.type == 'NUMBER':
            self.advance()
            return NumberLiteral(float(token.value) if '.' in token.value else int(token.value))

        # Reference
        if token.type == 'REF':
            self.advance()
            return RefNode(token.value)

        raise FormulaError(f"Unexpected token in unary position: {token.type} {token.value}")

    def _parse_call(self) -> CallNode:
        # call  := fname ( arg {, arg} )
        fname_token = self.consume('REF')
        func_name = fname_token.value
        self.consume('LPAREN') # Consume '('

        args: List[Any] = []

        # Handle empty arguments
        if self.current_token().type != 'RPAREN':
            args.append(self._parse_arg())

            while self.current_token().type == 'COMMA':
                self.advance() # Consume ','
                args.append(self._parse_arg())

        self.consume('RPAREN') # Consume ')'
        return CallNode(func_name, args)

    def _parse_arg(self) -> Any:
        # arg := ref : ref | expr
        token = self.current_token()

        # Range: ref : ref
        if token.type == 'REF' and self.tokens[self.pos+1].type == 'COLON':
            start_ref = self.consume('REF').value
            self.advance() # Consume ':'
            end_ref = self.consume('REF').value
            return RangeNode(start_ref, end_ref)

        # Expression (Ref or Parenthesized expression)
        return self._parse_expr()


def parse_formula(source: str) -> Any:
    """ Parses the formula text after = into an AST. """
    if not source.strip():
        raise FormulaError("Formula source cannot be empty.")

    lexer = Lexer(source)
    parser = Parser(lexer.tokens)
    return parser.parse()

# --- Range Handling ---

def _get_range_cells(start_name: str, end_name: str) -> Set[str]:
    """
    Returns the set of all unique, valid cell names within the rectangular range 
    defined by two corner names.
    """
    from .sheet import _ALL_CELL_NAMES # Import necessary list from Sheet module scope

    # 1. Parse coordinates
    def parse_coord(name: str) -> Tuple[int, int]:
        col_char = name[0]
        row = int(name[1:])
        col = ord(col_char) - ord('A')
        return col, row

    try:
        c1, r1 = parse_coord(start_name)
        c2, r2 = parse_coord(end_name)
    except ValueError:
        # This should be caught by the caller if they used _validate_cell_name, 
        # but we handle parsing failures here robustly.
        return set() 

    # 2. Determine bounds
    min_c = min(c1, c2)
    max_c = max(c1, c2)
    min_r = min(r1, r2)
    max_r = max(r1, r2)

    cells = set()
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            col_letter = chr(ord('A') + c)
            name = f"{col_letter}{r}"
            # Check if the cell name is valid within the sheet's defined structure
            if name in _ALL_CELL_NAMES:
                cells.add(name)
    return cells

def references(tree: Any) -> Set[str]:
    """ Recursively finds all cell references in the AST, respecting range expansion. """

    def _traverse(node):
        if isinstance(node, RefNode):
            return {node.name}
        if isinstance(node, RangeNode):
            # Range references *all* contained cells.
            # We need access to _ALL_CELL_NAMES, assuming it's available or passed.
            from .sheet import _ALL_CELL_NAMES

            # Since references() is called *before* sheet evaluation, we only return names
            # that are structurally valid inside the sheet boundaries (which _get_range_cells handles).
            return _get_range_cells(node.start, node.end)

        if isinstance(node, BinaryOpNode):
            return _traverse(node.left) | _traverse(node.right)
        if isinstance(node, UnaryOpNode):
            return _traverse(node.operand)
        if isinstance(node, ParenExprNode):
            return _traverse(node.expression)
        if isinstance(node, CallNode):
            all_refs = set()
            for arg in node.args:
                all_refs.update(_traverse(arg))
            return all_refs

        return set()

    return _traverse(tree)

# --- Evaluation ---

def evaluate(tree: Any, lookup: callable) -> Any:
    """
    Computes the value of the formula AST given the cell lookup function.
    """

    if isinstance(tree, NumberLiteral):
        return tree.value

    if isinstance(tree, RefNode):
        # Rule 2 & 3: Reference handling
        cell_value = lookup(tree.name)

        if cell_value is ERROR_REF:
            return ERROR_REF
        if cell_value is None:
            # Empty cell reference gives 0 for arithmetic contexts
            return 0

        # Rule 2: If cell holds text, return text.
        if isinstance(cell_value, str) and cell_value not in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE):
            return cell_value

        # Return computed value (number or error)
        return cell_value

    if isinstance(tree, RangeNode):
        # Range evaluation: Collect numbers, check for errors.

        def range_lookup(name: str) -> Any:
            # This function must be supplied by the Sheet context to check validity
            return lookup(name)

        cells = _get_range_cells(tree.start, tree.end)
        numbers = []

        for cell_name in cells:
            val = range_lookup(cell_name)

            if val is ERROR_CYCLE:
                return ERROR_CYCLE
            if val is ERROR_REF:
                return ERROR_REF
            if val is None:
                continue # Skip empty cells

            if isinstance(val, str) and val not in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE):
                # Text in a range context results in #VALUE! immediately
                return ERROR_VALUE

            if isinstance(val, (int, float)):
                numbers.append(val)
            elif isinstance(val, ErrorValue):
                 # If the cell holds an error, propagate it immediately (leftmost error principle)
                return val

        # Range itself does not return a single value, it returns a collection of numbers
        return numbers

    if isinstance(tree, CallNode):
        # Function Evaluation
        func_name = tree.func_name
        args_evaluated = []

        # 1. Evaluate all arguments
        for arg_tree in tree.args:
            arg_result = evaluate(arg_tree, lookup)

            # 2. Check for early exit errors
            if arg_result in (ERROR_CYCLE, ERROR_REF):
                return arg_result

            if isinstance(arg_result, ErrorValue):
                # If an argument evaluates to an error, the function result is that error
                if func_name == 'AVG' and arg_result == ERROR_DIV_ZERO:
                     return ERROR_DIV_ZERO # Specific rule for AVG(empty)
                return arg_result

            args_evaluated.append(arg_result)

        # 3. Compute based on function name
        if func_name == "SUM":
            if not args_evaluated:
                return 0

            total = 0
            is_float = False
            for arg in args_evaluated:
                if isinstance(arg, float):
                    is_float = True
                    break
                total += arg
            return total if is_float else int(total)

        elif func_name == "AVG":
            if not args_evaluated:
                return ERROR_DIV_ZERO

            total = sum(args_evaluated)
            return total / len(args_evaluated)

        elif func_name == "MIN":
            if not args_evaluated:
                return 0
            return min(args_evaluated)

        elif func_name == "MAX":
            if not args_evaluated:
                return 0
            return max(args_evaluated)

        else:
            # Should be caught during parsing
            return ERROR_VALUE


    if isinstance(tree, BinaryOpNode):
        left_val = evaluate(tree.left, lookup)
        right_val = evaluate(tree.right, lookup)
        op = tree.op

        # --- Error Propagation ---

        # Leftmost error wins, unless both are text, then it's #VALUE!
        if left_val in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE):
            return left_val
        if right_val in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE):
            return right_val

        if isinstance(left_val, str) and left_val not in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE) and \
           isinstance(right_val, str) and right_val not in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE):
            # Text operand used in arithmetic
            return ERROR_VALUE

        # --- Arithmetic ---
        try:
            if op == '+':
                return left_val + right_val
            elif op == '-':
                return left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    return ERROR_DIV_ZERO
                # Division always results in float
                return left_val / right_val
        except TypeError:
            # Type mismatch during operation
            return ERROR_VALUE

    if isinstance(tree, UnaryOpNode):
        operand_val = evaluate(tree.operand, lookup)
        op = tree.op

        if operand_val in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE):
            return operand_val

        if isinstance(operand_val, str) and operand_val not in (ERROR_CYCLE, ERROR_REF, ERROR_DIV_ZERO, ERROR_VALUE):
            # Text used with unary operator
            return ERROR_VALUE

        try:
            if op == '+':
                return operand_val + 0
            elif op == '-':
                return operand_val * -1
        except TypeError:
            return ERROR_VALUE

    if isinstance(tree, ParenExprNode):
        return evaluate(tree.expression, lookup)

    raise FormulaError("Unknown AST node encountered during evaluation.")
