```python
from typing import Dict, Set, Iterable

class DependencyGraph:
    """
    Records dependencies between cells (precedents and dependents).
    All cell names are assumed to be UPPERCASE.
    """
    def __init__(self):
        # Cell -> Set of cells it depends on (Precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # Cell -> Set of cells that depend on it (Dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Sets the direct precedents for a given cell."""
        self._precedents[cell] = set(precedents)

        # Rebuild dependents structure based on new precedents for this cell
        self._rebuild_dependents(cell)

    def _rebuild_dependents(self, cell: str):
        """Clears and rebuilds the dependent set for 'cell' and all affected cells."""
        # Reset dependents for 'cell'
        self._dependents[cell] = set()

        # Clear existing incoming links to 'cell' from others
        for c in list(self._dependents.keys()):
            if cell in self._dependents.get(c, set()):
                self._dependents[c].remove(cell)

        # Set new dependents based on current state
        for dependent, preds in self._precedents.items():
            if dependent == cell:
                continue
            for pred in preds:
                if pred in self._precedents: # Ensure precedent exists
                    self._dependents[pred].add(dependent)

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct set of cells that 'cell' refers to."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct set of cells that refer to 'cell'."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """
        Returns every cell that refers to 'cell' directly or transitively.
        Includes 'cell' itself only if it is on a cycle.
        """
        if cell not in self._precedents and cell not in self._dependents:
            return set()

        queue = list(self.dependents.get(cell, set()))
        visited = set(self.dependents.get(cell, set()))
        result = set(self.dependents.get(cell, set()))

        while queue:
            current = queue.pop(0)
            if current not in visited:
                visited.add(current)
                result.add(current)

                for neighbor in self.dependents.get(current, set()):
                    if neighbor not in visited:
                        queue.append(neighbor)

        # Cycle detection check (self-referential cycle)
        stack = [cell]
        cycle_check = {cell}
        on_cycle = False

        while stack:
            c = stack.pop()
            if c in self._precedents:
                for p in self._precedents[c]:
                    if p == cell:
                        on_cycle = True
                        break
                    if p not in cycle_check:
                        cycle_check.add(p)
                        stack.append(p)
            if on_cycle:
                break

        if on_cycle:
            result.add(cell)

        return result


    def cycle_cells(self) -> Set[str]:
        """
        Returns every cell that lies on a cycle (a cell from which following precedents
        leads back to itself).
        """
        cycle_nodes: Set[str] = set()
        all_cells = set(self._precedents.keys())

        for cell in all_cells:
            # Standard DFS cycle detection on the precedent graph
            visiting: Set[str] = set()
            visited: Set[str] = set()

            def dfs(node: str) -> bool:
                if node in visiting:
                    return True  # Cycle detected
                if node in visited:
                    return False

                visiting.add(node)

                for neighbor in self._precedents.get(node, set()):
                    if dfs(neighbor):
                        return True

                visiting.remove(node)
                visited.add(node)
                return False

            if dfs(cell):
                cycle_nodes.add(cell)

        return cycle_nodes
