import re
from typing import Dict, Any, Set, List
from .graph import DependencyGraph
from .formula import (
    FormulaError, ErrorValue, ERROR_DIV_ZERO, ERROR_VALUE, ERROR_REF, ERROR_CYCLE,
    parse_formula, references, evaluate
)

# --- Utility Functions ---

def _validate_cell_name(name: str):
    """Validates cell format (A1 to Z999)."""
    name = name.upper()
    if not name:
        raise ValueError("Cell name cannot be empty.")

    # Regex allows letters up to 26 (one column) followed by 1-3 digits.
    match = re.match(r"^[A-Z]\d{1,3}$", name)
    if not match:
        raise ValueError(f"Invalid cell name format or structure: {name}")

    # Row validation
    row_part = name[1:]
    try:
        row = int(row_part)
        if not (1 <= row <= 999):
            raise ValueError
        if str(row) != row_part: # Checks for leading zeros (e.g., '01')
            raise ValueError
    except ValueError:
        raise ValueError(f"Row number invalid or contains leading zeros: {name}")


def _get_all_cell_names() -> List[str]:
    """Generates all cell names in row-major order (A1, B1, ..., Z999)."""
    all_names = []
    for r in range(1, 1000):
        for c_ord in range(26): # A=0 to Z=25
            col_letter = chr(65 + c_ord)
            name = f"{col_letter}{r}"
            all_names.append(name)
    return all_names

_ALL_CELL_NAMES = _get_all_cell_names()

# --- Sheet Implementation ---

class Sheet:
    def __init__(self):
        # Stores the raw input string for each cell
        self._raw_values: Dict[str, str] = {name: "" for name in _ALL_CELL_NAMES}
        # Stores the computed value (int, float, str, None, ErrorValue)
        self._values: Dict[str, Any] = {name: None for name in _ALL_CELL_NAMES}
        self.evaluations: int = 0
        self.graph = DependencyGraph()
        self._is_dirty = True
        self._formula_trees: Dict[str, Any] = {} # Cache for parsed trees

    def _check_name(self, name: str):
        """Helper to validate cell name format."""
        _validate_cell_name(name)

    def get(self, name: str) -> Any:
        self._check_name(name)
        return self._values.get(name)

    def raw(self, name: str) -> str:
        self._check_name(name)
        return self._raw_values.get(name, "")

    def cells(self) -> List[str]:
        """Returns non-empty cells in row-major order."""
        return sorted([n for n in _ALL_CELL_NAMES if self.raw(n) != ""])

    def set(self, name: str, raw: str) -> List[str]:
        """
        Stores input, triggers recalculation, and returns affected cells.
        """
        self._check_name(name)
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        old_raw = self._raw_values[name]
        if old_raw == raw:
            return [] # No change

        self._raw_values[name] = raw
        self._is_dirty = True
        self._formula_trees.pop(name, None) # Invalidate cached tree for this cell

        # --- Step 1: Parsing and Dependency Update ---

        is_formula = raw.strip().startswith('=')

        if is_formula:
            formula_source = raw.strip()[1:]
            try:
                tree = parse_formula(formula_source)
                precedents = references(tree)
                self.graph.set_dependencies(name.upper(), precedents)
                self._formula_trees[name.upper()] = tree
            except FormulaError as e:
                # Re-raise immediately if parsing fails, sheet state is unchanged
                raise e

        # --- Step 2: Recalculation Trigger & Setup ---

        affected_cells = set()
        if is_formula:
            # Identify all cells affected by this change
            affected_cells = self.graph.all_dependents(name.upper())
            affected_cells.add(name.upper())
        else:
            # If not a formula, only the cell itself might change immediately
            affected_cells.add(name.upper())


        # --- Step 3: Perform Recalculation (Full Sweep) ---

        # Reset state for full recalculation sweep
        self._values = {n: None for n in _ALL_CELL_NAMES}
        self.evaluations = 0

        recalculated_set: Set[str] = set()

        for current_name in _ALL_CELL_NAMES:
            raw_input = self._raw_values[current_name]

            if not raw_input.startswith('='):
                # Not a formula: fixed value
                if raw_input == "":
                    self._values[current_name] = None
                else:
                    try:
                        if '.' in raw_input:
                            self._values[current_name] = float(raw_input)
                        else:
                            self._values[current_name] = int(raw_input)
                    except ValueError:
                        self._values[current_name] = raw_input # Text
                continue

            # --- Formula Evaluation ---

            # Get the tree (it must exist if the cell is a formula)
            tree = self._formula_trees.get(current_name)
            if tree is None:
                 # Should not happen if set() was called correctly, but handle safety.
                 self._values[current_name] = ERROR_GENERAL
                 continue

            # 1. Cycle Check
            is_on_cycle = current_name in self.graph.cycle_cells()
            if is_on_cycle:
                self._values[current_name] = ERROR_CYCLE
                continue

            # 2. Evaluation Lookup Definition
            def lookup_func(cell_name: str):
                # If the lookup is for a cycle cell, it returns ERROR_CYCLE immediately
                if cell_name in self.graph.cycle_cells():
                     return ERROR_CYCLE
                return self._values.get(cell_name)

            # 3. Execute Evaluation
            try:
                new_value = evaluate(tree, lookup_func)
                self._values[current_name] = new_value

                # Count evaluation only if this cell was in the set of affected cells
                if current_name in affected_cells:
                    self.evaluations += 1
                    recalculated_set.add(current_name)

            except Exception:
                # General catch-all for unforeseen evaluation failures
                self._values[current_name] = ERROR_GENERAL

        # Return the list of cells that were calculated due to the change
        return sorted(list(recalculated_set), key=lambda n: (int(n[1:]), n[0]))
