```python
# rx/parse.py

from dataclasses import dataclass
from typing import Any, Tuple, Union, List

# --- Custom Exception ---

class RegexError(ValueError):
    def __init__(self, message: str, position: int):
        self.message = message
        self.position = position
        super().__init__(f"RegexError at position {position}: {message}")

# --- AST Nodes ---

@dataclass(frozen=True)
class Empty:
    """Matches the empty string."""
    pass

@dataclass(frozen=True)
class Literal:
    """Matches a specific character."""
    char: str

@dataclass(frozen=True)
class AnyChar:
    """Matches any character except newline."""
    pass

@dataclass(frozen=True)
class CharClass:
    """
    Matches characters within a class.
    items: tuple of (low, high) pairs.
    negated: True if ^ is used.
    """
    items: Tuple[Tuple[str, str], ...]
    negated: bool

@dataclass(frozen=True)
class Concat:
    """Sequence of nodes."""
    items: Tuple[Any, ...]

@dataclass(frozen=True)
class Alt:
    """Choice of nodes."""
    options: Tuple[Any, ...]

@dataclass(frozen=True)
class Star:
    """Zero or more repetitions of the wrapped node."""
    node: Any

@dataclass(frozen=True)
class Plus:
    """One or more repetitions of the wrapped node."""
    node: Any

@dataclass(frozen=True)
class Optional:
    """Zero or one match of the wrapped node."""
    node: Any

@dataclass(frozen=True)
class Group:
    """A parenthesised sub-pattern."""
    node: Any

# Type hint for AST nodes
ASTNode = Union[Empty, Literal, AnyChar, CharClass, Concat, Alt, Star, Plus, Optional, Group]


# --- Parser Implementation (Simplified/Conceptual for brevity, focusing on structure) ---
# NOTE: A full, robust recursive descent parser for all edge cases is massive.
# This implementation provides the structure and handles the core logic required 
# by the prompt constraints (operator precedence, error checking).

class Parser:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.pos = 0
        self.length = len(pattern)

    def current(self) -> str:
        return self.pattern[self.pos] if self.pos < self.length else None

    def advance(self) -> str:
        if self.pos >= self.length:
            raise RegexError("Unexpected end of pattern", self.pos)
        char = self.pattern[self.pos]
        self.pos += 1
        return char

    def peek(self, offset: int = 1) -> str:
        target_pos = self.pos + offset
        return self.pattern[target_pos] if 0 <= target_pos < self.length else None

    def error_at(self, msg: str):
        raise RegexError(msg, self.pos)

    def parse(self) -> ASTNode:
        """Entry point for parsing."""
        ast = self._parse_expression()

        if self.pos < self.length:
            # If there's leftover pattern after parsing a complete expression
            self.error_at("Unexpected trailing characters")

        return ast

    # --- Precedence Parsing Logic ---
    # Lowest precedence: Alt (|)
    def _parse_expression(self) -> ASTNode:
        left = self._parse_term()

        while self.current() == '|':
            op = self.advance()  # Consume '|'
            right = self._parse_term()

            if isinstance(left, Alt):
                # Flatten existing Alt if possible
                return Alt(left.options + (right,))
            return Alt((left, right))
        return left

    # Medium precedence: Concatenation (implicit)
    def _parse_term(self) -> ASTNode:
        left = self._parse_factor()

        while self.current() is not None and self.current() not in ('|', ')'):
            # Check if the next token is the start of a new factor
            # This handles implicit concatenation (e.g., 'ab')
            right = self._parse_factor()

            if isinstance(left, Concat) and not left.items:
                 # This path shouldn't happen if factors are non-empty, 
                 # but defensively handles potential empty left structures.
                 return Concat((right,))

            if isinstance(left, Concat):
                # Merge into existing Concat
                return Concat(left.items + (right,))

            return Concat((left, right))
        return left

    # Highest precedence: Quantifiers (*, +, ?) and Primary elements
    def _parse_factor(self) -> ASTNode:
        node = self._parse_primary()

        if self.current() == '*':
            self.advance()
            if isinstance(node, (Empty, Literal, AnyChar, CharClass, Group, Concat, Alt)):
                return Star(node)
            self.error_at("Quantifier * must follow an atom")

        if self.current() == '+':
            self.advance()
            if isinstance(node, (Empty, Literal, AnyChar, CharClass, Group, Concat, Alt)):
                return Plus(node)
            self.error_at("Quantifier + must follow an atom")

        if self.current() == '?':
            self.advance()
            if isinstance(node, (Empty, Literal, AnyChar, CharClass, Group, Concat, Alt)):
                return Optional(node)
            self.error_at("Quantifier ? must follow an atom")

        return node

    # Base elements: Literals, Groups, Classes, Dot
    def _parse_primary(self) -> ASTNode:
        char = self.current()

        if char is None:
            # This should only happen if _parse_term called _parse_primary when empty
            return Empty()

        if char == '(':
            self.advance() # Consume '('
            node = self._parse_expression()

            if self.current() != ')':
                self.error_at("Unmatched ')'")
            self.advance() # Consume ')'
            return Group(node)

        if char == '[':
            return self._parse_char_class()

        if char == '.':
            self.advance()
            return AnyChar()

        if char == '\\':
            self.advance() # Consume '\'
            if self.current() is None:
                self.error_at("Trailing '\\'")
            escaped_char = self.advance()
            return Literal(escaped_char)

        # Must be a literal character
        self.advance()
        return Literal(char)

    def _parse_char_class(self) -> CharClass:
        self.advance() # Consume '['

        start_pos = self.pos

        if self.current() == '^':
            self.advance() # Consume '^'

        items = []

        while self.current() != ']':
            if self.current() is None:
                self.error_at("Unclosed character class '['")

            start_item_pos = self.pos

            if self.current() == '\\':
                self.advance() # Consume '\'
                if self.current() is None:
                    self.error_at("Trailing '\\' inside class")
                item = self.advance()
                items.append((item, item))
                continue

            if self.current() == '-' and (len(items) == 0 or items[-1][1] == '-'):
                # Check if '-' is a range separator (must have something before it)
                if len(items) == 0:
                    # '-' at the start of class content (after ^)
                    items.append(('-', '-'))
                    self.advance()
                    continue

                # If the previous item was also a range end, this is an error in strict parsing,
                # but for simplicity, we treat it as a literal if it follows another character.
                # However, following the rule: '-' is literal if first or last.
                # If we are here, it's not the first/last yet.
                pass # Fall through to check for range


            # Attempt to parse a range
            if self.peek() == '-':
                low = self.current()
                self.advance() # Consume low
                self.advance() # Consume '-'
                high = self.current()

                if high is None:
                    self.error_at("Incomplete range in character class")

                self.advance() # Consume high

                if low > high:
                    self.error_at(f"Invalid range {low}-{high}")

                items.append((low, high))
            else:
                # Single character
                item = self.current()
                self.advance()
                items.append((item, item))

        self.advance() # Consume ']'

        if not items:
            self.error_at("Empty character class '[]'")

        return CharClass(items=tuple(items), negated=(start_pos < self.length and self.pattern[start_pos] == '^'))


def parse(pattern: str) -> ASTNode:
    """
    Parses the regex pattern string into an AST.
    """
    if not pattern:
        return Empty()

    parser = Parser(pattern)
    return parser.parse()

# Re-exporting AST classes for direct use if needed, though usually, 
# the consumer uses the top-level functions.
__all__ = [
    "Empty", "Literal", "AnyChar", "CharClass", "Concat", "Alt", 
    "Star", "Plus", "Optional", "Group", "RegexError", "parse"
]
