# --- Definitions ---

Token = namedtuple('Token', ['kind', 'value', 'line', 'column'])
JSONError = namedtuple('JSONError', ['msg', 'line', 'column'])

# --- Scanner Implementation ---

def tokenize(text: str) -> list[Token]:
    """
    Tokenizes the input JSON text into a list of Token objects.
    """
    tokens = []
    line = 1
    column = 1
    i = 0
    n = len(text)

    def advance(char):
        nonlocal line, column
        if char == '\n':
            line += 1
            column = 1
        elif char == '\r':
            # Treat \r as whitespace, moving to next char, but not ending the line count change unless followed by \n
            # For simplicity in tracking, we treat \r like space unless it's followed by \n, but since we only advance char by char,
            # we just reset column if it's not a newline.
            column = 1
        else:
            column += 1
        return char

    def error(msg, start_i, start_line, start_col):
        raise JSONError(msg, start_line, start_col)

    while i < n:
        char = text[i]

        # Check for whitespace (and consume it)
        if char in ' \t\n\r':
            if char == '\n':
                line += 1
                column = 1
            elif char == '\r':
                # If \r is not followed by \n, it just increments column count for the current line
                column += 1
            else: # ' ' or '\t'
                column += 1
            i += 1
            continue

        # --- Single Character Tokens ---
        if char == '{':
            tokens.append(Token('LBRACE', None, line, column))
            i += 1
            continue
        if char == '}':
            tokens.append(Token('RBRACE', None, line, column))
            i += 1
            continue
        if char == '[':
            tokens.append(Token('LBRACKET', None, line, column))
            i += 1
            continue
        if char == ']':
            tokens.append(Token('RBRACKET', None, line, column))
            i += 1
            continue
        if char == ':':
            tokens.append(Token('COLON', None, line, column))
            i += 1
            continue
        if char == ',':
            tokens.append(Token('COMMA', None, line, column))
            i += 1
            continue

        # --- String Token ---
        if char == '"':
            start_line = line
            start_col = column
            i += 1
            start = i
            value_chars = []

            while i < n:
                char = text[i]
                if char == '"' and text[i-1] != '\\':
                    # End of string
                    break

                if char == '\\':
                    i += 1
                    if i >= n:
                        raise error("Unterminated string: expected closing '\"'", start_i, start_line, start_col)

                    escape_char = text[i]
                    if escape_char in ('"', '\\', '/', 'b', 'f', 'n', 'r', 't'):
                        if escape_char == 'n':
                            value_chars.append('\n')
                        elif escape_char == 'r':
                            value_chars.append('\r')
                        elif escape_char == 't':
                            value_chars.append('\t')
                        elif escape_char == 'b':
                            value_chars.append('\b')
                        elif escape_char == 'f':
                            value_chars.append('\f')
                        elif escape_char == '"':
                            value_chars.append('"')
                        elif escape_char == '\\':
                            value_chars.append('\\')
                        elif escape_char == '/':
                            value_chars.append('/')
                        elif escape_char == 'u':
                            # Unicode escape: \uXXXX
                            if i + 4 >= n:
                                raise error("Invalid escape sequence: expected 4 hex digits after \\u", i, line, column)

                            hex_digits = text[i+1 : i+5]
                            try:
                                code_point_str = hex_digits
                                code_point = int(code_point_str, 16)

                                # Handle surrogates manually for correct character decoding
                                if 0xD800 <= code_point <= 0xDBFF: # High surrogate
                                    if i + 5 >= n or text[i+5] != '\\': # Check if followed by \u
                                        raise error("High surrogate \\uXXXX not followed by low surrogate \\uYYYY", i, line, column)

                                    # Check if the next sequence is a valid low surrogate
                                    low_surrogate_start = i + 5
                                    if low_surrogate_start + 4 > n or text[low_surrogate_start] != '\\':
                                        raise error("High surrogate \\uXXXX not followed by second \\u escape", i, line, column)

                                    low_hex_digits = text[low_surrogate_start + 1 : low_surrogate_start + 5]
                                    try:
                                        low_code_point = int(low_hex_digits, 16)
                                    except ValueError:
                                        raise error("Invalid hex digits in second surrogate escape", low_surrogate_start + 1, line, column)

                                    if not (0xDC00 <= low_code_point <= 0xDFFF):
                                        raise error("Low surrogate \\uYYYY not found after high surrogate", low_surrogate_start + 1, line, column)

                                    # Combine surrogates
                                    codepoint = 0x10000 + ((code_point & 0x3FF) << 10) + (low_code_point & 0x3FF)
                                    value_chars.append(chr(codepoint))
                                    i += 5 # Skip \uXXXX and the next \uXXXX start
                                    continue # Skip standard advancement below
                                else: # Standard BMP char
                                    value_chars.append(chr(code_point))
                                    i += 5
                                    continue

                            except ValueError:
                                raise error("Invalid hex digits in unicode escape", i + 1, line, column)
                    else:
                        # Unknown escape sequence
                        raise error(f"Unknown escape sequence: \\{escape_char}", i, line, column)
                    i += 1 # Consume the escape char if it wasn't \u
                else:
                    # Regular character inside string
                    value_chars.append(char)
                    i += 1

                # Update line/column tracking only if the character wasn't consumed by a complex escape handler
                if char != '\\':
                    if char == '\n':
                        line += 1
                        column = 1
                    elif char == '\r':
                        column += 1
                    else:
                        column += 1

            if i >= n and text[i-1] != '\\': # Check if we hit EOF without closing quote
                 raise error("Unterminated string: expected closing '\"'", start_i, start_line, start_col)

            tokens.append(Token('STRING', "".join(value_chars), start_line, start_col))
            continue

        # --- Number Token ---
        if char in '-0123456789':
            start_line = line
            start_col = column
            j = i

            # Consume run of allowed characters
            while j < n and text[j] in '0123456789+-eE.':
                j += 1

            num_str = text[i:j]

            # Basic validation of JSON number structure
            if not num_str:
                # Should not happen if starting char was valid
                i += 1
                continue

            is_float = False
            try:
                if '.' in num_str:
                    is_float = True
                if 'e' in num_str.lower():
                    is_float = True

                # Strict JSON number validation (simplified check based on required properties)
                # We must ensure it matches the structure: optional '-', then (digit or 0 followed by digit*), then optional ('.' digit*), then optional (e/E sign digit*)

                # A more robust check: try conversion. Python's float() handles many cases, but we must catch malformed ones that look like numbers but aren't.
                # For instance, "1.2.3" will raise ValueError in float(), but we need to ensure we capture the whole invalid run.

                if is_float:
                    value = float(num_str)
                else:
                    # Must be an integer
                    if num_str.lstrip('-').isdigit():
                        value = int(num_str)
                    else:
                        # Catch cases like just "-" or "1-2" if the initial loop allowed it
                        raise ValueError("Invalid number format")

            except ValueError:
                raise error("Invalid number format", start_i, start_line, start_col)

            # Handle -0 case specifically if parsing resulted in float 0.0
            if value == 0.0 and num_str.lstrip('-') == '0':
                value = 0 # Ensure -0 becomes 0 int if possible, although JSON typically treats it as 0.0 float. Sticking to standard parsing behavior here.

            tokens.append(Token('NUMBER', value, start_line, start_col))
            i = j
            continue

        # --- Literals (true, false, null) ---
        if char.isalpha():
            start_line = line
            start_col = column
            j = i
            while j < n and text[j].isalpha():
                j += 1

            literal_str = text[i:j]
            if literal_str == 'true':
                tokens.append(Token('TRUE', True, start_line, start_col))
            elif literal_str == 'false':
                tokens.append(Token('FALSE', False, start_line, start_col))
            elif literal_str == 'null':
                tokens.append(Token('NULL', None, start_line, start_col))
            else:
                # Invalid literal (e.g., trueX)
                raise error("Invalid literal", start_i, start_line, start_col)

            i = j
            continue

        # --- Unexpected Character ---
        raise error(f"Unexpected character: {char}", i, line, column)

    # EOF token
    tokens.append(Token('EOF', None, line, column))
    return tokens

