from typing import Any, List
from .scanner import Token, JSONError

class ParserError(JSONError):
    pass

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token:
        if self.pos >= len(self.tokens):
            # This should be caught by the EOF token if the input was complete
            return Token('EOF', None, -1, -1)
        return self.tokens[self.pos]

    def advance(self):
        self.pos += 1

    def eat(self, expected_kind: str, expected_value=None):
        token = self.current_token()
        if token.kind != expected_kind:
            raise ParserError(
                f"Expected {expected_kind} but found {token.kind}", 
                token.line, token.column
            )
        if expected_value is not None and token.value != expected_value:
             raise ParserError(
                f"Expected value {expected_value} but found {token.value}", 
                token.line, token.column
            )
        self.advance()

    def parse(self) -> Any:
        """Starts the parsing process."""
        value = self._parse_value()

        # Check for extraneous tokens after the main value
        current = self.current_token()
        if current.kind != 'EOF':
            raise ParserError(
                f"Unexpected token '{current.kind}' after JSON value", 
                current.line, current.column
            )
        return value

    def _skip_whitespace(self):
        # Whitespace is implicitly handled by tokenization, but we skip explicit tokens that might be whitespace 
        # if we were tokenizing differently. Since our scanner ignores it, we just check the next token type.
        pass

    def _parse_value(self) -> Any:
        token = self.current_token()

        if token.kind == 'NUMBER':
            self.advance()
            return token.value
        elif token.kind == 'STRING':
            self.advance()
            return token.value
        elif token.kind == 'TRUE':
            self.advance()
            return True
        elif token.kind == 'FALSE':
            self.advance()
            return False
        elif token.kind == 'NULL':
            self.advance()
            return None
        elif token.kind == 'LBRACE':
            return self._parse_object()
        elif token.kind == 'LBRACKET':
            return self._parse_array()
        else:
            raise ParserError(
                f"Unexpected token when expecting a value: {token.kind}",
                token.line, token.column
            )

    def _parse_object(self) -> dict:
        self.eat('LBRACE')
        obj = {}

        # Check for empty object {}
        if self.current_token().kind == 'RBRACE':
            self.advance()
            return {}

        while True:
            # 1. Key must be a string
            key_token = self.current_token()
            if key_token.kind != 'STRING':
                raise ParserError(
                    "Expected string key in object", 
                    key_token.line, key_token.column
                )
            key = key_token.value
            self.advance() # Consume key

            # 2. Must be a colon
            self.eat('COLON')

            # 3. Value
            value = self._parse_value()

            # Store value (last key wins)
            obj[key] = value

            # 4. Check for comma or closing brace
            token = self.current_token()
            if token.kind == 'COMMA':
                self.advance() # Consume comma, loop for next pair
            elif token.kind == 'RBRACE':
                self.advance() # Consume RBRACE, exit loop
                break
            else:
                raise ParserError(
                    f"Expected comma or closing brace, found {token.kind}",
                    token.line, token.column
                )

        return obj

    def _parse_array(self) -> list:
        self.eat('LBRACKET')
        arr = []

        # Check for empty array []
        if self.current_token().kind == 'RBRACKET':
            self.advance()
            return []

        while True:
            # 1. Value
            value = self._parse_value()
            arr.append(value)

            # 2. Check for comma or closing bracket
            token = self.current_token()
            if token.kind == 'COMMA':
                self.advance() # Consume comma, loop for next value
            elif token.kind == 'RBRACKET':
                self.advance() # Consume RBRACKET, exit loop
                break
            else:
                raise ParserError(
                    f"Expected comma or closing bracket, found {token.kind}",
                    token.line, token.column
                )

        return arr


def loads(text: str) -> Any:
    """
    Parses a JSON string into a Python object.
    """
    from .scanner import tokenize

    tokens = tokenize(text)
    parser = Parser(tokens)
    try:
        return parser.parse()
    except JSONError as e:
        # Re-raise scanner errors directly
        raise e
    except ParserError as e:
        # Re-raise parser errors
        raise e

