from typing import Any, Dict, List, Optional, Union

# Helper for cycle detection
_SENTINEL = object()

def _dump_recursive(
    obj: Any, 
    indent: Optional[int], 
    sort_keys: bool, 
    ensure_ascii: bool, 
    seen_objects: Dict[int, Any]
) -> str:
    """Recursive helper for serialization."""

    # 1. Handle basic types
    if obj is None:
        return "null"
    if isinstance(obj, bool):
        return "true" if obj else "false"
    if isinstance(obj, int):
        return str(obj)
    if isinstance(obj, float):
        if obj != obj: # NaN check
            raise ValueError("Cannot serialize NaN")
        if obj == float('inf') or obj == float('-inf'):
            raise ValueError("Cannot serialize infinity")
        # Use repr(f) which provides standard float formatting (e.g., 1e+308)
        return repr(obj)
    if isinstance(obj, str):
        return _dump_string(obj, ensure_ascii)

    # 2. Handle containers
    if isinstance(obj, list):
        return _dump_list(obj, indent, sort_keys, ensure_ascii, seen_objects)

    if isinstance(obj, tuple):
        # Requirement: tuples come back as lists in the Python structure, but when serializing, 
        # they are treated as arrays.
        return _dump_list(list(obj), indent, sort_keys, ensure_ascii, seen_objects)

    if isinstance(obj, dict):
        if id(obj) in seen_objects:
            raise ValueError("Object contains self-reference (cycle detected)")
        seen_objects[id(obj)] = _SENTINEL
        try:
            return _dump_object(obj, indent, sort_keys, ensure_ascii, seen_objects)
        finally:
            del seen_objects[id(obj)]

    # Fail on unexpected types
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def _dump_string(s: str, ensure_ascii: bool) -> str:
    """Handles string escaping."""
    parts = []
    i = 0
    n = len(s)
    while i < n:
        char = s[i]

        # Escaping rules
        if char == '"':
            parts.append('\\"')
        elif char == '\\':
            parts.append('\\\\')
        elif char == '\b':
            parts.append('\\b')
        elif char == '\f':
            parts.append('\\f')
        elif char == '\n':
            parts.append('\\n')
        elif char == '\r':
            parts.append('\\r')
        elif char == '\t':
            parts.append('\\t')
        elif char < 0x20:
            # Control characters U+0000 to U+001F
            if ensure_ascii:
                parts.append(f'\\u{char:04x}')
            else:
                # Write raw character if not ensuring ASCII, but still escaped if required by JSON standard (though usually raw is okay if < U+0020)
                # Sticking to \u00xx for all < U+0020 for consistency if we want to avoid control chars in output, 
                # but the requirement states: "every other character below U+0020 becomes \u00xx"
                parts.append(f'\\u{char:04x}')
        elif ensure_ascii and char > 0x7F:
            # High ASCII characters
            if char <= 0xFFFF:
                parts.append(f'\\u{char:04x}')
            else:
                # Surrogate pair required for characters > U+FFFF
                high = 0xD800 + ((char - 0x10000) // 0x400)
                low = 0xDC00 + ((char - 0x10000) % 0x400)
                parts.append(f'\\u{high:04x}')
                parts.append(f'\\u{low:04x}')
        elif char > 0xFFFF:
            # Non-ASCII, not enforcing ASCII: write as is (UTF-8/Unicode characters)
            parts.append(char)
        else:
            # Standard printable characters U+0020 to U+FFFF (and ASCII > 0x7F if ensure_ascii=False)
            parts.append(char)

        i += 1

    return '"' + "".join(parts) + '"'

def _dump_list(
    data: List[Any], 
    indent: Optional[int], 
    sort_keys: bool, 
    ensure_ascii: bool, 
    seen_objects: Dict[int, Any]
) -> str:

    if not data:
        return "[]"

    item_strings = [_dump_recursive(item, indent, sort_keys, ensure_ascii, seen_objects) for item in data]

    if indent is None:
        return "[" + ",".join(item_strings) + "]"

    # Indented formatting
    indent_str = " " * indent
    next_indent_str = " " * (indent + 2)

    items_lines = []
    for item_str in item_strings:
        # If the item itself is complex (starts with { or [), it might already contain newlines, 
        # so we need to handle indentation carefully.

        if item_str.startswith('{') or item_str.startswith('['):
            # If complex, dump it separately to handle its internal structure correctly
            # This requires re-running the recursion for formatting, which is complex.
            # For simplicity following the example, we assume the recursive call handles its internal formatting if indent > 0.
            # If the recursive call returns a compact string (e.g., {}), we wrap it.

            # A simple approach for indentation: if the item string contains no newlines, it's compact.
            if '\n' not in item_str:
                 items_lines.append(f"{next_indent_str}{item_str},")
            else:
                 # If the item was already formatted with indentation, we just prepend the correct line indentation
                 items_lines.append(f"{next_indent_str}{item_str},")
        else:
            # Simple value on one line
            items_lines.append(f"{next_indent_str}{item_str},")

    # Remove trailing comma from the last item
    if items_lines:
        items_lines[-1] = items_lines[-1].rstrip(',')

    body = "\n".join(items_lines)
    return f"[\n{body}\n{indent_str}]"


def _dump_object(
    data: Dict[str, Any], 
    indent: Optional[int], 
    sort_keys: bool, 
    ensure_ascii: bool, 
    seen_objects: Dict[int, Any]
) -> str:

    if not data:
        return "{}"

    # Sort keys if required
    keys = sorted(data.keys()) if sort_keys else data.keys()

    items_lines = []

    for key in keys:
        value = data[key]

        # Key must be string, checked by caller context in a full implementation, but we trust dict keys here.
        if not isinstance(key, str):
             raise TypeError("Dictionary keys must be strings.")

        key_str = _dump_string(key, ensure_ascii)

        # Recursively dump the value
        value_str = _dump_recursive(value, indent, sort_keys, ensure_ascii, seen_objects)

        if indent is None:
            items_lines.append(f"{key_str}:{value_str}")
        else:
            indent_str = " " * indent
            next_indent_str = " " * (indent + 2)

            # Format: "key": value
            items_lines.append(f"{next_indent_str}{key_str}: {value_str},")

    if indent is None:
        return "{" + ",".join(items_lines) + "}"

    # Indented formatting
    body = "\n".join(items_lines)
    return f"{\n{body}\n{indent_str}}}"


def dumps(obj: Any, *, indent: Optional[int] = None, sort_keys: bool = False, ensure_ascii: bool = True) -> str:
    """
    Serializes a Python object into a JSON string.
    """
    if indent is not None and indent < 0:
        raise ValueError("Indentation level must be non-negative.")

    # Cycle detection map: {object_id: sentinel}
    seen_objects = {}

    try:
        return _dump_recursive(obj, indent, sort_keys, ensure_ascii, seen_objects)
    except TypeError as e:
        raise e
    except ValueError as e:
        # Catch NaN/Inf errors from float conversion
        raise e

