```python
from typing import Any, List, Dict
from .scanner import Token, JSONError

class ParserError(JSONError):
    pass

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token], 
                 duplicate_keys: str = 'last', 
                 max_depth: Optional[int] = None):
        self.tokens = tokens
        self.pos = 0
        self.duplicate_keys = duplicate_keys
        self.max_depth = max_depth
        self.current_depth = 0

    def current_token(self) -> Token:
        if self.pos >= len(self.tokens):
            return Token('EOF', None, -1, -1)
        return self.tokens[self.pos]

    def advance(self):
        self.pos += 1

    def eat(self, expected_kind: str, expected_value=None):
        token = self.current_token()
        if token.kind != expected_kind:
            raise ParserError(
                f"Expected {expected_kind} but found {token.kind}", 
                token.line, token.column
            )
        if expected_value is not None and token.value != expected_value:
             raise ParserError(
                f"Expected value {expected_value} but found {token.value}", 
                token.line, token.column
            )
        self.advance()

    def parse(self) -> Any:
        """Starts the parsing process."""

        # Check depth limit for the whole document (top level container starts at depth 1 if it's a container)
        if self.max_depth is not None and self.max_depth < 1 and self.tokens and self.tokens[0].kind in ('LBRACKET', 'LBRACE'):
             raise ParserError("Max depth limit must be at least 1 if the document is a container", 
                               self.tokens[0].line, self.tokens[0].column)


        value = self._parse_value()

        # Check for extraneous tokens after the main value
        current = self.current_token()
        if current.kind != 'EOF':
            raise ParserError(
                f"Unexpected token '{current.kind}' after JSON value", 
                current.line, current.column
            )
        return value

    def _parse_value(self) -> Any:
        token = self.current_token()

        if token.kind == 'NUMBER':
            self.advance()
            return token.value
        elif token.kind == 'STRING':
            self.advance()
            return token.value
        elif token.kind == 'TRUE':
            self.advance()
            return True
        elif token.kind == 'FALSE':
            self.advance()
            return False
        elif token.kind == 'NULL':
            self.advance()
            return None
        elif token.kind == 'LBRACE':
            self.current_depth += 1
            obj = self._parse_object()
            self.current_depth -= 1
            return obj
        elif token.kind == 'LBRACKET':
            self.current_depth += 1
            arr = self._parse_array()
            self.current_depth -= 1
            return arr
        else:
            raise ParserError(
                f"Unexpected token when expecting a value: {token.kind}",
                token.line, token.column
            )

    def _parse_object(self) -> dict:
        self.eat('LBRACE')
        obj: Dict[str, Any] = {}

        # Check for empty object {}
        if self.current_token().kind == 'RBRACE':
            self.advance()
            return {}

        while True:
            # 1. Key must be a string
            key_token = self.current_token()
            if key_token.kind != 'STRING':
                raise ParserError(
                    "Expected string key in object", 
                    key_token.line, key_token.column
                )

            key = key_token.value
            self.advance() # Consume key

            # Check for duplicate keys immediately
            if key in obj:
                if self.duplicate_keys == 'first':
                    # Ignore subsequent keys, but continue parsing structure
                    pass 
                elif self.duplicate_keys == 'error':
                    raise ParserError(
                        f"Duplicate key found: '{key}'", 
                        key_token.line, key_token.column
                    )
                elif self.duplicate_keys == 'last':
                    # Overwrite, which happens naturally later, but we ensure the key is present.
                    pass
            else:
                 # If this is the first time seeing the key, we store it for later reference/overwriting
                 obj[key] = None # Placeholder to mark presence

            # 2. Must be a colon
            self.eat('COLON')

            # 3. Value
            value = self._parse_value()

            # Store value (last key wins, handles both 'last' and overwrites if 'first' was used and we are now overwriting)
            if self.duplicate_keys == 'first':
                # If 'first', we only write if the key hasn't been set yet (i.e., the placeholder is still None)
                if obj.get(key) is None and key not in obj:
                     # This logic is complex: if we are 'first', we only set it if it's the first encounter.
                     # Since we overwrite the placeholder, we check if the actual key is new.
                     if key not in obj:
                         obj[key] = value
                     # If key *is* in obj, it means we already processed it first, so we skip the assignment.
                     pass
                elif key not in obj:
                    obj[key] = value
            elif self.duplicate_keys == 'last':
                obj[key] = value
            elif self.duplicate_keys == 'error':
                # If 'error', we already raised or skipped in step 1, so we assign it here if we reached this point (which shouldn't happen if logic is sound, but safety)
                obj[key] = value


            # 4. Check for comma or closing brace
            token = self.current_token()
            if token.kind == 'COMMA':
                self.advance() # Consume comma, loop for next pair
            elif token.kind == 'RBRACE':
                self.advance() # Consume RBRACE, exit loop
                break
            else:
                raise ParserError(
                    f"Expected comma or closing brace, found {token.kind}",
                    token.line, token.column
                )

        return obj

    def _parse_array(self) -> list:
        self.eat('LBRACKET')
        arr: List[Any] = []

        # Check for empty array []
        if self.current_token().kind == 'RBRACKET':
            self.advance()
            return []

        while True:
            # Check depth limit before parsing the next element
            if self.max_depth is not None and self.current_depth + 1 > self.max_depth:
                # Error points at the opening bracket that would cause the overflow, 
                # which is the current LBRACKET token if we were to process it.
                # Since we already ate the LBRACKET, we point at the comma/value start.
                raise ParserError(
                    f"Nesting depth limit ({self.max_depth}) exceeded", 
                    self.current_token().line, self.current_token().column
                )

            # 1. Value
            value = self._parse_value()
            arr.append(value)

            # 2. Check for comma or closing bracket
            token = self.current_token()
            if token.kind == 'COMMA':
                self.advance() # Consume comma, loop for next value
            elif token.kind == 'RBRACKET':
                self.advance() # Consume RBRACKET, exit loop
                break
            else:
                raise ParserError(
                    f"Expected comma or closing bracket, found {token.kind}",
                    token.line, token.column
                )

        return arr


def loads(text: str, *, duplicate_keys: str = 'last', max_depth: Optional[int] = None, allow_nan: bool = False) -> Any:
    """
    Parses a JSON string into a Python object.
    """
    from .scanner import tokenize

    if duplicate_keys not in ('last', 'first', 'error'):
        raise ValueError(f"Invalid duplicate_keys setting: {duplicate_keys}")
    if max_depth is not None and (not isinstance(max_depth, int) or max_depth < 1):
        raise ValueError("max_depth must be None or an integer >= 1")

    tokens = tokenize(text, allow_nan=allow_nan)
    parser = Parser(tokens, duplicate_keys=duplicate_keys, max_depth=max_depth)

    try:
        return parser.parse()
    except JSONError as e:
        raise e
    except ParserError as e:
        raise e

__all__ = ['loads', 'ParserError']
