The dumper now handles `allow_nan` for serialization and correctly handles cycles.

```python
from typing import Any, Dict, List, Optional, Union
import math

# Helper for cycle detection
_SENTINEL = object()

def _dump_recursive(
    obj: Any, 
    indent: Optional[int], 
    sort_keys: bool, 
    ensure_ascii: bool, 
    allow_nan: bool,
    seen_objects: Dict[int, Any]
) -> str:
    """Recursive helper for serialization."""

    # 1. Handle basic types
    if obj is None:
        return "null"
    if isinstance(obj, bool):
        return "true" if obj else "false"
    if isinstance(obj, int):
        return str(obj)
    if isinstance(obj, float):
        if math.isnan(obj):
            if allow_nan:
                return "NaN"
            else:
                raise ValueError("Cannot serialize NaN")
        if math.isinf(obj):
            if allow_nan:
                return "Infinity" if obj > 0 else "-Infinity"
            else:
                raise ValueError("Cannot serialize infinity")

        # Finite float
        return repr(obj)
    if isinstance(obj, str):
        return _dump_string(obj, ensure_ascii)

    # 2. Handle containers
    if isinstance(obj, list):
        return _dump_list(obj, indent, sort_keys, ensure_ascii, allow_nan, seen_objects)

    if isinstance(obj, tuple):
        # Tuples serialize as lists
        return _dump_list(list(obj), indent, sort_keys, ensure_ascii, allow_nan, seen_objects)

    if isinstance(obj, dict):
        if id(obj) in seen_objects:
            raise ValueError("Object contains self-reference (cycle detected)")
        seen_objects[id(obj)] = _SENTINEL
        try:
            return _dump_object(obj, indent, sort_keys, ensure_ascii, allow_nan, seen_objects)
        finally:
            del seen_objects[id(obj)]

    # Fail on unexpected types
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def _dump_string(s: str, ensure_ascii: bool) -> str:
    """Handles string escaping."""
    parts = []
    i = 0
    n = len(s)
    while i < n:
        char = s[i]

        if char == '"':
            parts.append('\\"')
        elif char == '\\':
            parts.append('\\\\')
        elif char == '\b':
            parts.append('\\b')
        elif char == '\f':
            parts.append('\\f')
        elif char == '\n':
            parts.append('\\n')
        elif char == '\r':
            parts.append('\\r')
        elif char == '\t':
            parts.append('\\t')
        elif char < 0x20:
            # Control characters U+0000 to U+001F
            parts.append(f'\\u{char:04x}')
        elif ensure_ascii and char > 0x7F:
            # High ASCII characters
            if char <= 0xFFFF:
                parts.append(f'\\u{char:04x}')
            else:
                # Surrogate pair required for characters > U+FFFF
                high = 0xD800 + ((char - 0x10000) // 0x400)
                low = 0xDC00 + ((char - 0x10000) % 0x400)
                parts.append(f'\\u{high:04x}')
                parts.append(f'\\u{low:04x}')
        elif char > 0xFFFF:
            # Non-ASCII, not enforcing ASCII: write as is
            parts.append(char)
        else:
            # Standard printable characters
            parts.append(char)

        i += 1

    return '"' + "".join(parts) + '"'

def _dump_list(
    data: List[Any], 
    indent: Optional[int], 
    sort_keys: bool, 
    ensure_ascii: bool, 
    allow_nan: bool,
    seen_objects: Dict[int, Any]
) -> str:

    if not data:
        return "[]"

    item_strings = [_dump_recursive(item, indent, sort_keys, ensure_ascii, allow_nan, seen_objects) for item in data]

    if indent is None:
        return "[" + ",".join(item_strings) + "]"

    # Indented formatting
    indent_str = " " * indent
    next_indent_str = " " * (indent + 2)

    items_lines = []
    for item_str in item_strings:
        # We append the comma *after* the item's structure, ensuring trailing commas are avoided in the list structure itself
        items_lines.append(f"{next_indent_str}{item_str},")

    # Remove trailing comma from the last item
    body = "\n".join(items_lines).rstrip(',\n')

    return f"[\n{body}\n{indent_str}]"


def _dump_object(
    data: Dict[str, Any], 
    indent: Optional[int], 
    sort_keys: bool, 
    ensure_ascii: bool, 
    allow_nan: bool,
    seen_objects: Dict[int, Any]
) -> str:

    if not data:
        return "{}"

    keys = sorted(data.keys()) if sort_keys else data.keys()

    items_lines = []

    for key in keys:
        value = data[key]

        key_str = _dump_string(key, ensure_ascii)

        value_str = _dump_recursive(value, indent, sort_keys, ensure_ascii, allow_nan, seen_objects)

        if indent is None:
            items_lines.append(f"{key_str}:{value_str}")
        else:
            indent_str = " " * indent
            next_indent_str = " " * (indent + 2)

            # Format: "key": value
            items_lines.append(f"{next_indent_str}{key_str}: {value_str},")

    if indent is None:
        return "{" + ",".join(items_lines) + "}"

    body = "\n".join(items_lines).rstrip(',\n')
    return f"{\n{body}\n{indent_str}}}"


def dumps(obj: Any, *, indent: Optional[int] = None, sort_keys: bool = False, ensure_ascii: bool = True, allow_nan: bool = False) -> str:
    """
    Serializes a Python object into a JSON string.
    """
    if indent is not None and indent < 0:
        raise ValueError("Indentation level must be non-negative.")

    seen_objects = {}

    try:
        return _dump_recursive(obj, indent, sort_keys, ensure_ascii, allow_nan, seen_objects)
    except TypeError as e:
        raise e
    except ValueError as e:
        # Catch NaN/Inf errors from float conversion
        raise e

