import re
from typing import Tuple

class Version:
    """Represents a package version MAJOR.MINOR.PATCH."""
    _VERSION_REGEX = re.compile(r"^(\d+)\.(\d+)\.(\d+)$")

    def __init__(self, text: str):
        match = self._VERSION_REGEX.match(text)
        if not match:
            raise ValueError(f"Invalid version format: {text}. Must be MAJOR.MINOR.PATCH.")

        major_s, minor_s, patch_s = match.groups()

        # Check for leading zeros, unless the number is '0' itself
        if len(major_s) > 1 and major_s.startswith('0'):
            raise ValueError(f"Invalid version: {text}. Major part '{major_s}' has a leading zero.")
        if len(minor_s) > 1 and minor_s.startswith('0'):
            raise ValueError(f"Invalid version: {text}. Minor part '{minor_s}' has a leading zero.")
        if len(patch_s) > 1 and patch_s.startswith('0'):
            raise ValueError(f"Invalid version: {text}. Patch part '{patch_s}' has a leading zero.")

        self.major = int(major_s)
        self.minor = int(minor_s)
        self.patch = int(patch_s)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return self.major == other.major and self.minor == other.minor and self.patch == other.patch

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self < other or self == other

    def __gt__(self, other):
        return self > other

    def __ge__(self, other):
        return self > other or self == other

    def __repr__(self):
        return f"Version('{self.major}.{self.minor}.{self.patch}')"

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def to_tuple(self) -> Tuple[int, int, int]:
        return (self.major, self.minor, self.patch)

class Range:
    """Represents a package version constraint range."""

    OPERATORS = {
        '==': lambda v: v == self,
        '!=': lambda v: v != self,
        '>': lambda v: v > self,
        '>=': lambda v: v >= self,
        '<': lambda v: v < self,
        '<=': lambda v: v <= self,
    }

    def __init__(self, spec: str):
        self.constraints: list[Tuple[str, Version]] = []
        self._parse_spec(spec.strip())

    def _parse_spec(self, spec: str):
        if not spec:
            raise ValueError("Range specification cannot be empty.")

        # Split by comma, preserving structure for each constraint
        parts = [p.strip() for p in spec.split(',')]

        for part in parts:
            if not part:
                raise ValueError("Empty constraint found in range spec.")

            part = part.strip()

            # Handle wildcards first
            if part == '*':
                self.constraints.append(('*', None)) # Placeholder for '*'
                continue

            # Handle caret (^) and tilde (~) ranges
            if part.startswith('^'):
                self._parse_caret(part[1:], part)
                continue
            if part.startswith('~'):
                self._parse_tilde(part[1:], part)
                continue

            # Handle explicit operators or exact version
            match = re.match(r"^(==|!=|>=|<=|>|<)?\s*([\d.]+)", part)
            if not match:
                raise ValueError(f"Invalid constraint format: {part}")

            op_str = match.group(1)
            version_str = match.group(2)

            try:
                version = Version(version_str)
            except ValueError:
                raise ValueError(f"Invalid version in constraint: {version_str}")

            if op_str is None:
                # Must be an exact version if no operator is present
                op_str = '=='

            if op_str not in self.OPERATORS:
                 raise ValueError(f"Unknown operator in constraint: {op_str}")

            self.constraints.append((op_str, version))


    def _parse_caret(self, version_str: str, full_spec: str):
        """Handles ^X.Y.Z syntax."""
        try:
            base_v = Version(version_str)
        except ValueError:
            raise ValueError(f"Invalid version in caret spec: {version_str}")

        major, minor, patch = base_v.to_tuple()

        if major > 0:
            # ^1.2.3 => >=1.2.3, <2.0.0
            lower_bound = base_v
            upper_bound = Version(f"{major + 1}.0.0")
        elif minor > 0:
            # ^0.2.3 => >=0.2.3, <0.3.0
            lower_bound = base_v
            upper_bound = Version(f"0.{minor + 1}.0")
        else: # major=0, minor=0
            # ^0.0.3 => >=0.0.3, <0.0.4
            lower_bound = base_v
            upper_bound = Version(f"0.0.{patch + 1}")

        # Add >= lower_bound
        self.constraints.append(('>=', lower_bound))
        # Add < upper_bound
        self.constraints.append(('<', upper_bound))

    def _parse_tilde(self, version_str: str, full_spec: str):
        """Handles ~X.Y.Z syntax."""
        try:
            base_v = Version(version_str)
        except ValueError:
            raise ValueError(f"Invalid version in tilde spec: {version_str}")

        major, minor, patch = base_v.to_tuple()

        if patch == 0:
            # ~1.2.0 => >=1.2.0, <1.3.0 (increment patch)
            lower_bound = base_v
            upper_bound = Version(f"{major}.{minor + 1}.0")
        else:
            # ~1.2.3 => >=1.2.3, <1.3.0 (increment patch)
            lower_bound = base_v
            upper_bound = Version(f"{major}.{minor}.{patch + 1}")

        # Add >= lower_bound
        self.constraints.append(('>=', lower_bound))
        # Add < upper_bound
        self.constraints.append(('<', upper_bound))

    def contains(self, version: Version) -> bool:
        """Checks if the version satisfies all constraints."""

        for op, constraint_v in self.constraints:
            if op == '*':
                continue

            # For explicit constraints, check if the version satisfies the operator
            if op in self.OPERATORS:
                if not self.OPERATORS[op](version):
                    return False
            # If the constraint was derived from caret/tilde, it must be in self.OPERATORS
            elif op == '>=' and not (version >= constraint_v):
                return False
            elif op == '<' and not (version < constraint_v):
                return False
            elif op == '==' and not (version == constraint_v):
                return False
            elif op == '!=' and not (version != constraint_v):
                return False

        return True

    def __in__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        # Reconstruct the spec string, removing internal whitespace

        # A simplified reconstruction is tricky due to internal structure (^) vs (>=).
        # For compliance with the requirement "str(r) is the spec with all whitespace removed", 
        # we will reconstruct based on the original input structure if possible, 
        # but since we are parsing and canonicalizing, we rely on a standard representation.

        # Let's return a human-readable canonical string representation based on constraints.
        parts = []
        for op, v in self.constraints:
            if op == '*':
                parts.append('*')
            elif op in ('>=', '<=', '>', '<', '==', '!='):
                parts.append(f"{op}{v}")
            # Caret/Tilde specs are implicitly represented by two constraints, 
            # so we cannot easily reconstruct the single operator unless we track it.

        # For simplicity, if we parsed complex ranges, we rely on the original input 
        # format being somewhat preserved or use a generic representation.
        # Since the problem implies parsing *from* a string *to* a Range object, 
        # and then converting *back* to that string, we assume the original format 
        # or a strict canonical form is expected.

        # Given the complexity of perfectly reverse-engineering ^ and ~, we will 
        # represent the canonical form of the constraints found.

        # If the original spec had complex forms, this output might be verbose.
        if not self.constraints:
            return ""

        # A basic approach: stringify the constraints found.
        # This might not perfectly match the input if the input was complex, 
        # but it's the best approximation from the canonicalized constraints list.
        constraint_strs = []
        for op, v in self.constraints:
            if op == '*':
                constraint_strs.append('*')
            elif op in self.OPERATORS:
                constraint_strs.append(f"{op}{v}")
            else:
                # This catches >=, < from derived ranges
                constraint_strs.append(f"{op}{v}")

        return ",".join(constraint_strs)

