# resolve/index.py
from typing import Dict, List, Optional
from .versions import Version, Range

class PackageIndex:
    """Stores known package releases and their dependencies."""
    def __init__(self):
        # {name: {version_string: {'requires': {dep_name: Range}}}}
        self._releases: Dict[str, Dict[str, dict]] = {}

    def add(self, name: str, version_str: str, requires: Optional[Dict[str, str]] = None):
        """Adds a new release version to the index."""
        try:
            version = Version(version_str)
        except ValueError as e:
            raise ValueError(f"Bad version provided for {name}: {e}")

        if name not in self._releases:
            self._releases[name] = {}

        if version_str in self._releases[name]:
            raise ValueError(f"Version {version_str} already exists for package {name}.")

        req_map = {}
        if requires:
            for dep_name, spec_str in requires.items():
                try:
                    # We must parse the spec string to store the Range object internally
                    req_map[dep_name] = Range(spec_str)
                except ValueError as e:
                    raise ValueError(f"Bad dependency range specification for {name}@{version_str} on {dep_name}: {e}")

        self._releases[name][version_str] = {'requires': req_map}

    def versions(self, name: str) -> List[Version]:
        """Returns known versions for a package, newest first."""
        if name not in self._releases:
            return []

        version_list = []
        for v_str in self._releases[name].keys():
            version_list.append(Version(v_str))

        # Sort descending (newest first)
        version_list.sort(reverse=True)
        return version_list

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        """Returns the dependency requirements for a specific released version."""
        if name not in self._releases:
            raise KeyError(f"Package {name} not found.")

        release_data = self._releases[name].get(str(version))

        if not release_data:
            raise KeyError(f"Version {version} not found for package {name}.")

        return release_data['requires']

    @classmethod
    def from_dict(cls, data: Dict) -> 'PackageIndex':
        """Builds an index from a nested dictionary structure."""
        index = cls()
        for name, versions_data in data.items():
            for v_str, deps in versions_data.items():
                # deps is expected to be {dep_name: spec_str}
                index.add(name, v_str, requires=deps)
        return index

