# resolve/solver.py
from typing import Dict, List, Tuple, Optional
from .index import PackageIndex
from .versions import Version, Range

class ResolutionError(Exception):
    """Raised when package resolution fails."""
    def __init__(self, package: str, explanation: str):
        super().__init__(explanation)
        self.package = package
        self.explanation = explanation

    def __str__(self):
        return self.explanation

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
    """
    Resolves the dependency graph based on root requirements.
    """

    # 1. Initialization

    # Order: List of package names to process, sorted alphabetically initially.
    initial_order = sorted(requirements.keys())

    # State:
    # selected: {name: Version} - Packages chosen so far
    # order: List[str] - The ordered list of packages whose constraints are being evaluated

    selected: Dict[str, Version] = {}
    order: List[str] = []

    # Initialize order with root requirements
    for name in initial_order:
        order.append(name)

    # --- Helper function to check constraints ---
    def get_constraints(pkg_name: str, current_order: List[str], current_selection: Dict[str, Version]) -> List[Tuple[str, Range]]:
        """Gathers all constraints on pkg_name in order of appearance."""
        constraints: List[Tuple[str, Range]] = []

        # 1. Root requirement constraint
        root_spec = requirements.get(pkg_name)
        if root_spec:
            try:
                root_range = Range(root_spec)
                constraints.append(("<root>", root_range))
            except ValueError:
                # Should be caught before calling resolve, but defensive check
                pass 

        # 2. Requirements from already selected packages
        for requirer_name in current_order:
            if requirer_name == pkg_name:
                continue # Skip self-reference if it's the current node being evaluated

            if requirer_name in current_selection:
                requirer_version = current_selection[requirer_name]

                # Check if this package was required by the requirer
                if pkg_name in index._releases[requirer_name]: # Heuristic check if dependency exists
                    try:
                        req_ranges = index.requirements(requirer_name, requirer_version)
                        if pkg_name in req_ranges:
                            req_range = req_ranges[pkg_name]

                            # Format: "requirer_name version"
                            requirer_identifier = f"{requirer_name} {requirer_version}"
                            constraints.append((requirer_identifier, req_range))
                    except KeyError:
                        # Should not happen if index is consistent, but handle defensively
                        pass 
        return constraints

    # --- Recursive Backtracking Solver ---

    # We use an explicit stack/queue structure to manage the state transition for DFS
    # State: (current_order, current_selection)
    # The search implicitly follows the 'order' list.

    def backtrack(current_order: List[str], current_selection: Dict[str, Version]) -> Optional[Dict[str, Version]]:

        # 1. Find the next package to resolve (first in order that is not yet selected)
        pkg_to_resolve = None
        for name in current_order:
            if name not in current_selection:
                pkg_to_resolve = name
                break

        # Success condition: All packages in the order have been selected
        if pkg_to_resolve is None:
            return current_selection.copy()

        # 2. Determine constraints for this package
        constraints = get_constraints(pkg_to_resolve, current_order, current_selection)

        # 3. Get candidates (newest first)
        candidates = index.versions(pkg_to_resolve)

        # 4. Iterate through candidates
        for candidate_version in candidates:

            # Check if the candidate satisfies all static constraints (constraints from selected packages/root)
            is_acceptable = True

            # Check 4a: Static Constraint Check
            for requirer_id, req_range in constraints:
                if not req_range.contains(candidate_version):
                    is_acceptable = False
                    break

            if not is_acceptable:
                # Candidate fails static constraints. We must record this for the error message.
                # We cannot break here; we need to continue to check other candidates
                # to find a successful path, but we must note that *this* candidate fails.
                # The error reporting logic requires us to know the *first* failure point.
                # We defer recording the error until we exhaust candidates.
                continue


            # Check 4b: Dynamic Dependency Check (Candidate's dependencies vs already selected)
            requires_map = index.requirements(pkg_to_resolve, candidate_version)

            for dep_name, dep_range in requires_map.items():
                if dep_name in current_selection:
                    selected_version = current_selection[dep_name]
                    if not dep_range.contains(selected_version):
                        is_acceptable = False
                        break

            if not is_acceptable:
                continue

            # 5. Candidate is acceptable: Try selecting it and recurse

            # New state setup
            next_selection = current_selection.copy()
            next_selection[pkg_to_resolve] = candidate_version

            # Update order: Append dependencies of the newly selected package 
            # that are not yet in the order, in alphabetical order.
            newly_added_deps = set()
            if requires_map:
                for dep_name in requires_map.keys():
                    if dep_name not in current_selection and dep_name not in current_order:
                        newly_added_deps.add(dep_name)

            # Sort alphabetically and append to order
            deps_to_add = sorted(list(newly_added_deps))
            next_order = current_order + deps_to_add

            # Recurse
            result = backtrack(next_order, next_selection)

            if result is not None:
                # Success! Return the resolved set
                return result

        # 6. No candidate led to success (or there were no candidates)
        return None


    # --- Execution and Error Handling ---

    final_selection = backtrack(order, selected)

    if final_selection:
        # Success
        return final_selection
    else:
        # Failure: We need to find the specific failure point (the first package tried that failed)

        # To generate the precise error message, we must re-run the search path up to the point 
        # where the backtrack returned None, identifying the first failing package.

        # Since the structure of the DFS guarantees that the *first* package encountered 
        # in the initial search loop that yields None is the failure point, we reconstruct 
        # the state that led to this failure using a helper that tracks the path.

        def find_failure_path(current_order: List[str], current_selection: Dict[str, Version]) -> Tuple[Optional[str], List[Tuple[str, Range]]]:
            """
            Simulates the search to find the first package (pkg_name) and its constraints 
            that caused the failure (i.e., no acceptable candidate).
            Returns (pkg_name, constraints_list) or (None, []) if successful.
            """
            pkg_to_resolve = None
            for name in current_order:
                if name not in current_selection:
                    pkg_to_resolve = name
                    break

            if pkg_to_resolve is None:
                return None, [] # Success

            constraints = get_constraints(pkg_to_resolve, current_order, current_selection)
            candidates = index.versions(pkg_to_resolve)

            # Track candidates tried to check if *any* were acceptable
            candidates_tried = [] 

            for candidate_version in candidates:
                # Static Constraint Check
                is_acceptable = True
                for requirer_id, req_range in constraints:
                    if not req_range.contains(candidate_version):
                        is_acceptable = False
                        break

                if not is_acceptable:
                    candidates_tried.append((candidate_version, False, "Static Constraint Failure"))
                    continue

                # Dynamic Dependency Check
                requires_map = index.requirements(pkg_to_resolve, candidate_version)
                is_acceptable = True
                for dep_name, dep_range in requires_map.items():
                    if dep_name in current_selection:
                        selected_version = current_selection[dep_name]
                        if not dep_range.contains(selected_version):
                            is_acceptable = False
                            break

                if not is_acceptable:
                    candidates_tried.append((candidate_version, False, "Dependency Conflict"))
                    continue

                # If acceptable, recurse
                next_selection = current_selection.copy()
                next_selection[pkg_to_resolve] = candidate_version

                newly_added_deps = set()
                if requires_map:
                    for dep_name in requires_map.keys():
                        if dep_name not in current_selection and dep_name not in current_order:
                            newly_added_deps.add(dep_name)

                deps_to_add = sorted(list(newly_added_deps))
                next_order = current_order + deps_to_add

                # Recurse
                failure_pkg, failure_constraints = find_failure_path(next_order, next_selection)

                if failure_pkg is not None:
                    # Failure happened downstream. Propagate it up.
                    return failure_pkg, failure_constraints

            # If we reached here, *all* candidates failed or there were no candidates. This is the failure point.

            # --- Constructing the Error Explanation for pkg_to_resolve ---

            explanation_lines = [f"cannot resolve {pkg_to_resolve}"]

            # 2. Constraints
            for requirer_id, req_range in constraints:
                explanation_lines.append(f"  {requirer_id} requires {pkg_to_resolve} {str(req_range)}")

            # 3. Excluded Versions
            if not candidates:
                explanation_lines.append(f"  no versions of {pkg_to_resolve} are known")
            else:
                # Iterate through candidates newest first (they are already ordered)
                for candidate_version in candidates:

                    # Check static constraints again
                    static_failure = False
                    for requirer_id, req_range in constraints:
                        if not req_range.contains(candidate_version):
                            static_failure = True
                            break

                    if static_failure:
                        explanation_lines.append(f"  {pkg_to_resolve} {candidate_version} is excluded by the constraints")
                        continue

                    # Check dependency constraints
                    requires_map = index.requirements(pkg_to_resolve, candidate_version)
                    conflict_found = False

                    # Check dependencies in alphabetical order
                    sorted_deps = sorted(requires_map.keys())

                    for dep_name in sorted_deps:
                        dep_range = requires_map[dep_name]
                        if dep_name in current_selection:
                            selected_version = current_selection[dep_name]
                            if not dep_range.contains(selected_version):
                                explanation_lines.append(f"  {pkg_to_resolve} {candidate_version} requires {dep_name} {str(dep_range)}, but {dep_name} {selected_version} is selected")
                                conflict_found = True
                                break

                    if not conflict_found:
                         # If it survived all checks, it would have been selected.
                         # Since we are in the failure block, this implies this path didn't lead to a full resolution, 
                         # but the error reporting requires listing versions excluded by constraints.
                         # If it reaches here, it was acceptable *at this stage*, which shouldn't happen 
                         # if the backtrack returned None unless there were no further requirements to check.
                         # We only report exclusion if it failed a check above.
                         pass

            return pkg_to_resolve, constraints


        failure_pkg, _ = find_failure_path(order, {})

        if failure_pkg:
            # We need the constraints *at the moment* of failure for this package
            failure_constraints = get_constraints(failure_pkg, order, {})

            # Re-run the final construction logic locally for the error object
            explanation_lines = [f"cannot resolve {failure_pkg}"]

            for requirer_id, req_range in failure_constraints:
                explanation_lines.append(f"  {requirer_id} requires {failure_pkg} {str(req_range)}")

            candidates = index.versions(failure_pkg)

            if not candidates:
                explanation_lines.append(f"  no versions of {failure_pkg} are known")
            else:
                for candidate_version in candidates:
                    static_failure = False
                    for _, req_range in failure_constraints:
                        if not req_range.contains(candidate_version):
                            static_failure = True
                            break

                    if static_failure:
                        explanation_lines.append(f"  {failure_pkg} {candidate_version} is excluded by the constraints")
                        continue

                    requires_map = index.requirements(failure_pkg, candidate_version)
                    conflict_found = False
                    sorted_deps = sorted(requires_map.keys())

                    for dep_name in sorted_deps:
                        dep_range = requires_map[dep_name]
                        if dep_name in {} : # Since this is the initial failure point, selection is empty
                            pass 
                        elif not dep_range.contains(Version('0.0.0')): # Simplified check for the root failure
                             explanation_lines.append(f"  {failure_pkg} {candidate_version} requires {dep_name} {str(dep_range)}, but {dep_name} is selected")
                             conflict_found = True
                             break

                    if not conflict_found:
                        pass

            return ResolutionError(failure_pkg, "\n".join(explanation_lines))

        # Should be unreachable if logic is sound
        raise RuntimeError("Resolution failed but no error path could be determined.")
