        room_item_listings: Dict[str, set] = {rid: set() for rid in rooms_data}

        for room_id, room_data in rooms_data.items():
            if "name" not in room_data or "description" not in room_data:
                raise WorldError(f"Room '{room_id}' is missing 'name' or 'description'.")

            # Process Exits
