from typing import NamedTuple, Optional
import re

class ParseError(ValueError):
    def __str__(self):
        # This method will be overridden in the calling code if needed, 
        # but for the specific error messages requested, we rely on the calling context.
        pass

class Command(NamedTuple):
    verb: str
    arg: Optional[str]

def _normalize_line(line: str) -> str:
    """Removes articles after the first word."""
    if not line:
        return ""

    words = line.lower().split()
    if not words:
        return ""

    first_word = words[0]

    # Remove articles from subsequent words
    processed_words = [first_word]
    for word in words[1:]:
        if word not in ('the', 'a', 'an'):
            processed_words.append(word)

    return " ".join(processed_words)


def parse(line: str) -> Command:
    line = line.lower().strip()

    if not line:
        raise ParseError("Say something.")

    normalized_line = _normalize_line(line)
    parts = normalized_line.split()

    if not parts:
        raise ParseError("Say something.")

    verb = parts[0]
    args = parts[1:]

    # Handle single-word commands that might be aliases
    if verb in ('l', 'look', 'examine', 'x'):
        return Command('look', None)
    if verb in ('i', 'inventory', 'inv'):
        return Command('inventory', None)

    # Handle 'go' commands
    if verb == 'go':
        if not args:
            raise ParseError("Go where?")

        target = args[0]
        # Check if the target is a full direction or a single-letter abbreviation
        if len(target) == 1 and target in ('n', 's', 'e', 'w', 'u', 'd'):
            # Map single letter to full direction name
            abbr_map = {'n': 'north', 's': 'south', 'e': 'east', 'w': 'west', 'u': 'up', 'd': 'down'}
            full_dir = abbr_map[target]
            return Command('go', full_dir)

        # Check if the target is a full direction name
        if target in ('north', 'south', 'east', 'west', 'up', 'down'):
            return Command('go', target)

        # If it wasn't a recognized direction
        if args:
            raise ParseError(f'"{normalized_line}" is not a direction.')
        else:
             # This path should ideally be covered by the check above, but safety net
             raise ParseError("Go where?")

    # Handle 'take', 'get', 'drop'
    if verb in ('take', 'get', 'drop'):
        if not args:
            if verb == 'take':
                raise ParseError("Take what?")
            elif verb == 'drop':
                raise ParseError("Drop what?")
            # 'get' shouldn't happen if we rely on 'take'
            raise ParseError("Take what?") 

        # The argument is everything after the verb
        return Command(verb, " ".join(args))

    # Handle 'look X', 'examine X' (where X is the remaining argument)
    if verb in ('look', 'examine'):
        if not args:
            # This case should be handled by the alias 'l' above, but for explicit 'look'
            return Command('look', None)
        return Command('look', " ".join(args))

    # Unknown verb
    raise ParseError(f'I don\'t know the word "{verb}".')

