        """Returns a new list of the item ids now in that room, in order."""
        return self.room_item_states.get(room_id, [])[:]

    def _find_matching_item(self, arg: str) -> tuple[Optional[str], Optional[str]]:
        """
        Searches for an item matching the argument X.
        Returns (item_id, item_name) or (None, None).
        Searches room first, then inventory.
        """
        # 1. Search Room
        current_items = self.items_in(self.room_id)
        for item_id in current_items:
            item = self.world.items[item_id]
            if arg == item_id or arg == item.name.lower():
                return item_id, item.name

        # 2. Search Inventory
        for item_id in self.inventory:
            item = self.world.items[item_id]
            if arg == item_id or arg == item.name.lower():
                return item_id, item.name

        return None, None

    def do(self, line: str) -> str:
        """Runs one command and returns the response text."""
        try:
            cmd = self.world.parser(line)
        except ParseError as e:
            return str(e)

        # --- Handle Commands ---
        if cmd.verb == 'look':
            return self._handle_look(cmd.arg)
        elif cmd.verb == 'go':
            return self._handle_go(cmd.arg)
        elif cmd.verb == 'take':
            return self._handle_take(cmd.arg)
        elif cmd.verb == 'drop':
            return self._handle_drop(cmd.arg)
        elif cmd.verb == 'use':
            return self._handle_use(cmd.arg)
        elif cmd.verb == 'inventory':
            return self._handle_inventory()
        elif cmd.verb == 'score':
            return self._handle_score()

        return f"I don't know how to '{cmd.verb}' that."


    # --- Command Handlers ---

    def _handle_look(self, arg: Optional[str]) -> str:
        if arg is None:
            # Look (Room description)
            room = self.world.get_room(self.room_id)

            lines = [room.name, room.description]

            # Exits
            exit_details = []
            for direction, target in room.exits.items():
                if isinstance(target, str):
                    # Unlocked exit (simple room ID)
                    exit_details.append(direction)
                elif isinstance(target, dict):
                    # Locked exit
                    key_id = room.locks.get(direction)
                    is_unlocked = self.unlocked_exits[self.room_id].get(direction, False)
                    status = ""
                    if not is_unlocked:
                        status = " (locked)"
                    exit_details.append(f"{direction}{status}")

            if exit_details:
                lines.append(f"Exits: {', '.join(exit_details)}.")
            else:
                lines.append("Exits: none.")

            # Items
            room_items = self.items_in(self.room_id)
            if room_items:
                item_names = []
                for item_id in room_items:
                    item_names.append(self.world.items[item_id].name)
                lines.append(f"You see: {', '.join(item_names)}.")

            return "\n".join(lines)

        else:
            # Look X
            item_id, item_name = self._find_matching_item(arg)

            if item_id:
                # Item found (room or inventory)
                item = self.world.items[item_id]
                return f"{item.description}"
            else:
                return "You see no X here."

    def _handle_go(self, direction: str) -> str:
        room = self.world.get_room(self.room_id)

        if direction not in room.exits:
            return "You can't go that way."

        target = room.exits[direction]

        if isinstance(target, dict):
            # It's a locked exit
            if not self.unlocked_exits[self.room_id].get(direction, False):
                return f"The way {direction.upper()} is locked."
            # If unlocked, proceed as normal
            new_room_id = target["to"]
        else:
            # It's a direct room ID exit
            new_room_id = target

        # Movement successful
        if new_room_id != self.room_id:
            self.room_id = new_room_id
            self.moves += 1

            # Score for visiting new room
            if new_room_id not in self.visited_rooms:
                self.score += 10
                self.visited_rooms.add(new_room_id)

            # Return the look text of the new room
            return self.do("look") 

        return "You are already there."

    def _handle_take(self, arg: str) -> str:
        item_id, item_name = self._find_matching_item(arg)

        if not item_id:
            return "You see no X here."

        # Check if the item is in the room
        if item_id in self.items_in(self.room_id):
            item = self.world.items[item_id]

            if not item.portable:
                return f"You can't take the {item.name}."

            # Scoring: Check if treasure was awarded before
            if item.treasure > 0 and item_id not in self.scored_items:
                self.score += item.treasure
                self.scored_items.add(item_id)

            # Take the item
            current_room_items = self.items_in(self.room_id)
            new_room_items = [i for i in current_room_items if i != item_id]
            self.room_item_states[self.room_id] = new_room_items

            # Add to inventory
            self.inventory.append(item_id)
            return f"Taken: {item.name}."

        # Check if the item is in inventory
        elif item_id in self.inventory:
            return f"You already have the {item_name}."

        return "Error during take action."

    def _handle_drop(self, arg: str) -> str:
        item_id, item_name = self._find_matching_item(arg)

        if not item_id:
            return "You aren't carrying that."

        # Check if the item is in inventory
        if item_id not in self.inventory:
            return "You aren't carrying that."

        # Drop the item
        self.inventory.remove(item_id)

        # Add to room list (at the end)
        self.room_item_states[self.room_id].append(item_id)

        return f"Dropped: {item_name}."

    def _handle_use(self, arg: str) -> str:
        item_id, item_name = self._find_matching_item(arg)

        if not item_id:
            return "You aren't carrying that."

        # Check if the item is a key that can unlock something in the current room
        unlocked_directions: List[str] = []
        key_found = False

        room = self.world.get_room(self.room_id)

        for direction, target in room.exits.items():
            if isinstance(target, dict) and room.locks.get(direction) == item_id:
                # This is a locked exit that uses the current item as a key
                if not self.unlocked_exits[self.room_id].get(direction, False):
                    unlocked_directions.append(direction)
                    key_found = True

        if key_found:
            # Unlock the exit(s)
            for direction in unlocked_directions:
                self.unlocked_exits[self.room_id][direction] = True

            # Sort directions as required by prompt
            unlocked_directions.sort(key=lambda d: DIRECTIONS.index(d))
            return f"Unlocked: {', '.join(unlocked_directions)}."
        else:
            return f"Nothing here to use the {item_name} on."


    def _handle_inventory(self) -> str:
        if not self.inventory:
            return "You are carrying nothing."

        item_names = []
        for item_id in self.inventory:
            item_names.append(self.world.items[item_id].name)

        return f"You are carrying: {', '.join(item_names)}."

    def _handle_score(self) -> str:
        return f"Your score is {self.score}."


    # --- Saving/Loading ---

    def save(self) -> str:
        """Returns a JSON string of the current game state (Version 2)."""

        # Format room items state for JSON serialization: {room_id: [item_id, ...]}
        serializable_room_items: Dict[str, List[str]] = {}
        for room_id, items_list in self.room_item_states.items():
            serializable_room_items[room_id] = items_list[:]

        # Format unlocked exits state for JSON serialization: [[room_id, direction], ...]
        unlocked_list: List[List[str]] = []
        for room_id, directions_map in self.unlocked_exits.items():
            for direction, is_unlocked in directions_map.items():
                if is_unlocked:
                    unlocked_list.append([room_id, direction])

        unlocked_list.sort()

        state = {
            "version": 2,
            "room": self.room_id,
            "inventory": self.inventory[:],
            "items": serializable_room_items,
            "moves": self.moves,
            "score": self.score,
            "unlocked": unlocked_list,
            "visited": sorted(list(self.visited_rooms)),
            "scored": sorted(list(self.scored_items))
        }
        return json.dumps(state)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        """Loads a game state from a JSON string (V1 or V2)."""
        try:
            data: Dict[str, Any] = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Text is not valid JSON.")

        if not isinstance(data, dict):
            raise SaveError("JSON content is not an object.")

        version = data.get("version")

        if version is None:
            raise SaveError("Save file missing 'version' key.")

        if version > 2:
            raise SaveError(f"Unsupported save file version: {version}")

        # --- Base Validation (Common to V1 and V2) ---

        # Base required keys
        base_required_keys = ["room", "inventory", "items", "moves"]
        for key in base_required_keys:
            if key not in data:
                raise SaveError(f"Missing required base key in save data: '{key}'.")

        try:
            start_room_id = data["room"]
            if start_room_id not in world.rooms:
                raise SaveError(f"Saved room '{start_room_id}' does not exist in world.")

            moves = data["moves"]
            if not isinstance(moves, int) or moves < 0:
                raise SaveError("Moves count is not a non-negative integer.")
        except Exception as e:
            raise SaveError(f"Validation error during initial load: {e}")

        # Item/Room integrity checks
        inventory_ids = set(data["inventory"])

        # Check inventory items exist
        for item_id in inventory_ids:
            if item_id not in world.items:
                raise SaveError(f"Inventory contains unknown item ID '{item_id}'.")

        # --- Version Specific Loading ---

        if version == 1:
            # V1 State Initialization
            game = cls(world)
            game.room_id = data["room"]
            game.inventory = data["inventory"][:]
            game.moves = data["moves"]
            game.score = 0
            game.visited_rooms = {data["room"]}
            game.scored_items = set()
            # Locks remain locked, unlocked_exits initialized in __init__

        elif version == 2:
            # V2 State Loading
            required_v2_keys = ["unlocked", "visited", "scored", "score"]
            for key in required_v2_keys:
                if key not in data:
                    raise SaveError(f"Missing required V2 key: '{key}'.")

            game = cls(world)

            # 1. Load simple fields
            game.room_id = data["room"]
            game.inventory = data["inventory"][:]
            game.moves = data["moves"]
            game.score = data["score"]
            game.visited_rooms = set(data["visited"])
            game.scored_items = set(data["scored"])

            # 2. Load Room Items State
            loaded_room_items_state: Dict[str, List[str]] = {}
            loaded_unlocked_exits: Dict[str, Dict[str, bool]] = {}
            all_listed_ids = set()

            for room_id, item_list in data["items"].items():
                if room_id not in world.rooms:
                    raise SaveError(f"Saved room key '{room_id}' does not exist in world.")

                loaded_items = []
                for item_id in item_list:
                    if item_id not in world.items:
                        raise SaveError(f"Room '{room_id}' lists unknown item ID '{item_id}'.")

                    if item_id in inventory_ids:
                        raise SaveError(f"Item ID '{item_id}' found in both inventory and room '{room_id}'.")

                    if item_id in all_listed_ids:
                        raise SaveError(f"Item ID '{item_id}' listed more than once in room '{room_id}'.")

                    all_listed_ids.add(item_id)
                    loaded_items.append(item_id)

                loaded_room_items_state[room_id] = loaded_items

            # 3. Load Unlocked Exits
            for room_id, direction in data["unlocked"]:
                if room_id not in world.rooms:
                     raise SaveError(f"Unlocked record refers to unknown room ID '{room_id}'.")

                room = world.get_room(room_id)

                if direction not in room.exits:
                    raise SaveError(f"Unlocked direction '{direction}' does not exist in room '{room_id}'.")

                target = room.exits[direction]
                if not isinstance(target, dict) or room.locks.get(direction) != target.get("key"):
                    # Ensure it was actually a lock and the key matches the world definition
                    raise SaveError(f"Unlocked entry for {room_id}/{direction} is not a valid locked exit in the current world.")

                if room_id not in loaded_unlocked_exits:
                    loaded_unlocked_exits[room_id] = {}

                loaded_unlocked_exits[room_id][direction] = True

            game.room_item_states = loaded_room_items_state
            game.unlocked_exits = loaded_unlocked_exits

        else:
            # Should be unreachable due to version check above
            raise SaveError("Invalid version encountered during loading.")

        # Final verification step: ensure all items referenced in state exist in world
        all_referenced_items = set(game.inventory) | set(item_id for items in game.room_item_states.values() for item_id in items)
        for item_id in all_referenced_items:
            if item_id not in world.items:
                raise SaveError(f"State references unknown item ID '{item_id}'.")

        return game
