# vfs/paths.py
import os
from typing import Tuple

def normalize(path: str, cwd: str = '/') -> str:
    """
    Returns an absolute path with no . or .. parts, no repeated /, and no trailing / 
    (except the root, /). Relative paths are taken relative to cwd.
    """
    if not path:
        raise ValueError("Path cannot be empty")

    # 1. Convert to absolute path based on cwd
    if os.path.isabs(path):
        abs_path = path
    else:
        # Ensure cwd is absolute and normalized before joining
        normalized_cwd = normalize(cwd)
        abs_path = os.path.join(normalized_cwd, path)

    # 2. Normalize using os.path.normpath and then fix specific VFS rules
    # os.path.normpath handles /./ and /../ to some extent, but we need strict POSIX behavior.

    # Simple component-wise processing for strict POSIX behavior
    parts = []
    # Start with components of the absolute path derived from cwd/input
    # We use os.path.split/os.path.normpath temporarily to get a base path, 
    # then process manually to strictly enforce VFS rules (especially root handling).

    # Normalize the OS path first to handle OS specific separators/redundancies, then convert to POSIX logic
    temp_path = os.path.normpath(abs_path.replace(os.sep, '/'))

    # Ensure it starts with a slash if it was absolute
    if not temp_path.startswith('/'):
        temp_path = '/' + temp_path

    # Now, process components strictly
    components = [p for p in temp_path.split('/') if p]

    result_parts = []
    for part in components:
        if part == '..':
            if result_parts:
                result_parts.pop()
        elif part == '.':
            continue
        else:
            result_parts.append(part)

    # Rebuild the path
    normalized_path = '/' + '/'.join(result_parts)

    # Handle root edge case: if result_parts is empty, it must be '/'
    if not result_parts:
        return '/'

    # Ensure no trailing slash (unless it is '/')
    return normalized_path.rstrip('/') if normalized_path != '/' else '/'


def join(base: str, *parts: str) -> str:
    """
    Joins paths like posixpath.join. A part starting with / starts over. Returns normalized.
    """
    if not base:
        # If base is empty, treat the first part as the root if it starts with /
        if parts and parts[0].startswith('/'):
            return normalize(parts[0])
        return normalize(*parts) # Will handle the case where all parts are relative

    all_parts = []
    # Split the base path into components
    base_components = [p for p in base.split('/') if p]

    for part in parts:
        if part.startswith('/'):
            # Starts over
            all_parts = [p for p in part.split('/') if p]
        else:
            all_parts.extend([p for p in part.split('/') if p])

    # Reconstruct and normalize
    return normalize('/' + '/'.join(all_parts))


def split(path: str) -> Tuple[str, str]:
    """
    Takes an absolute normalised path and returns (parent, name).
    split('/') is ('/', '').
    """
    if path == '/':
        return ('/', '')

    # Remove trailing slash if present (shouldn't happen if input is normalized, but for safety)
    if path.endswith('/') and path != '/':
        path = path[:-1]

    last_slash = path.rfind('/')

    if last_slash == 0:
        # e.g., /name -> parent is /
        return ('/', path[1:])
    elif last_slash == -1:
        # Should only happen if path is something invalid, but if we assume absolute normalized, 
        # this case is unlikely unless the path is just a name without a leading slash.
        # For strict absolute normalized path, this means path must be '/' handled above.
        return ('/', path) # Treating the whole thing as the name if no slash found (e.g., if input was somehow just 'file')
    else:
        parent = path[:last_slash]
        name = path[last_slash+1:]
        return (parent, name)


def is_within(path: str, ancestor: str) -> bool:
    """
    Tells whether the normalised path is ancestor itself or lies below it. 
    /ab is not within /a.
    """
    # Both paths must be normalized absolute paths starting with /
    if not (path.startswith('/') and ancestor.startswith('/')):
        # Should not happen if inputs are properly normalized
        return False

    if path == ancestor:
        return True

    # Check if path starts with ancestor + '/'
    # Example: ancestor=/a, path=/a/b. Does /a/b start with /a/? Yes.
    # Example: ancestor=/a, path=/ab. Does /ab start with /a/? Yes, but this is NOT within.

    ancestor_len = len(ancestor)

    # We need to check that the next character after the ancestor prefix is a '/'
    if path.startswith(ancestor):
        # If they are equal, we already returned True
        if len(path) > ancestor_len and path[ancestor_len] == '/':
            return True

    return False
