# --- Errors ---

class FSError(Exception):
    """Base class for all VFS errors."""
    def __init__(self, path: str):
        self.path = path
        super().__init__(self._error_message())

    def _error_message(self) -> str:
        # Default implementation ensures str(error) is the normalized path
        return self.path

class NotFound(FSError):
    pass

class AlreadyExists(FSError):
    pass

class NotADirectory(FSError):
    pass

class IsADirectory(FSError):
    pass

class InvalidOperation(FSError):
    pass

# --- FileSystem ---

class FileSystem:
    def __init__(self):
        # Structure: {path: {type: 'file'|'dir', content: str | None}}
        # Root directory is always present and is a directory.
        self.data: Dict[str, Dict[str, Any]] = {
            '/': {'type': 'dir', 'content': None}
        }
        self.cwd: str = '/'

    def _resolve_path(self, path: str, absolute_required: bool = False) -> str:
        """Resolves a potentially relative path to a normalized absolute path."""
        if not path:
            raise ValueError("Path cannot be empty")

        # Use paths.normalize which handles the core logic
        from .paths import normalize

        if absolute_required:
            return normalize(path, cwd='/')
        else:
            return normalize(path, cwd=self.cwd)

    def _get_entry_metadata(self, path: str) -> Tuple[Dict[str, Any] | None, str | None]:
        """Retrieves metadata for a path. Returns (metadata, name_only)."""
        if path not in self.data:
            return None, None

        # Get the final component name
        from .paths import split
        _, name = split(path)
        return self.data[path], name

    def exists(self, path: str) -> bool:
        try:
            abs_path = self._resolve_path(path)
            return abs_path in self.data
        except ValueError:
            return False

    def is_dir(self, path: str) -> bool:
        try:
            abs_path = self._resolve_path(path)
            metadata, _ = self._get_entry_metadata(abs_path)
            return metadata is not None and metadata['type'] == 'dir'
        except ValueError:
            return False

    def pwd(self) -> str:
        return self.cwd

    def cd(self, path: str):
        """Changes directory."""
        try:
            target_path = self._resolve_path(path)
            metadata, _ = self._get_entry_metadata(target_path)

            if not metadata:
                raise NotFound(target_path)

            if metadata['type'] == 'file':
                raise NotADirectory(target_path)

            self.cwd = target_path

        except ValueError as e:
            # Catch empty path error
            raise NotFound(path)
        except FSError:
            # Re-raise existing VFS errors
            raise
        except Exception:
            # Catch unexpected issues during resolution
            raise NotFound(path)


    def mkdir(self, path: str, parents: bool = False):
