            if not parents:
                parent_path, name = self._resolve_path(path)
                parent_path = parent_path.rsplit('/', 1)[0] or '/'

                if parent_path not in self.data or self.data[parent_path]['type'] != 'dir':
                    raise NotFound(parent_path)

            # Create directories recursively if parents=True and they don't exist
            current_path = target_path
            while current_path not in self.data:
                # Find parent path
                parent_path, _ = self._resolve_path(current_path)
                parent_path = parent_path.rsplit('/', 1)[0] or '/'

                if parent_path not in self.data or self.data[parent_path]['type'] != 'dir':
                    raise NotFound(parent_path)

                current_path = parent_path

            # If we reached here and the path isn't in data, create it
            if target_path not in self.data:
                 self.data[target_path] = {'type': 'dir', 'content': None}

