            if target_path in self.data and self.data[target_path]['type'] == 'dir':
                raise IsADirectory(target_path)

            # Handle file creation/overwriting
            if target_path not in self.data:
                self.data[target_path] = {'type': 'file', 'content': ""}

            metadata = self.data[target_path]

            if append and metadata['type'] != 'file':
                 # Should be caught by directory check, but safety net
                 raise IsADirectory(target_path)

            current_content = metadata['content'] if metadata['content'] is not None else ""

            if append:
                self.data[target_path]['content'] = current_content + text
            else:
