            target_path = self._resolve_path(path)
            metadata, _ = self._get_entry_metadata(target_path)

            if not metadata:
                raise NotFound(target_path)

            if metadata['type'] == 'dir':
                raise IsADirectory(target_path)

            content = metadata['content']
            if content is None: # Should not happen for file type
                return ""
            return content

        except ValueError as e:
            raise NotFound(path)
        except FSError:
            raise
        except Exception:
            raise NotFound(path)


    def ls(self, path: str = '.'):
        """Lists directory contents or returns file name."""
        try:
            abs_path = self._resolve_path(path)
            metadata, _ = self._get_entry_metadata(abs_path)

            if not metadata:
                raise NotFound(abs_path)

            if metadata['type'] == 'file':
                return [self._get_entry_metadata(abs_path)[1]] # Returns name only

            # Directory listing
            contents = []
            for p in self.data:
                if p.startswith(abs_path + '/') and p != abs_path:
                    # Ensure we only list immediate children
                    if p.count('/') == abs_path.count('/') + 1:
                        _, name = self._get_entry_metadata(p)
                        contents.append(name)

            return sorted(contents)


        except ValueError as e:
