# vfs/shell.py
import shlex
import sys
import io
from typing import Tuple, Optional

from .fs import FileSystem, FSError
from .paths import join, normalize

class Shell:
    def __init__(self, fs: Optional[FileSystem] = None):
        self.fs = fs if fs is not None else FileSystem()

    def _execute_command(self, line_num: int, tokens: list, fs: FileSystem) -> Tuple[str, int]:
        """Executes a single parsed line of commands."""
        if not tokens:
            return "", 0

        command = tokens[0]
        args = tokens[1:]
        output = ""
        status = 0

        # --- PWD ---
        if command == "pwd":
            output = fs.pwd() + "\n"
            return output, 0

        # --- CD ---
        elif command == "cd":
            if not args:
                # cd without arguments usually goes to home, but here we default to root for simplicity
                try:
                    fs.cd('/')
                except FSError:
                    return f"line {line_num}: cd: ErrorClassName: / (Failed to change to root)\n", 1 # Should not happen
            else:
                try:
                    fs.cd(args[0])
                except FSError as e:
                    output = f"line {line_num}: cd: {e.__class__.__name__}: {str(e)}\n"
                    status = 1
                except Exception:
                    output = f"line {line_num}: cd: usage\n"
                    status = 2
            return output, status

        # --- MKDIR ---
        elif command == "mkdir":
            parents = False
            if args and args[0] in ('-p', '-r'): # -r is not specified, so we only check -p
                parents = args[0] == "-p"
                args = args[1:]

            if not args:
                return f"line {line_num}: mkdir: usage\n", 2

            paths_to_create = args

            for path in paths_to_create:
                try:
                    fs.mkdir(path, parents=parents)
                except FSError as e:
                    output = f"line {line_num}: mkdir: {e.__class__.__name__}: {str(e)}\n"
                    status = 1
                    break
                except Exception:
                    output = f"line {line_num}: mkdir: usage\n"
                    status = 2
                    break
            return output, status

        # --- LS ---
        elif command == "ls":
            if not args:
                args = ['.'] # Default to current directory

            output = ""
            for path in args:
                try:
                    result = fs.ls(path)
                    if isinstance(result, list):
                        for item in result:
                            output += item + "\n"
                    else:
                         # This path suggests ls returned something unexpected for a file
                         output += "Error Listing\n"
                except FSError as e:
                    output = f"line {line_num}: ls: {e.__class__.__name__}: {str(e)}\n"
                    status = 1
                    break
                except Exception:
                    output = f"line {line_num}: ls: usage\n"
                    status = 2
                    break
            return output, status

        # --- RM ---
        elif command == "rm":
            recursive = False
            args_processed = []

            if args and args[0] in ('-r', '-R'): # Assuming -r is used for recursive
                recursive = True
                args_processed.append(args[0])
                args_processed.append(args[1:])
            else:
                args_processed.append(args)

            paths_to_remove = args_processed[0] if isinstance(args_processed, list) else args_processed

            output = ""
            for path in paths_to_remove:
                try:
                    fs.rm(path, recursive=recursive)
                except FSError as e:
                    output = f"line {line_num}: rm: {e.__class__.__name__}: {str(e)}\n"
                    status = 1
                    break
                except Exception:
                    output = f"line {line_num}: rm: usage\n"
                    status = 2
                    break
            return output, status

        # --- MV ---
        elif command == "mv":
            if len(args) != 2:
                return f"line {line_num}: mv: usage\n", 2
            src, dst = args
            try:
                fs.mv(src, dst)
            except FSError as e:
                output = f"line {line_num}: mv: {e.__class__.__name__}: {str(e)}\n"
                status = 1
            except Exception:
                output = f"line {line_num}: mv: usage\n"
                status = 2
            return output, status

        # --- WRITE ---
        elif command == "write":
            if len(args) < 1:
                return f"line {line_num}: write: usage\n", 2
            path = args[0]
            content_args = args[1:]

            # Join words with single spaces, plus newline
            text = " ".join(content_args) + "\n"

            try:
                fs.write(path, text, append=False)
            except FSError as e:
                output = f"line {line_num}: write: {e.__class__.__name__}: {str(e)}\n"
                status = 1
            except Exception:
                output = f"line {line_num}: write: usage\n"
                status = 2
            return output, status

        # --- APPEND ---
        elif command == "append":
            if len(args) < 1:
                return f"line {line_num}: append: usage\n", 2
            path = args[0]
            content_args = args[1:]

            # Join words with single spaces, plus newline
            text = " ".join(content_args) + "\n"

            try:
                fs.write(path, text, append=True)
            except FSError as e:
                output = f"line {line_num}: append: {e.__class__.__name__}: {str(e)}\n"
                status = 1
            except Exception:
                output = f"line {line_num}: append: usage\n"
                status = 2
            return output, status

        # --- CAT ---
        elif command == "cat":
            if not args:
                return f"line {line_num}: cat: usage\n", 2

            output = ""
            for path in args:
                try:
                    text = fs.read(path)
                    output += text
                except FSError as e:
                    output = f"line {line_num}: cat: {e.__class__.__name__}: {str(e)}\n"
                    status = 1
                    break
                except Exception:
                    output = f"line {line_num}: cat: usage\n"
                    status = 2
                    break
            return output, status

        # --- FIND ---
        elif command == "find":
            path = args[0] if args and not args[0].startswith('-') else '.'
            pattern = '*'

            # Simple flag parsing for find
            if args:
                for i, arg in enumerate(args):
                    if arg.startswith('-'):
                        if arg == '-name':
                            if i + 1 < len(args):
                                pattern = args[i+1]
                            else:
                                return f"line {line_num}: find: usage\n", 2
                            continue
                        else:
                            return f"line {line_num}: find: usage\n", 2

                # If pattern wasn't explicitly set, check the last argument if it's not a flag
                if pattern == '*' and len(args) > 1 and not args[-1].startswith('-'):
                    # This case is ambiguous; following the spec strictly: 
                    # find [PATH] [-name PATTERN]
                    # If we see something else, it's probably an extra positional argument, treat as usage error if pattern is still '*'
                    pass

            try:
                results = fs.find(path, pattern)
                output = "\n".join(results) + "\n"
            except FSError as e:
                output = f"line {line_num}: find: {e.__class__.__name__}: {str(e)}\n"
                status = 1
            except Exception:
                output = f"line {line_num}: find: usage\n"
                status = 2
            return output, status


        # --- Unknown Command ---
        else:
            return f"line {line_num}: {command}: unknown command\n", 0 # Status 0 if command is recognized but unsupported? No, spec implies unknown command status 1, but list suggests 2. Using 0 as a safe default unless error implies failure. Let's use 2 as per error table for unknown command.
            # Re-reading: "an unknown command adds line N: COMMAND: unknown command and \n, and the status is 1"
            return f"line {line_num}: {command}: unknown command\n", 1

    def run(self, script_path: str) -> Tuple[str, int]:
        """Reads and executes the script file."""
        try:
            with open(script_path, 'r') as f:
                script_content = f.read()
        except FileNotFoundError:
            return f"error: Script file not found: {script_path}", 2
        except Exception:
            return f"error: Could not read script file: {script_path}", 2

        lines = script_content.splitlines()
        shell = self

        total_output = ""
        exit_status = 0

        for i, line in enumerate(lines):
            line_num = i + 1

            # Skip empty lines and comments
            stripped_line = line.strip()
            if not stripped_line or stripped_line.startswith('#'):
                continue

            try:
                # Use shlex.split to handle quotes correctly
                tokens = shlex.split(stripped_line)
            except ValueError:
                # Quoting error
                command = stripped_line.split()[0] if stripped_line else "UNKNOWN"
                output = f"line {line_num}: {command}: usage\n"
                return total_output + output, 2

            # Execute
            line_output, line_status = shell._execute_command(line_num, tokens, self.fs)
            total_output += line_output

            # Stop on first FSError (status 1)
            if line_status == 1:
                exit_status = 1
                break
            # Stop on usage error (status 2)
            elif line_status == 2:
                exit_status = 2
                break

        return total_output, exit_status

# Required for running via python -m vfs.shell SCRIPT
def main():
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python -m vfs.shell <script_file>\n")
        sys.exit(2)

    script_path = sys.argv[1]
    shell = Shell()
    output, status = shell.run(script_path)

    # Print output to stdout
    sys.stdout.write(output)

    # Exit with the determined status
    sys.exit(status)

if __name__ == '__main__':
    # This block is only for running the module directly via 'python -m vfs.shell'
    main()
